// ---- Seed roles ---------------------------------------------------------
// Roles saved before the China-only dashboard split may only have
// "dashboard.view". Give them the China sections they already had access to.
const DASHBOARD_CHINA_HINTS = [
  "tk.view",
  "inbound.view",
  "outbound.view",
  "shipment.view",
  "lookup.view",
  "arrival.view",
  "wh_arrived.view",
  "kh_warehouse.view",
  "sorting.view",
  "delivery.view",
  "exception.view",
];
function withDashboardScopes(perms) {
  if (!perms.includes("dashboard.view")) return perms;
  if (perms.includes("dashboard.china") || perms.includes("dashboard.air"))
    return perms;
  const air = perms.includes("air_order.view");
  const china = DASHBOARD_CHINA_HINTS.some((k) => perms.includes(k)) || !air;
  return [
    ...perms,
    ...(china ? ["dashboard.china"] : []),
    ...(air ? ["dashboard.air"] : []),
  ];
}

function normalizeRole(r) {
  return {
    name: r.name,
    level: r.level === undefined || r.level === "" ? null : r.level,
    scope: ROLE_SCOPES.includes(r.scope) ? r.scope : "DEPARTMENT",
    status: r.status === "Inactive" ? "Inactive" : "Active",
    description: r.description || "",
    system: !!r.system,
    legacy: !!r.legacy,
    permissions: Array.isArray(r.permissions)
      ? withDashboardScopes(
          r.permissions.filter(
            (k) => PERMISSION_LABEL[k] && !SUPER_ONLY.has(k),
          ),
        )
      : [],
  };
}

