//   create index if not exists status_history_tk_idx on status_history(tk);
//
//   -- Storage: create a public bucket named "cargo-photos", plus RLS
//   -- policies that let staff insert/select on cargo_photos.

const SIZE_PRICES = { S: 0.5, M: 1, L: 2 };
const CBM_RATES = { Normal: 180, Sensitive: 220 };
const CARGO_TYPES = ["Normal", "Sensitive"];
const SIZE_CHOICES = ["S", "M", "L", "OVER"];
const PHOTO_CATEGORIES = [
  "Product Front",
  "Product Back",
  "Product Label / Barcode",
  "Package",
  "Damage / Exception",
];
const INBOUND_STATUSES = [
  "Pending",
  "Received",
  "Measuring",
  "Checked",
  "Ready for Shipment",
  "Exception",
];
const CHINA_WAREHOUSES = [
  { code: "CN-GZ-01", name: "Guangzhou" },
  { code: "CN-YW-01", name: "Yiwu" },
  { code: "CN-SZ-01", name: "Shenzhen" },
];
// Who may create/scan TKs, measure cargo and move them to Outbound Origin.
// TK_CREATE_ROLES → permission "tk.manage_inbound" (see lib/permissions.js)
// Who may override the automatically calculated freight fee.
// FREIGHT_OVERRIDE_ROLES → permission "tk.freight_override" (see lib/permissions.js)
// Who may re-measure (size / weight) a TK at the Cambodia warehouse when
// the China side entered it wrongly.
// REMEASURE_ROLES → permission "tk.remeasure" (see lib/permissions.js)

const LABEL_CLS =
  "block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1";
const INPUT_CLS =
  "w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue";

function makeId() {
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
}

function money(n) {
  const v = Number(n);
  return Number.isFinite(v) ? `$${v.toFixed(2)}` : "—";
}

// Like money(), but a negative balance reads "−$5.00" instead of "$-5.00".
function moneyS(n) {
  const v = Number(n);
  if (!Number.isFinite(v)) return "—";
  return v < 0 ? `−$${Math.abs(v).toFixed(2)}` : `$${v.toFixed(2)}`;
}

function sizeLabel(size) {
  if (!size) return "—";
  return size === "OVER" ? "Dimension Based (> L)" : size;
}

// CBM = L × W × H (cm) / 1,000,000. Keep full precision for pricing;
// round only when displaying CBM to the user.
function computeCbm(length, width, height) {
  const l = Number(length);
  const w = Number(width);
  const h = Number(height);
  if (!(l > 0 && w > 0 && h > 0)) return null;
  return (l * w * h) / 1000000;
}

// S/M/L → fixed price. "OVER" (> L) → CBM × rate for the cargo type.
function calcFreight({
  cargoType,
  sizeClass,
  packageType,
  length,
  width,
  height,
  weight,
}) {
  const cbm = computeCbm(length, width, height);
  const policy =
    getSystemSettings().shipping || DEFAULT_SYSTEM_SETTINGS.shipping;
  const effectivePackageType =
    packageType || (sizeClass === "OVER" ? "dimension_based" : "small_package");

  // Small Package is independent from Normal/Sensitive. S/M/L are fixed prices.
  if (effectivePackageType === "small_package") {
    if (!["S", "M", "L"].includes(sizeClass))
      return { ok: false, message: "Please select Size S, M or L", cbm };
    const rate = Number(policy.sizeRates?.[sizeClass] || 0);
    if (!(rate >= 0))
      return {
        ok: false,
        message: "Small Package size rate is not configured",
        cbm,
      };
    return {
      ok: true,
      method: "Fixed Size",
      rate,
      cbm: null,
      fee: Math.round(rate * 100) / 100,
      policyCurrency: policy.currency || "USD",
      cargoType: null,
      packageType: "small_package",
    };
  }

  if (effectivePackageType !== "dimension_based")
    return { ok: false, message: "Please select a Package Type", cbm };
  if (!cargoType)
    return { ok: false, message: "Please select Normal or Sensitive", cbm };
  if (cbm == null)
    return {
      ok: false,
      message: "Please enter Length, Width and Height as positive numbers",
      cbm,
    };

  const type = cargoType === "Sensitive" ? "Sensitive" : "Normal";
  const cargoPolicy =
    (policy.cargoPolicies || DEFAULT_CARGO_POLICIES)[type] ||
    DEFAULT_CARGO_POLICIES[type];
  const rate = Number(cargoPolicy.cbmRate || 0);
  if (!(rate > 0))
    return { ok: false, message: `${type} CBM rate is not configured`, cbm };

  // Dimension Based: actual CBM × the selected cargo-type rate.
  // 190/220 are rates per CBM, never size thresholds.
  // Minimum Freight is a SPECIAL RULE and is OFF by default.
  const rawFee = cbm * rate;
  const minimumFreight = Number(cargoPolicy.minimumFreight || 0);
  const applyMinimumFreight = cargoPolicy.applyMinimumFreight === true;
  const fee = applyMinimumFreight ? Math.max(rawFee, minimumFreight) : rawFee;
  return {
    ok: true,
    method: "CBM",
    rate,
    cbm,
    rawFee: Math.round(rawFee * 100) / 100,
    minimumFreight,
    applyMinimumFreight,
    fee: Math.round(fee * 100) / 100,
    policyCurrency: policy.currency || "USD",
    cargoType: type,
    packageType: "dimension_based",
  };
}

function rateLabel(pkg) {
  if (pkg.rate === undefined || pkg.rate === null || pkg.rate === "")
    return "—";
  return pkg.pricing_method === "CBM"
    ? `${money(pkg.rate).replace(".00", "")} / CBM`
    : money(pkg.rate);
}

// ---- Shipping fee (payment) status --------------------------------------
// total = freight_fee, paid = paid_amount (0 until a payment is recorded),
// due = total - paid. Shown on every TK list as "Due $X / Shipping fee",
// "Paid $X" or "—" when the TK has no fee yet.
function shippingFeeOf(p) {
  const total = Number(p?.freight_fee);
  if (
    p?.freight_fee === undefined ||
    p?.freight_fee === null ||
    p?.freight_fee === "" ||
    !Number.isFinite(total)
  )
    return { state: "none", total: null, paid: 0, due: 0 };
  const paid = Math.max(Number(p?.paid_amount) || 0, 0);
  const due = Math.max(Math.round((total - paid) * 100) / 100, 0);
  return { state: due > 0 ? "due" : "paid", total, paid, due };
}

// Cambodia shipping fee of a CN order's TKs. It is shown once the TK has been
// confirmed at Arrived Destination (or later) and has a freight fee.
const CN_SHIP_FEE_STAGES = [
  "Arrived Destination",
  "Shipping To Branch",
  "Inbound Warehouse",
  "Completed",
];
function cnShippingFeeRows(tks) {
  return (tks || [])
    .filter(
      (x) =>
        x?.tk &&
        CN_SHIP_FEE_STAGES.includes(
          String(x.tk_status || x.status || "").trim(),
        ),
    )
    .map((x) => ({ tk: x.tk, fee: shippingFeeOf(x) }))
    .filter((x) => x.fee.state !== "none" && x.fee.total > 0);
}

function shippingFeeText(p) {
  const f = shippingFeeOf(p);
  if (f.state === "none") return "—";
  return f.state === "due" ? `Due ${money(f.due)}` : `Paid ${money(f.total)}`;
}

function ShippingFeeCell({ row }) {
  const f = shippingFeeOf(row);
  if (f.state === "none") return <span className="text-ink-600/40">—</span>;
  if (f.state === "paid")
    return (
      <div className="leading-tight">
        <div className="font-semibold text-signal-teal">{money(f.total)}</div>
        <div className="text-[11px] text-signal-teal/80">Paid</div>
      </div>
    );
  return (
    <div className="leading-tight">
      <div className="font-semibold text-[#B87415]">{money(f.due)}</div>
      <div className="text-[11px] text-ink-600/55">Shipping fee</div>
    </div>
  );
}

const SHIPPING_FEE_COL = {
  key: "shipping_fee",
  label: "Shipping Fee",
  render: (row) => <ShippingFeeCell row={row} />,
};

function outboundStatusOf(p) {
  return p.status === "Inbound Origin" || !p.status ? "Not Shipped" : p.status;
}

// ------------------------------------------------------------
// Date helpers: "Created" cell + date-range filter (local time zone)
// ------------------------------------------------------------
const EMPTY_DATE_RANGE = { preset: "", from: "", to: "" };
const DATE_PRESETS = [
  { key: "today", label: "Today" },
  { key: "yesterday", label: "Yesterday" },
  { key: "last7", label: "Last 7 days" },
  { key: "last30", label: "Last 30 days" },
  { key: "thisMonth", label: "This month" },
  { key: "lastMonth", label: "Last month" },
];

// "YYYY-MM-DD" in the viewer's LOCAL time zone (slice(0,10) of an ISO string
// is UTC, which would shift rows registered 12am-7am in Cambodia by a day).
function localDayKey(input) {
  const d = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) return "";
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// Start of a local calendar day ("YYYY-MM-DD") as an ISO instant, optionally
// shifted by whole days — used for server-side `>= start` / `< next day` ranges.
function dayStartISO(key, plusDays = 0) {
  const [y, m, d] = String(key).split("-").map(Number);
  return new Date(y, m - 1, d + plusDays).toISOString();
}

function resolveDateRange({ preset, from, to }) {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth();
  const d = now.getDate();
  const day = (yy, mm, dd) => localDayKey(new Date(yy, mm, dd));
  switch (preset) {
    case "today":
      return { from: day(y, m, d), to: day(y, m, d) };
    case "yesterday":
      return { from: day(y, m, d - 1), to: day(y, m, d - 1) };
    case "last7":
      return { from: day(y, m, d - 6), to: day(y, m, d) };
    case "last30":
      return { from: day(y, m, d - 29), to: day(y, m, d) };
    case "thisMonth":
      return { from: day(y, m, 1), to: day(y, m, d) };
    case "lastMonth":
      return { from: day(y, m - 1, 1), to: day(y, m, 0) };
    default:
      return { from: from || "", to: to || "" };
  }
}

function dateInRange(iso, range) {
  const { from, to } = resolveDateRange(range);
  if (!from && !to) return true;
  const key = localDayKey(iso);
  if (!key) return false;
  return (!from || key >= from) && (!to || key <= to);
}

function dateRangeLabel(range) {
  const preset = DATE_PRESETS.find((p) => p.key === range.preset);
  if (preset) return preset.label;
  if (range.from || range.to)
    return `${range.from || "…"} → ${range.to || "…"}`;
  return "";
}

function agoShort(iso) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const min = Math.max(0, Math.floor((Date.now() - d.getTime()) / 60000));
  if (min < 1) return "just now";
  if (min < 60) return `${min}m ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h ago`;
  const days = Math.floor(hr / 24);
  if (days < 30) return `${days}d ago`;
  const months = Math.floor(days / 30);
  return months < 12 ? `${months}mo ago` : `${Math.floor(months / 12)}y ago`;
}

// Two-line cell:  Oct 14, 2026  /  10:09 PM · 57m ago
function CreatedAtCell({ iso }) {
  if (!iso) return <span className="text-ink-600/40">—</span>;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return <span>{String(iso)}</span>;
  const date = d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
  const time = d.toLocaleTimeString("en-US", {
    hour: "2-digit",
    minute: "2-digit",
  });
  return (
    <div className="leading-tight">
      <div className="font-medium text-ink-900">{date}</div>
      <div className="text-xs text-ink-600/55 mt-0.5">
        {time}
        <span className="mx-1">·</span>
        <span className="text-signal-blue">{agoShort(iso)}</span>
      </div>
    </div>
  );
}

function DateRangeFilter({ label = "Created At", value, onChange }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    function onClickOutside(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, []);
  const active = dateRangeLabel(value);
  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className={`flex items-center gap-1.5 text-sm border px-3 py-2 rounded-md hover:bg-mist-50 ${
          active
            ? "border-signal-blue text-signal-blue bg-signal-blue/5"
            : "border-mist-200 text-ink-700"
        }`}
      >
        <Icons.CalendarDays size={14} />
        {active ? `${label}: ${active}` : label}
        {active ? (
          <span
            role="button"
            title="Clear"
            onClick={(e) => {
              e.stopPropagation();
              onChange(EMPTY_DATE_RANGE);
            }}
            className="ml-0.5 rounded-sm hover:bg-signal-blue/10"
          >
            <X size={13} />
          </span>
        ) : (
          <Icons.ChevronDown size={14} />
        )}
      </button>
      {open && (
        <div className="absolute left-0 mt-1 w-64 bg-white border border-mist-200 rounded-md shadow-lg py-1 z-20">
          {DATE_PRESETS.map((p) => (
            <button
              key={p.key}
              type="button"
              onClick={() => {
                onChange({ preset: p.key, from: "", to: "" });
                setOpen(false);
              }}
              className={`w-full text-left px-3 py-1.5 text-sm hover:bg-mist-50 ${
                value.preset === p.key
                  ? "text-signal-blue font-medium"
                  : "text-ink-800"
              }`}
            >
              {p.label}
            </button>
          ))}
          <div className="border-t border-mist-200 mt-1 pt-2 px-3 pb-2 space-y-2">
            <div className="text-[11px] uppercase tracking-wide text-ink-600/40 font-semibold">
              Custom range
            </div>
            <div>
              <label className={LABEL_CLS}>ចាប់ពីថ្ងៃ</label>
              <input
                type="date"
                value={value.preset ? "" : value.from}
                onChange={(e) =>
                  onChange({
                    preset: "",
                    from: e.target.value,
                    to: value.preset ? "" : value.to,
                  })
                }
                className={INPUT_CLS}
              />
            </div>
            <div>
              <label className={LABEL_CLS}>ដល់ថ្ងៃ</label>
              <input
                type="date"
                value={value.preset ? "" : value.to}
                onChange={(e) =>
                  onChange({
                    preset: "",
                    from: value.preset ? "" : value.from,
                    to: e.target.value,
                  })
                }
                className={INPUT_CLS}
              />
            </div>
            <button
              type="button"
              onClick={() => {
                onChange(EMPTY_DATE_RANGE);
                setOpen(false);
              }}
              className="w-full text-sm text-ink-700 border border-mist-200 px-3 py-1.5 rounded-md hover:bg-mist-50"
            >
              Clear
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// Advanced date range picker for CN Purchase Orders only. Keeps the shared
// DateRangeFilter used by other modules unchanged.
function CNDateRangeFilter({ value, onChange }) {
  const [open, setOpen] = useState(false);
  const [month, setMonth] = useState(() => {
    const key = value?.from || localDayKey(new Date());
    const d = key ? new Date(`${key}T12:00:00`) : new Date();
    return new Date(d.getFullYear(), d.getMonth(), 1);
  });
  const [draftStart, setDraftStart] = useState("");
  const [hoverDate, setHoverDate] = useState("");
  const [draftRange, setDraftRange] = useState({
    from: value?.from || "",
    to: value?.to || "",
  });
  const rootRef = useRef(null);
  useEffect(() => {
    const closeOutside = (event) => {
      if (rootRef.current && !rootRef.current.contains(event.target)) {
        setOpen(false);
        setDraftStart("");
        setHoverDate("");
      }
    };
    document.addEventListener("mousedown", closeOutside);
    return () => document.removeEventListener("mousedown", closeOutside);
  }, []);
  const dayKey = (d) => localDayKey(d);
  const fmt = (key) =>
    key
      ? new Date(`${key}T12:00:00`).toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        })
      : "Select date";
  const active = dateRangeLabel(value || EMPTY_DATE_RANGE);
  const presetClick = (key) => {
    onChange({ preset: key, from: "", to: "" });
    setDraftStart("");
    setHoverDate("");
    setOpen(false);
  };
  const selectDay = (key) => {
    if (!draftStart) {
      setDraftStart(key);
      setHoverDate(key);
      setDraftRange({ from: key, to: "" });
      return;
    }
    const from = draftStart <= key ? draftStart : key;
    const to = draftStart <= key ? key : draftStart;
    setDraftRange({ from, to });
    setDraftStart("");
    setHoverDate("");
  };
  const renderMonth = (monthDate) => {
    const y = monthDate.getFullYear();
    const m = monthDate.getMonth();
    const first = new Date(y, m, 1);
    const offset = (first.getDay() + 6) % 7;
    const cells = Array.from({ length: 42 }, (_, i) => {
      const d = new Date(y, m, i - offset + 1);
      return { d, key: dayKey(d), inMonth: d.getMonth() === m };
    });
    const tentativeEnd =
      draftStart && hoverDate
        ? draftStart < hoverDate
          ? hoverDate
          : draftStart
        : draftRange.to;
    const tentativeStart =
      draftStart && hoverDate
        ? draftStart < hoverDate
          ? draftStart
          : hoverDate
        : draftRange.from || value?.from || "";
    return (
      <div className="min-w-0 flex-1" key={`${y}-${m}`}>
        <div className="mb-3 text-center text-sm font-semibold text-ink-800">
          {monthDate.toLocaleDateString("en-US", {
            month: "long",
            year: "numeric",
          })}
        </div>
        <div className="mb-2 grid grid-cols-7 border-b border-mist-100 pb-2">
          {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((d) => (
            <div
              key={d}
              className="text-center text-[11px] font-semibold text-ink-600/55"
            >
              {d}
            </div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-y-1">
          {cells.map(({ d, key, inMonth }) => {
            const between =
              !!tentativeStart &&
              !!tentativeEnd &&
              key >= tentativeStart &&
              key <= tentativeEnd;
            const endpoint =
              (key === tentativeStart || key === tentativeEnd) && between;
            const today = key === dayKey(new Date());
            return (
              <button
                key={key}
                type="button"
                onMouseEnter={() => draftStart && setHoverDate(key)}
                onClick={() => selectDay(key)}
                className={`mx-auto grid h-8 w-8 place-items-center rounded-full text-xs transition-all duration-150 hover:scale-105 hover:bg-signal-blue/10 hover:text-signal-blue ${between ? "!rounded-lg bg-signal-blue/10 text-signal-blue" : ""} ${endpoint ? "!rounded-full !bg-signal-blue !text-white shadow-sm" : today ? "ring-1 ring-signal-blue/30" : inMonth ? "text-ink-800" : "text-ink-600/25"}`}
              >
                {d.getDate()}
              </button>
            );
          })}
        </div>
      </div>
    );
  };
  return (
    <div className="relative" ref={rootRef}>
      <button
        type="button"
        onClick={() => {
          setOpen((v) => !v);
          setDraftStart("");
          setHoverDate("");
          setDraftRange({ from: value?.from || "", to: value?.to || "" });
        }}
        className={`inline-flex h-10 items-center gap-2 rounded-lg border px-3 text-sm transition-all hover:border-signal-blue/50 hover:shadow-sm ${active ? "border-signal-blue/40 bg-signal-blue/5 text-signal-blue" : "border-mist-200 bg-white text-ink-700"}`}
      >
        <Icons.CalendarDays size={15} />
        <span>{active ? active : "Created At"}</span>
        <Icons.ChevronDown size={14} />
      </button>
      {open && (
        <>
          <button
            type="button"
            aria-label="Close date range picker"
            className="fixed inset-0 z-[70] cursor-default"
            onClick={() => {
              setOpen(false);
              setDraftStart("");
            }}
          />
          <div
            className="absolute left-0 z-[80] mt-2 w-[min(94vw,760px)] overflow-hidden rounded-2xl border border-mist-200 bg-white shadow-2xl shadow-slate-900/15"
            style={{
              animation: "jenzCalendarIn .18s cubic-bezier(.2,.8,.2,1)",
            }}
          >
            <div className="flex items-center justify-between gap-3 border-b border-mist-100 px-4 py-3 sm:px-5">
              <div>
                <p className="text-sm font-semibold text-ink-800">
                  Select date range
                </p>
                <p className="mt-0.5 text-xs text-ink-600/50">
                  Choose a preset or select start and end dates
                </p>
              </div>
              <span className="max-w-[45%] truncate text-xs text-ink-600/60">
                {draftStart
                  ? `Start: ${fmt(draftStart)} · choose end date`
                  : draftRange.from && draftRange.to
                    ? `${fmt(draftRange.from)} – ${fmt(draftRange.to)}`
                    : "Custom range"}
              </span>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-[150px_minmax(0,1fr)]">
              <div className="border-b border-mist-100 p-2 sm:border-b-0 sm:border-r sm:p-3">
                {DATE_PRESETS.map((p) => (
                  <button
                    key={p.key}
                    type="button"
                    onClick={() => presetClick(p.key)}
                    className={`block w-full rounded-lg px-3 py-2.5 text-left text-sm transition-colors hover:bg-signal-blue/5 hover:text-signal-blue ${value?.preset === p.key ? "bg-signal-blue/5 font-medium text-signal-blue" : "text-ink-700"}`}
                  >
                    {p.label}
                  </button>
                ))}
                <div className="mt-2 border-t border-mist-100 px-3 pt-3 text-[10px] font-semibold uppercase tracking-[.12em] text-ink-600/40">
                  Custom date
                </div>
                <div className="px-3 pb-2 pt-1 text-xs text-ink-600/60">
                  {draftStart
                    ? `Start: ${fmt(draftStart)}`
                    : draftRange.from && draftRange.to
                      ? `${fmt(draftRange.from)} – ${fmt(draftRange.to)}`
                      : "Select start and end"}
                </div>
              </div>
              <div className="min-w-0 p-3 sm:p-4">
                <div className="mb-3 flex items-center justify-between gap-2">
                  <button
                    type="button"
                    aria-label="Previous month"
                    onClick={() =>
                      setMonth(
                        new Date(month.getFullYear(), month.getMonth() - 1, 1),
                      )
                    }
                    className="grid h-8 w-8 place-items-center rounded-lg text-ink-600/70 transition hover:bg-mist-50"
                  >
                    <Icons.ChevronLeft size={17} />
                  </button>
                  <span className="text-xs text-ink-600/50">
                    {draftStart ? "Select the end date" : "Select a date range"}
                  </span>
                  <button
                    type="button"
                    aria-label="Next month"
                    onClick={() =>
                      setMonth(
                        new Date(month.getFullYear(), month.getMonth() + 1, 1),
                      )
                    }
                    className="grid h-8 w-8 place-items-center rounded-lg text-ink-600/70 transition hover:bg-mist-50"
                  >
                    <Icons.ChevronRight size={17} />
                  </button>
                </div>
                <div className="flex flex-col gap-5 md:flex-row">
                  {renderMonth(month)}
                  {renderMonth(
                    new Date(month.getFullYear(), month.getMonth() + 1, 1),
                  )}
                </div>
                <div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-mist-100 pt-3">
                  <button
                    type="button"
                    onClick={() => {
                      onChange(EMPTY_DATE_RANGE);
                      setDraftRange({ from: "", to: "" });
                      setDraftStart("");
                      setOpen(false);
                    }}
                    className="rounded-lg px-3 py-2 text-sm text-ink-600/70 transition hover:bg-mist-50"
                  >
                    Clear
                  </button>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => presetClick("today")}
                      className="rounded-lg px-3 py-2 text-sm font-medium text-signal-blue transition hover:bg-signal-blue/5"
                    >
                      Today
                    </button>
                    <button
                      type="button"
                      disabled={!draftRange.from || !draftRange.to}
                      onClick={() => {
                        onChange({
                          preset: "",
                          from: draftRange.from,
                          to: draftRange.to,
                        });
                        setOpen(false);
                        setDraftStart("");
                        setHoverDate("");
                      }}
                      className="rounded-lg bg-signal-blue px-4 py-2 text-sm font-semibold text-white shadow-sm transition hover:brightness-95 disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      Apply
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

