const TONES = {
  blue: "bg-signal-blue/10 text-signal-blue",
  amber: "bg-signal-amber/10 text-[#B87415]",
  teal: "bg-signal-teal/10 text-signal-teal",
  red: "bg-signal-red/10 text-signal-red",
  ink: "bg-ink-900/5 text-ink-800",
  violet: "bg-violet-50 text-violet-700",
};

function StatCard({ icon, label, value, unit, tone = "ink", delta, to }) {
  const Icon = Icons[icon] || Icons.Circle;
  const Arrow = Icons.ArrowUpRight || Icons.ChevronRight || Icons.Circle;
  const card = (
    <div className="cb-surface cb-card cb-stat p-4 shadow-panel">
      <div className="flex items-center gap-3">
        <div
          className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ring-4 ring-white shadow-sm ${TONES[tone]}`}
        >
          <Icon size={18} strokeWidth={2.25} />
        </div>
        <div className="text-[13px] font-medium text-ink-600/70 leading-tight">
          {label}
        </div>
        {to && (
          <Arrow
            size={15}
            className="ml-auto shrink-0 text-ink-600/40"
            aria-hidden="true"
          />
        )}
      </div>
      <div className="mt-3 flex items-baseline gap-1.5">
        <span className="font-display text-[28px] leading-none font-extrabold text-ink-900 tabular-nums">
          {value}
        </span>
        {unit && (
          <span className="text-xs text-ink-600/50 font-medium">{unit}</span>
        )}
        {delta && (
          <span
            className={`ml-auto text-[11px] font-semibold ${
              delta.startsWith("-") ? "text-signal-red" : "text-signal-teal"
            }`}
          >
            {delta}
          </span>
        )}
      </div>
    </div>
  );
  if (!to) return card;
  return (
    <Link to={to} className="cbx-kpi-link" aria-label={`${label}: ${value}`}>
      {card}
    </Link>
  );
}

