// Khmer font for the admin area (the fonts are already loaded by the
// Customer Portal module; this only switches the family).
const ADMIN_KM_CSS = String.raw`
html.cb-admin-km body,html.cb-admin-km #root,html.cb-admin-km .font-display,
html.cb-admin-km .cb-app *:not(.font-mono),html.cb-admin-km .cb-login-page *:not(.font-mono){font-family:'Kantumruy Pro','Noto Sans Khmer',Inter,system-ui,sans-serif!important}
html.cb-admin-km .leading-tight,html.cb-admin-km .leading-snug,html.cb-admin-km .leading-none{line-height:1.5}
`;

const AdminPrefsCtx = createContext(null);
const ADMIN_PREFS_FALLBACK = {
  theme: "light",
  dark: false,
  lang: "en",
  setTheme: () => {},
  setLang: () => {},
  t: (s) => s,
};
function useAdminPrefs() {
  return useContext(AdminPrefsCtx) || ADMIN_PREFS_FALLBACK;
}

function AdminPrefsProvider({ children }) {
  const [theme, setThemeState] = useState(readAdminTheme);
  const [lang, setLangState] = useState(readAdminLang);
  const [sysDark, setSysDark] = useState(
    () =>
      typeof window !== "undefined" &&
      !!window.matchMedia &&
      window.matchMedia("(prefers-color-scheme: dark)").matches,
  );
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = (e) => setSysDark(e.matches);
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", onChange);
      else mq.removeListener(onChange);
    };
  }, []);
  const dark = theme === "dark" || (theme === "system" && sysDark);

  useEffect(() => {
    const el = document.documentElement;
    el.classList.toggle("cb-admin-dark", dark);
    return () => el.classList.remove("cb-admin-dark");
  }, [dark]);
  useEffect(() => {
    const el = document.documentElement;
    el.classList.toggle("cb-admin-km", lang === "km");
    return () => el.classList.remove("cb-admin-km");
  }, [lang]);

  const setTheme = (v) => {
    setThemeState(v);
    try {
      localStorage.setItem(ADMIN_THEME_KEY, v);
    } catch {}
  };
  const setLang = (v) => {
    setLangState(v);
    try {
      localStorage.setItem(ADMIN_LANG_KEY, v);
    } catch {}
  };
  const t = (s) => (lang === "km" ? ADMIN_KM[s] || s : s);

  return (
    <AdminPrefsCtx.Provider value={{ theme, setTheme, dark, lang, setLang, t }}>
      {dark && <style>{ADMIN_DARK_CSS}</style>}
      {lang === "km" && <style>{ADMIN_KM_CSS}</style>}
      {children}
    </AdminPrefsCtx.Provider>
  );
}

// Small centred picker used by the user menu (Language / Appearance).
function AdminPrefsModal({ kind, onClose }) {
  const { theme, setTheme, lang, setLang, t } = useAdminPrefs();
  const isLang = kind === "lang";
  const opts = isLang
    ? [
        ["en", "English", "🇬🇧"],
        ["km", "ភាសាខ្មែរ", "🇰🇭"],
      ]
    : [
        ["light", t("Light theme"), Icons.Sun],
        ["dark", t("Dark theme"), Icons.Moon],
        ["system", t("Use device theme"), Icons.Monitor],
      ];
  const current = isLang ? lang : theme;
  return (
    <div
      className="fixed inset-0 z-[110] bg-ink-900/40 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-xl shadow-lg w-full max-w-sm p-5"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
      >
        <h3 className="font-display font-bold text-base text-ink-900 mb-4">
          {isLang ? t("Language") : t("Appearance")}
        </h3>
        <div className="space-y-2">
          {opts.map(([k, label, ic]) => {
            const on = current === k;
            return (
              <button
                key={k}
                type="button"
                onClick={() => {
                  if (isLang) setLang(k);
                  else setTheme(k);
                  onClose();
                }}
                className={`w-full h-12 rounded-xl flex items-center gap-3 px-3.5 text-sm font-semibold border transition-colors ${
                  on
                    ? "bg-signal-blue text-white border-signal-blue shadow-lg shadow-blue-500/20"
                    : "bg-mist-50 text-ink-800 border-mist-200 hover:border-mist-300"
                }`}
              >
                {isLang ? (
                  <span className="text-lg leading-none">{ic}</span>
                ) : (
                  React.createElement(ic, { size: 17 })
                )}
                <span className="flex-1 text-left">{label}</span>
                <span
                  className={`w-5 h-5 rounded-full grid place-items-center ${
                    on
                      ? "bg-white/95 text-signal-blue"
                      : "border border-mist-300"
                  }`}
                >
                  {on && <Check size={12} strokeWidth={3} />}
                </span>
              </button>
            );
          })}
        </div>
        <button
          type="button"
          onClick={onClose}
          className="mt-3 w-full text-sm font-medium text-center border border-mist-200 py-2 rounded-md hover:bg-mist-50"
        >
          {t("Cancel")}
        </button>
      </div>
    </div>
  );
}

// Quick language + theme buttons shown in the corner of the Login page.
function AdminLoginPrefs() {
  const { dark, setTheme, lang, setLang, t } = useAdminPrefs();
  const btn =
    "h-10 w-10 grid place-items-center rounded-full border border-mist-200 bg-white/90 text-ink-700 shadow-sm hover:bg-white transition";
  return (
    <div className="absolute top-4 right-4 z-20 flex items-center gap-2">
      <button
        type="button"
        className={`${btn} text-lg`}
        aria-label={t("Language")}
        onClick={() => setLang(lang === "km" ? "en" : "km")}
      >
        {lang === "km" ? "🇰🇭" : "🇬🇧"}
      </button>
      <button
        type="button"
        className={btn}
        aria-label={t("Appearance")}
        onClick={() => setTheme(dark ? "light" : "dark")}
      >
        {dark ? <Icons.Sun size={18} /> : <Icons.Moon size={18} />}
      </button>
    </div>
  );
}

const SIDEBAR_COLLAPSED_KEY = "cb_sidebar_collapsed";
const readSidebarCollapsed = () => {
  try {
    return localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === "1";
  } catch {
    return false;
  }
};
const isDesktopViewport = () =>
  typeof window !== "undefined" &&
  window.matchMedia("(min-width: 1024px)").matches;

function Sidebar({ open, onClose, collapsed = false, onToggleCollapse }) {
  const { user } = useAuth();
  const { t } = useAdminPrefs();
  const systemSettings = useSystemSettings();
  const company = systemSettings.company || DEFAULT_SYSTEM_SETTINGS.company;
  const sidebarLogo = company.logoUrl || company.logoDataUrl || "";
  const [tip, setTip] = useState(null); // { label, top, left }

  // Tooltip only while the desktop sidebar is collapsed (labels are hidden).
  const showTip = (e, label) => {
    if (!collapsed || !isDesktopViewport()) return;
    const r = e.currentTarget.getBoundingClientRect();
    setTip({ label, top: r.top + r.height / 2, left: r.right + 10 });
  };
  const hideTip = () => setTip(null);
  useEffect(() => {
    if (!collapsed) setTip(null);
  }, [collapsed]);

  const toggleLabel = collapsed ? t("Expand sidebar") : t("Collapse sidebar");

  return (
    <>
      {/* mobile overlay */}
      {open && (
        <div
          className="fixed inset-0 z-30 bg-ink-900/40 lg:hidden"
          onClick={onClose}
        />
      )}
      <aside
        aria-label="Main navigation"
        className={`cbx-sidebar ${collapsed ? "is-collapsed" : ""} fixed z-40 inset-y-0 left-0 flex flex-col
          transform lg:static lg:translate-x-0
          ${open ? "translate-x-0" : "-translate-x-full"}`}
      >
        <div className="cbx-side-head flex items-center gap-2.5 px-4 shrink-0">
          <div className="w-9 h-9 rounded-lg bg-signal-blue flex items-center justify-center overflow-hidden shrink-0">
            {sidebarLogo ? (
              <img
                src={sidebarLogo}
                alt="Company logo"
                className="w-full h-full object-cover"
              />
            ) : (
              <Icons.Waypoints size={18} className="text-white" />
            )}
          </div>
          <div className="cbx-side-brandtext leading-tight min-w-0 flex-1">
            <div className="cbx-side-title font-display font-extrabold text-sm tracking-tight truncate">
              {company.name || "Cargo Bridge"}
            </div>
            <div className="cbx-side-sub text-[11px] truncate">
              {company.shortName
                ? `${company.shortName} · Logistics`
                : "CN → KH Logistics"}
            </div>
          </div>
          {onToggleCollapse && (
            <button
              type="button"
              className="cbx-collapse-btn"
              aria-label={toggleLabel}
              aria-pressed={collapsed}
              title={toggleLabel}
              onClick={onToggleCollapse}
            >
              <Icon
                name={collapsed ? "PanelLeftOpen" : "PanelLeftClose"}
                size={16}
              />
            </button>
          )}
        </div>

        <nav className="flex-1 overflow-y-auto overflow-x-hidden px-3 py-4 space-y-4">
          {NAV_SECTIONS.map((section, i) => {
            const items = section.items.filter(
              (item) =>
                user?.allowedPaths === "*" ||
                user?.allowedPaths?.includes(item.path),
            );
            if (items.length === 0) return null;
            return (
              <div key={i}>
                {section.label ? (
                  <>
                    <div className="cbx-side-group px-3 mb-1.5">
                      {t(section.label)}
                    </div>
                    <div className="cbx-side-rule" aria-hidden="true" />
                  </>
                ) : null}
                <div className="space-y-0.5">
                  {items.map((item) => {
                    const label = t(item.label);
                    return (
                      <NavLink
                        key={item.path}
                        to={item.path}
                        end={item.path === "/"}
                        onClick={onClose}
                        aria-label={label}
                        onMouseEnter={(e) => showTip(e, label)}
                        onMouseLeave={hideTip}
                        onFocus={(e) => showTip(e, label)}
                        onBlur={hideTip}
                        className={({ isActive }) =>
                          `cbx-nav-link ${isActive ? "is-active" : ""}`
                        }
                      >
                        <Icon
                          name={item.icon}
                          size={17}
                          strokeWidth={2}
                          className="shrink-0"
                        />
                        <span className="cbx-label truncate">{label}</span>
                      </NavLink>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </nav>
      </aside>
      {tip &&
        createPortal(
          <div
            role="tooltip"
            className="cbx-tip"
            style={{ top: tip.top, left: tip.left }}
          >
            {tip.label}
          </div>,
          document.body,
        )}
    </>
  );
}

// ------------------------------------------------------------
// components/Topbar.jsx
// ------------------------------------------------------------
function UserAvatar({ url, initials }) {
  const [broken, setBroken] = useState(false);
  useEffect(() => setBroken(false), [url]);
  if (url && !broken) {
    return (
      <img
        src={url}
        alt=""
        onError={() => setBroken(true)}
        className="absolute inset-0 w-full h-full rounded-full object-cover"
      />
    );
  }
  return <>{initials}</>;
}

function Topbar({ title, onMenuClick }) {
  const { user, logout, updateAvatar } = useAuth();
  const fileRef = useRef(null);
  const [avatarBusy, setAvatarBusy] = useState(false);
  const { t, lang, theme } = useAdminPrefs();
  const [prefsModal, setPrefsModal] = useState(null); // null | "lang" | "theme"
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  const [showAccount, setShowAccount] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [commandQuery, setCommandQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  const menuRef = useRef(null);
  const commandInputRef = useRef(null);
  const { items: slaBellItems } = useSlaNotifications({ limit: 500 });
  const slaUnread = slaBellItems.filter((n) => !n.read_at).length;

  // Command Palette / Quick Navigation.
  // Only routes already allowed for the current staff account are exposed.
  const commandItems = useMemo(() => {
    const sections = [];
    for (const section of NAV_SECTIONS) {
      const items = section.items.filter(
        (item) =>
          user?.allowedPaths === "*" || user?.allowedPaths?.includes(item.path),
      );
      if (items.length) {
        sections.push({
          label: section.label || "MAIN",
          items,
        });
      }
    }
    return sections;
  }, [user?.allowedPaths]);

  const flatCommandItems = useMemo(
    () => commandItems.flatMap((section) => section.items),
    [commandItems],
  );

  const filteredCommandItems = useMemo(() => {
    const q = commandQuery.trim().toLowerCase();
    if (!q) return flatCommandItems;

    return flatCommandItems.filter((item) => {
      const haystack =
        `${item.label} ${t(item.label)} ${item.path} ${item.section || ""}`.toLowerCase();
      return haystack.includes(q);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flatCommandItems, commandQuery, lang]);

  useEffect(() => {
    setActiveIndex(0);
  }, [commandQuery, commandOpen]);

  useEffect(() => {
    if (!commandOpen) return;
    const id = requestAnimationFrame(() => commandInputRef.current?.focus());
    return () => cancelAnimationFrame(id);
  }, [commandOpen]);

  useEffect(() => {
    function onKeyDown(e) {
      const isShortcut =
        (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k";

      if (isShortcut) {
        e.preventDefault();
        setMenuOpen(false);
        setCommandOpen(true);
        return;
      }

      if (!commandOpen) return;

      if (e.key === "Escape") {
        e.preventDefault();
        setCommandOpen(false);
        setCommandQuery("");
        return;
      }

      if (e.key === "ArrowDown") {
        e.preventDefault();
        setActiveIndex((i) =>
          filteredCommandItems.length
            ? (i + 1) % filteredCommandItems.length
            : 0,
        );
      }

      if (e.key === "ArrowUp") {
        e.preventDefault();
        setActiveIndex((i) =>
          filteredCommandItems.length
            ? (i - 1 + filteredCommandItems.length) %
              filteredCommandItems.length
            : 0,
        );
      }

      if (e.key === "Enter" && filteredCommandItems[activeIndex]) {
        e.preventDefault();
        navigate(filteredCommandItems[activeIndex].path);
        setCommandOpen(false);
        setCommandQuery("");
      }
    }

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [commandOpen, filteredCommandItems, activeIndex, navigate]);

  function openCommandPalette() {
    setMenuOpen(false);
    setCommandQuery("");
    setActiveIndex(0);
    setCommandOpen(true);
  }

  function closeCommandPalette() {
    setCommandOpen(false);
    setCommandQuery("");
  }

  function goToCommandItem(item) {
    navigate(item.path);
    closeCommandPalette();
  }

  useEffect(() => {
    function onClickOutside(e) {
      if (menuRef.current && !menuRef.current.contains(e.target))
        setMenuOpen(false);
    }
    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, []);

  const displayName = user?.name || user?.email?.split("@")[0] || "User";
  const initials = displayName.slice(0, 2).toUpperCase();
  const shortcutLabel =
    typeof navigator !== "undefined" &&
    /Mac|iPhone|iPad/i.test(navigator.platform || "")
      ? "⌘ K"
      : "Ctrl K";

  async function handleAvatarChange(e) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file || !supabase) return;
    if (!file.type.startsWith("image/")) return alert("សូមជ្រើសរើសរូបភាព");
    if (file.size > 2 * 1024 * 1024) return alert("រូបភាពធំជាង 2MB");

    setAvatarBusy(true);
    try {
      const path = `${user.id}/avatar`;
      const { error: upErr } = await supabase.storage
        .from("avatars")
        .upload(path, file, { upsert: true, contentType: file.type });
      if (upErr) throw upErr;

      const { data } = supabase.storage.from("avatars").getPublicUrl(path);
      const url = `${data.publicUrl}?t=${Date.now()}`;

      const { error } = await supabase
        .from("users")
        .update({ avatar_url: url })
        .eq("auth_user_id", user.id);
      if (error) throw error;

      updateAvatar(url);
    } catch (err) {
      alert(err.message || "មិនអាច upload បានទេ");
    } finally {
      setAvatarBusy(false);
    }
  }

  async function handleAvatarRemove() {
    if (!supabase) return;
    setAvatarBusy(true);
    try {
      await supabase.storage.from("avatars").remove([`${user.id}/avatar`]);
      const { error } = await supabase
        .from("users")
        .update({ avatar_url: null })
        .eq("auth_user_id", user.id);
      if (error) throw error;
      updateAvatar(null);
    } catch (err) {
      alert(err.message);
    } finally {
      setAvatarBusy(false);
    }
  }

  async function handleLogout() {
    setMenuOpen(false);
    const ok = await confirmDialog({
      variant: "signout",
      title: t("Sign out"),
      message: t("Are you sure you want to sign out?"),
      confirmText: t("Confirm"),
      cancelText: t("Cancel"),
    });
    if (!ok) return;
    await logout();
    navigate("/login", { replace: true });
  }

  return (
    <>
      <header className="cbx-topbar h-16 shrink-0 flex items-center gap-3 px-4 lg:px-6">
        <button
          type="button"
          onClick={onMenuClick}
          className="cbx-icon-btn lg:hidden inline-flex items-center justify-center"
          aria-label="Open menu"
        >
          <Menu size={20} />
        </button>

        <h1 className="cbx-page-title font-display font-bold text-lg hidden sm:block">
          {t(title)}
        </h1>

        <button
          type="button"
          onClick={openCommandPalette}
          className="cbx-search hidden md:flex flex-1 max-w-2xl mx-auto items-center gap-3 h-10 px-3.5 text-left"
          aria-label="Search pages or jump to a menu"
        >
          <Search size={18} className="shrink-0" />
          <span className="text-sm flex-1">
            {t("Search pages or jump to a menu...")}
          </span>
          <kbd className="cbx-kbd hidden lg:inline-flex items-center">
            {shortcutLabel}
          </kbd>
        </button>

        <div className="flex-1 md:hidden" />

        <button
          type="button"
          onClick={openCommandPalette}
          className="cbx-icon-btn md:hidden inline-flex items-center justify-center"
          aria-label="Search pages or jump to a menu"
        >
          <Search size={19} />
        </button>

        <button
          type="button"
          onClick={() => navigate("/notifications")}
          className="cbx-icon-btn inline-flex items-center justify-center"
          aria-label={`${t("Notifications")}${slaUnread > 0 ? ` (${slaUnread})` : ""}`}
        >
          <Bell size={20} strokeWidth={1.9} />
          {slaUnread > 0 && (
            <span className="cbx-badge" aria-hidden="true">
              {slaUnread > 99 ? "99+" : slaUnread}
            </span>
          )}
        </button>

        <span className="cbx-divider hidden sm:block" aria-hidden="true" />

        <div
          className="relative"
          ref={menuRef}
          onKeyDown={(e) => {
            if (e.key === "Escape") setMenuOpen(false);
          }}
        >
          <button
            type="button"
            onClick={() => setMenuOpen((v) => !v)}
            className="cbx-user-pill"
            aria-haspopup="menu"
            aria-expanded={menuOpen}
            aria-label={`${displayName}, ${user?.role || "Admin"}`}
          >
            <div className="cbx-avatar">
              <UserAvatar url={user?.avatarUrl} initials={initials} />
            </div>
            <div className="hidden sm:block text-left leading-tight min-w-0">
              <div className="cbx-user-name capitalize truncate max-w-[150px]">
                {displayName}
              </div>
              <div className="cbx-user-role mt-0.5 flex items-center gap-1">
                <Icons.ShieldCheck size={13} />
                {t(user?.role || "Admin")}
              </div>
            </div>
            <ChevronDown
              size={16}
              className={`cbx-muted hidden sm:block transition-transform duration-200 ${menuOpen ? "rotate-180" : ""}`}
            />
          </button>

          {menuOpen && (
            <div
              role="menu"
              className="cbx-menu absolute right-0 mt-2 w-64 py-1.5 z-50 cb-fade-in"
            >
              <div className="cbx-menu-head">
                <div className="cbx-menu-name truncate">{displayName}</div>
                <div className="cbx-menu-mail truncate">{user?.email}</div>
              </div>
              <button
                onClick={() => {
                  setMenuOpen(false);
                  setShowAccount(true);
                }}
                role="menuitem"
                className="cbx-menu-item"
              >
                <UserRound size={15} />
                {t("My Account")}
              </button>
              <button
                onClick={() => {
                  setMenuOpen(false);
                  setPrefsModal("lang");
                }}
                role="menuitem"
                className="cbx-menu-item"
              >
                <Icons.Languages size={15} />
                <span className="flex-1">{t("Language")}</span>
                <span className="cbx-menu-meta">
                  {lang === "km" ? "ខ្មែរ" : "English"}
                </span>
              </button>
              <button
                onClick={() => {
                  setMenuOpen(false);
                  setPrefsModal("theme");
                }}
                role="menuitem"
                className="cbx-menu-item"
              >
                <Icons.Palette size={15} />
                <span className="flex-1">{t("Appearance")}</span>
                <span className="cbx-menu-meta">
                  {theme === "dark"
                    ? t("Dark")
                    : theme === "system"
                      ? t("Device")
                      : t("Light")}
                </span>
              </button>
              <div className="cbx-menu-sep" />
              <button
                onClick={handleLogout}
                role="menuitem"
                className="cbx-menu-item is-danger"
              >
                <LogOut size={15} />
                {t("Log out")}
              </button>
            </div>
          )}
        </div>

        {showAccount &&
          createPortal(
            <div
              className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
              onClick={() => setShowAccount(false)}
            >
              <div
                className="bg-white rounded-md shadow-lg w-full max-w-sm p-5"
                onClick={(e) => e.stopPropagation()}
              >
                <h3 className="font-display font-bold text-base text-ink-900 mb-4">
                  {t("My Account")}
                </h3>
                <div className="flex items-center gap-3 mb-4">
                  <div className="relative w-14 h-14 rounded-full bg-ink-800 text-white text-base font-semibold flex items-center justify-center shrink-0 overflow-hidden">
                    <UserAvatar url={user?.avatarUrl} initials={initials} />
                  </div>
                  <div className="min-w-0">
                    <div className="text-sm font-medium text-ink-900 capitalize truncate">
                      {displayName}
                    </div>
                    <div className="text-xs text-ink-600/55 truncate">
                      {user?.email}
                    </div>
                  </div>
                </div>

                <input
                  ref={fileRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={handleAvatarChange}
                />
                <div className="flex gap-2 mb-3">
                  <button
                    disabled={avatarBusy || !user?.isStaff}
                    onClick={() => fileRef.current?.click()}
                    className="flex-1 text-sm font-medium border border-mist-200 py-2 rounded-md hover:bg-mist-50 disabled:opacity-50"
                  >
                    {avatarBusy ? "..." : t("Change photo")}
                  </button>
                  {user?.avatarUrl && (
                    <button
                      disabled={avatarBusy}
                      onClick={handleAvatarRemove}
                      className="text-sm font-medium text-signal-red border border-mist-200 px-3 py-2 rounded-md hover:bg-signal-red/5 disabled:opacity-50"
                    >
                      {t("Remove")}
                    </button>
                  )}
                </div>
                <button
                  onClick={() => setShowAccount(false)}
                  className="w-full text-sm font-medium text-center border border-mist-200 py-2 rounded-md hover:bg-mist-50"
                >
                  {t("Close")}
                </button>
              </div>
            </div>,
            document.body,
          )}
      </header>

      {prefsModal && (
        <AdminPrefsModal
          kind={prefsModal}
          onClose={() => setPrefsModal(null)}
        />
      )}

      {commandOpen && (
        <div
          className="fixed inset-0 z-[100] bg-ink-900/35 backdrop-blur-[1px] flex items-start justify-center px-4 pt-[10vh] sm:pt-[12vh]"
          onMouseDown={closeCommandPalette}
        >
          <div
            className="w-full max-w-3xl overflow-hidden rounded-2xl border border-mist-200 bg-white shadow-2xl"
            onMouseDown={(e) => e.stopPropagation()}
            role="dialog"
            aria-modal="true"
            aria-label="Search pages"
          >
            <div className="flex items-center gap-3 px-5 h-16 border-b border-mist-100">
              <Search size={21} className="text-ink-600/45 shrink-0" />
              <input
                ref={commandInputRef}
                value={commandQuery}
                onChange={(e) => setCommandQuery(e.target.value)}
                placeholder={t("Search pages or menu...")}
                className="flex-1 bg-transparent outline-none text-base text-ink-900 placeholder:text-ink-600/40"
                autoComplete="off"
                aria-label="Search pages"
              />
              <kbd className="rounded-md border border-mist-200 bg-mist-50 px-2 py-1 text-[11px] text-ink-600/55">
                Esc
              </kbd>
            </div>

            <div className="max-h-[68vh] overflow-y-auto py-3">
              {commandQuery.trim() ? (
                filteredCommandItems.length ? (
                  <div className="px-3">
                    <div className="px-3 pb-2 text-[11px] font-semibold uppercase tracking-wide text-ink-600/45">
                      {t("Search Results")}
                    </div>
                    {filteredCommandItems.map((item, index) => (
                      <button
                        key={`${item.path}-${index}`}
                        type="button"
                        onClick={() => goToCommandItem(item)}
                        className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-left transition-colors ${
                          index === activeIndex
                            ? "bg-blue-50 text-signal-blue"
                            : "text-ink-800 hover:bg-mist-50"
                        }`}
                      >
                        <span className="w-8 h-8 rounded-lg bg-mist-50 grid place-items-center shrink-0">
                          <Icon name={item.icon} size={17} strokeWidth={1.9} />
                        </span>
                        <span className="min-w-0 flex-1">
                          <span className="block text-sm font-medium truncate">
                            {t(item.label)}
                          </span>
                          <span className="block text-[11px] text-ink-600/40 truncate">
                            {item.path}
                          </span>
                        </span>
                        {index === activeIndex && (
                          <span className="text-[11px] text-ink-600/40">
                            Enter
                          </span>
                        )}
                      </button>
                    ))}
                  </div>
                ) : (
                  <div className="px-6 py-14 text-center">
                    <Search
                      size={28}
                      className="mx-auto text-ink-600/20 mb-3"
                    />
                    <div className="text-sm font-medium text-ink-800">
                      {t("No pages found")}
                    </div>
                    <div className="text-xs text-ink-600/45 mt-1">
                      {t("Try another page name or route.")}
                    </div>
                  </div>
                )
              ) : (
                <div className="px-3">
                  {commandItems.map((section, sectionIndex) => (
                    <div
                      key={`${section.label}-${sectionIndex}`}
                      className="mb-4 last:mb-0"
                    >
                      <div className="px-3 pb-2 text-[11px] font-semibold uppercase tracking-wide text-ink-600/45">
                        {t(section.label)}
                      </div>

                      {section.items.map((item) => {
                        const index = filteredCommandItems.findIndex(
                          (x) => x.path === item.path,
                        );
                        const active = index === activeIndex;

                        return (
                          <button
                            key={item.path}
                            type="button"
                            onClick={() => goToCommandItem(item)}
                            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-left transition-colors ${
                              active
                                ? "bg-blue-50 text-signal-blue"
                                : "text-ink-800 hover:bg-mist-50"
                            }`}
                          >
                            <span className="w-8 h-8 rounded-lg bg-mist-50 grid place-items-center shrink-0">
                              <Icon
                                name={item.icon}
                                size={17}
                                strokeWidth={1.9}
                              />
                            </span>
                            <span className="min-w-0 flex-1 text-sm font-medium truncate">
                              {t(item.label)}
                            </span>
                            <span className="text-[11px] text-ink-600/35 truncate max-w-[220px]">
                              {item.path}
                            </span>
                          </button>
                        );
                      })}
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="h-11 px-5 border-t border-mist-100 bg-mist-50/50 flex items-center gap-4 text-[11px] text-ink-600/45">
              <span>
                <b className="text-ink-600/60">↑ ↓</b> {t("Navigate")}
              </span>
              <span>
                <b className="text-ink-600/60">Enter</b> {t("Open")}
              </span>
              <span>
                <b className="text-ink-600/60">Esc</b> {t("Close")}
              </span>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
// ------------------------------------------------------------
// components/Layout.jsx
// ------------------------------------------------------------
function useCurrentTitle() {
  const { pathname } = useLocation();
  if (pathname === "/notifications") return "Notifications";
  for (const section of NAV_SECTIONS) {
    for (const item of section.items) {
      if (item.path === pathname) return item.label;
    }
  }
  return "Dashboard";
}

function Layout() {
  const { pathname } = useLocation();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] =
    useState(readSidebarCollapsed);
  const title = useCurrentTitle();
  const toggleSidebarCollapsed = () =>
    setSidebarCollapsed((prev) => {
      const next = !prev;
      try {
        localStorage.setItem(SIDEBAR_COLLAPSED_KEY, next ? "1" : "0");
      } catch {
        /* storage unavailable – still works for this session */
      }
      return next;
    });

  return (
    <div className="cb-app h-screen flex bg-[#f4f7fb]">
      <Sidebar
        open={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        collapsed={sidebarCollapsed}
        onToggleCollapse={toggleSidebarCollapsed}
      />
      <div className="flex-1 flex flex-col min-w-0">
        <SlaNotificationSync />
        <SlaAirNotificationSync />
        <Topbar title={title} onMenuClick={() => setSidebarOpen(true)} />
        <main className="flex-1 overflow-y-auto p-4 lg:p-6 xl:p-7">
          <div key={pathname} className="cb-page-enter">
            <Outlet />
          </div>
        </main>
      </div>
    </div>
  );
}

// ------------------------------------------------------------
// components/ProtectedRoute.jsx
// ------------------------------------------------------------
function ProtectedRoute({ children }) {
  const { user, loading } = useAuth();
  const location = useLocation();

  if (loading) return <AppShellSkeleton />;

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // SECURITY: customer accounts must never open the admin system.
  if (user.isStaff !== true) {
    return <Navigate to="/customer" replace />;
  }

  const allowed =
    user.allowedPaths === "*" ||
    user.allowedPaths?.includes(location.pathname) ||
    // detail pages (e.g. /containers/MSCU1234567) follow their list page
    user.allowedPaths?.some(
      (p) => p !== "/" && location.pathname.startsWith(`${p}/`),
    );

  if (!allowed) {
    // Send the user to the first page their role can open (no redirect loop
    // when even the Dashboard is not allowed).
    const fallback = firstAllowedPath(user);
    if (fallback && fallback !== location.pathname)
      return <Navigate to={fallback} replace />;
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-mist-50 gap-2">
        <span className="text-sm text-ink-600/70">
          You do not have permission to view this page.
        </span>
        <span className="text-xs text-ink-600/45">
          Contact a Super Admin to update your role.
        </span>
      </div>
    );
  }

  return children;
}

// ------------------------------------------------------------
// lib/tableData.js
// ------------------------------------------------------------
// Every module path maps 1:1 to a Supabase table (e.g. "/customer-accounts"
// -> table "customer_accounts"). Create these tables in your Supabase
// project (see supabase/schema.sql) with columns matching each module's
// `columns` config in MODULES above.
function pathToTable(path) {
  return path.replace(/^\//, "").replace(/-/g, "_");
}

// The `customers` table's real primary key is a uuid `id` — the
// human-readable, sequential Customer ID (KH-000001, KH-000002, ...)
// that should actually be shown/searched everywhere lives in its own
// `customer_code` column, generated by the DB trigger described in
// supabase/schema.sql. Alias it onto `id` in every customers query so
// the rest of the app (columns config, DataTable, CreateRowModal, the
// transfer lookups) can keep reading `row.id` without knowing the
// difference — and never fetch the raw uuid for display.
const CUSTOMERS_DISPLAY_SELECT =
  "id:customer_code, name, email, phone, warehouse, status, created_at, avatar_url";
// Archived / purged customers are hidden from the normal Customers list; they
// live in Customer Recovery. (status NULL still counts as a normal customer.)
const HIDE_ARCHIVED_CUSTOMERS =
  "status.is.null,status.not.in.(archived,purged)";

// PostgREST returns at most `max-rows` (Supabase default: 1000) rows per request
// no matter what .limit() says, so one .limit(5000) can silently cut data off.
// This loads a query in batches until everything (or `cap`) is read, and also
// reports the exact total so the UI can warn when something is left out.
// `build({ count, stable })` must return a FRESH query each call (select,
// filters, order); `count` asks for the exact total, `stable` asks for an `id`
// tiebreaker so rows with the same created_at never repeat/skip between batches.
const FETCH_BATCH = 1000;
const FETCH_ALL_CAP = 20000;
async function fetchAllRows(build, { cap = FETCH_ALL_CAP } = {}) {
  const rows = [];
  let total = null;
  let stable = true;
  while (rows.length < cap) {
    const from = rows.length;
    const to = Math.min(from + FETCH_BATCH, cap) - 1;
    const { data, error, count } = await build({
      count: from === 0,
      stable,
    }).range(from, to);
    if (error) {
      // The id tiebreaker is only an optimisation: retry once without it.
      if (from === 0 && stable) {
        stable = false;
        continue;
      }
      return { data: null, error, total, truncated: false };
    }
    if (count != null) total = count;
    const got = data ? data.length : 0;
    if (!got) break;
    rows.push(...data);
    if (total != null && rows.length >= total) break;
    if (total == null && got < to - from + 1) break;
  }
  const truncated = total != null ? rows.length < total : rows.length >= cap;
  return { data: rows, error: null, total: total ?? rows.length, truncated };
}

// Loads rows for a module from Supabase. If Supabase isn't configured, or
// the table doesn't exist yet / errors out, it falls back to the mock rows
// from MODULES so the UI never breaks.
function useTableRows(path, fallbackRows) {
  const tableName = pathToTable(path);
  const isCustomers = path === "/customers";
  const cacheKey = `cargo_bridge_${tableName}`;
  const [rows, setRows] = useState(() => {
    try {
      const raw = window.localStorage.getItem(cacheKey);
      if (raw != null) return JSON.parse(raw);
    } catch {
      // Corrupted/unavailable storage — fall through to the fallback rows.
    }
    return fallbackRows;
  });
  useEffect(() => {
    try {
      window.localStorage.setItem(cacheKey, JSON.stringify(rows.slice(0, 500)));
    } catch {
      // Storage full/unavailable — the list still works for this session.
    }
  }, [cacheKey, rows]);
  const [meta, setMeta] = useState({ total: null, truncated: false });
  const [loading, setLoading] = useState(false);
  const [ready, setReady] = useState(!supabase); // first fetch finished
  const [usingLiveData, setUsingLiveData] = useState(false);
  // Last fetch failure (null when the last fetch succeeded). Rows are NOT
  // touched on error - this only lets the UI say the list may be stale.
  const [loadError, setLoadError] = useState(null);

  const refetch = React.useCallback(async () => {
    if (!supabase) return;
    setLoading(true);
    const { data, error, total, truncated } = await fetchAllRows(
      ({ count, stable }) => {
        let q = supabase
          .from(tableName)
          .select(
            isCustomers ? CUSTOMERS_DISPLAY_SELECT : "*",
            count ? { count: "exact" } : undefined,
          );
        if (isCustomers) q = q.or(HIDE_ARCHIVED_CUSTOMERS);
        q = q.order("created_at", { ascending: false });
        return stable ? q.order("id", { ascending: false }) : q;
      },
    );
    setLoading(false);
    setReady(true);
    if (!error && data) {
      setRows(data);
      setMeta({ total, truncated });
      setUsingLiveData(true);
      setLoadError(null);
    } else if (error) {
      setLoadError({ code: error.code || "", message: error.message || "" });
    }
    // On error (e.g. table not created yet), keep showing the
    // mock rows — no need to break the page over a missing table.
  }, [tableName, isCustomers]);

  useEffect(() => {
    setReady(!supabase);
    refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tableName]);

  async function addRow(values) {
    if (supabase) {
      const { data, error } = await supabase
        .from(tableName)
        .insert(values)
        .select(isCustomers ? CUSTOMERS_DISPLAY_SELECT : "*")
        .single();
      if (error) throw error;
      setRows((prev) => [data, ...prev]);
      setUsingLiveData(true);
      return data;
    }
    // UI-only mode: just prepend locally so the page still feels alive.
    setRows((prev) => [values, ...prev]);
    return values;
  }

  function prependRow(row) {
    setRows((prev) => [row, ...prev]);
  }

  // Super Admin edit/delete (permission is enforced in the UI; add RLS in
  // Supabase for real protection). Customers are keyed by `customer_code`
  // (aliased onto `id`), every other table by its `id`.
  const keyColumn = isCustomers ? "customer_code" : "id";
  const sameRow = (a, b) => a === b || (a?.id !== undefined && a?.id === b?.id);

  async function updateRow(row, patch) {
    if (supabase && row?.id !== undefined) {
      const { data, error } = await supabase
        .from(tableName)
        .update(patch)
        .eq(keyColumn, row.id)
        .select(isCustomers ? CUSTOMERS_DISPLAY_SELECT : "*")
        .single();
      if (error) throw error;
      setRows((prev) => prev.map((r) => (sameRow(r, row) ? data : r)));
      return data;
    }
    const merged = { ...row, ...patch };
    setRows((prev) => prev.map((r) => (sameRow(r, row) ? merged : r)));
    return merged;
  }

  async function deleteRow(row, reason) {
    if (supabase && row?.id !== undefined && isCustomers) {
      // Customers are never hard-deleted: archive keeps the identity, orders,
      // wallet, addresses and history. Server enforces customer.delete.
      const { data: found, error: findErr } = await supabase
        .from("customers")
        .select("id")
        .eq("customer_code", row.id)
        .maybeSingle();
      if (findErr) throw findErr;
      if (!found?.id) throw new Error("Customer not found.");
      const { error: archErr } = await supabase.rpc("archive_customer", {
        p_customer_id: found.id,
        p_reason: reason || null,
      });
      if (archErr) {
        if (archErr.code === "42501") throw new Error(NO_PERM_MSG);
        throw archErr;
      }
      // Also block the Auth login itself (best effort; RLS + the login check
      // already stop access even if this call fails).
      callCustomerRecovery({ action: "lock", customer_code: row.id }).catch(
        () => {},
      );
      setRows((prev) => prev.filter((r) => !sameRow(r, row)));
      return;
    }
    if (supabase && row?.id !== undefined) {
      const { data, error } = await supabase
        .from(tableName)
        .delete()
        .eq(keyColumn, row.id)
        .select();
      if (error) throw error;
      if (!data?.length)
        throw new Error("Server មិនអនុញ្ញាតឱ្យលុបទេ (គ្មានសិទ្ធិ Super Admin)");
    }
    setRows((prev) => prev.filter((r) => !sameRow(r, row)));
  }

  return {
    rows,
    loading,
    ready,
    usingLiveData,
    loadError,
    refetch,
    addRow,
    prependRow,
    updateRow,
    deleteRow,
    tableName,
    total: meta.total,
    truncated: meta.truncated,
  };
}

function exportRowsToCSV(filename, columns, rows) {
  // Spreadsheet apps run a cell that starts with = + - @ as a formula, so text
  // typed by a user (a customer name, a note) could execute when staff open
  // the export. Prefix such text with an apostrophe. Plain numbers and
  // phone-style values (e.g. -5, 12.5, +855 12 345 678) are left untouched.
  const SAFE_NUMERIC = /^[+-]?\d+([.,]\d+)*$/;
  const SAFE_PHONE = /^\+[\d\s().-]+$/;
  const neutralise = (v) => {
    const s = String(v ?? "");
    return /^[=+\-@\t\r]/.test(s) &&
      !SAFE_NUMERIC.test(s) &&
      !SAFE_PHONE.test(s)
      ? `'${s}`
      : s;
  };
  const esc = (v) => `"${neutralise(v).replace(/"/g, '""')}"`;
  const header = columns.map((c) => esc(c.label)).join(",");
  const body = rows
    .map((r) => columns.map((c) => esc(c.csv ? c.csv(r) : r[c.key])).join(","))
    .join("\n");
  const blob = new Blob([`${header}\n${body}`], {
    type: "text/csv;charset=utf-8;",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

const PAGE_SIZE = 10;

// ------------------------------------------------------------
// components/CreateRowModal.jsx
// ------------------------------------------------------------
function CreateRowModal({
  open,
  title,
  columns,
  existingRows,
  onClose,
  onSubmit,
}) {
  const editableColumns = columns.filter((c) => c.key !== "id" && !c.readOnly);
  const [values, setValues] = useState({});
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  function statusOptions(key) {
    return [...new Set(existingRows.map((r) => r[key]).filter(Boolean))];
  }

  useEffect(() => {
    if (open) {
      // Pre-select the first status option for any status column so a
      // freshly scanned/created row never sits with a blank Status badge.
      const defaults = {};
      editableColumns.forEach((c) => {
        if (c.status) {
          const opts = statusOptions(c.key);
          if (opts.length > 0) defaults[c.key] = opts[0];
        }
      });
      setValues(defaults);
      setError("");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  if (!open) return null;

  async function handleSubmit(e) {
    e.preventDefault();
    setSaving(true);
    setError("");
    try {
      await onSubmit(values);
      onClose();
    } catch (err) {
      setError(err.message || "មិនអាចSaveបានទេ");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div
      className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <form
        onClick={(e) => e.stopPropagation()}
        onSubmit={handleSubmit}
        className="bg-white rounded-md shadow-lg w-full max-w-md max-h-[85vh] overflow-y-auto"
      >
        <div className="px-5 py-4 border-b border-mist-200">
          <h3 className="font-display font-bold text-base text-ink-900">
            {title}
          </h3>
        </div>
        <div className="p-5 space-y-3.5">
          {error && (
            <div className="flex items-center gap-2 text-sm text-signal-red bg-signal-red/10 rounded-md px-3 py-2">
              <TriangleAlert size={14} className="shrink-0" />
              {error}
            </div>
          )}
          {editableColumns.map((c) => {
            const options = c.status ? statusOptions(c.key) : null;
            return (
              <div key={c.key}>
                <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
                  {c.label}
                </label>
                {options && options.length > 0 ? (
                  <select
                    value={values[c.key] ?? ""}
                    onChange={(e) =>
                      setValues((v) => ({ ...v, [c.key]: e.target.value }))
                    }
                    className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
                  >
                    <option value="" disabled>
                      ជ្រើសរើស...
                    </option>
                    {options.map((opt) => (
                      <option key={opt} value={opt}>
                        {opt}
                      </option>
                    ))}
                  </select>
                ) : (
                  <input
                    value={values[c.key] ?? ""}
                    onChange={(e) =>
                      setValues((v) => ({ ...v, [c.key]: e.target.value }))
                    }
                    className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
                  />
                )}
              </div>
            );
          })}
        </div>
        <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-mist-200">
          <button
            type="button"
            onClick={onClose}
            className="text-sm font-medium text-ink-700 px-3.5 py-2 rounded-md hover:bg-mist-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving}
            className="flex items-center gap-1.5 bg-signal-blue text-white text-sm font-medium px-3.5 py-2 rounded-md hover:bg-signal-blue/90 disabled:opacity-60"
          >
            {saving ? "កំពុងSave..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

// ------------------------------------------------------------
// components/CreateCustomerAccountModal.jsx
// ------------------------------------------------------------
// Staff "New Customer": creates the Auth login (Phone + Password, same as the
// customer app's own Sign up) AND the customers row together through the
// "create-customer-account" Edge Function, so the customer can sign in at once.
const CREATE_CUSTOMER_FUNCTION = "create-customer-account-ts";

function CreateCustomerAccountModal({ open, onClose, onCreated }) {
  const [values, setValues] = useState({});
  const [show, setShow] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    if (open) {
      setValues({ password: generateTempPassword() });
      setShow(true);
      setError("");
      setCopied(false);
    }
  }, [open]);
  if (!open) return null;
  const set = (k, v) => setValues((o) => ({ ...o, [k]: v }));
  const inputCls =
    "w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue";
  const labelCls =
    "block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1";

  async function copyPw() {
    try {
      await navigator.clipboard.writeText(values.password || "");
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {}
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (saving) return;
    const name = (values.name || "").trim();
    const phone = (values.phone || "").trim();
    const password = values.password || "";
    if (!name) return setError("សូមបញ្ចូលឈ្មោះ");
    if (phone.replace(/\D/g, "").length < 6)
      return setError("លេខទូរស័ព្ទមិនត្រឹមត្រូវ");
    if (password.length < 6)
      return setError("Password ត្រូវមានយ៉ាងតិច 6 តួអក្សរ");
    setSaving(true);
    setError("");
    try {
      if (!supabase) throw new Error("Supabase មិនទាន់តភ្ជាប់");
      const { data: session } = await supabase.auth.getSession();
      const { data, error: fnError } = await supabase.functions.invoke(
        CREATE_CUSTOMER_FUNCTION,
        {
          body: { name, phone, email: (values.email || "").trim(), password },
          headers: {
            Authorization: `Bearer ${session.session?.access_token}`,
          },
        },
      );
      if (fnError) throw fnError;
      if (data?.error) throw new Error(data.error);
      onCreated(data?.data);
      onClose();
    } catch (err) {
      setError(await edgeFnErrorMessage(err, "មិនអាចបង្កើតអតិថិជនបានទេ"));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div
      className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <form
        onClick={(e) => e.stopPropagation()}
        onSubmit={handleSubmit}
        className="bg-white rounded-md shadow-lg w-full max-w-md max-h-[85vh] overflow-y-auto"
      >
        <div className="px-5 py-4 border-b border-mist-200">
          <h3 className="font-display font-bold text-base text-ink-900">
            New Customer
          </h3>
          <p className="text-xs text-ink-600/55 mt-0.5">
            អតិថិជនអាចចូលប្រើដោយ Phone + Password នេះភ្លាមៗ
          </p>
        </div>
        <div className="p-5 space-y-3.5">
          {error && (
            <div className="flex items-center gap-2 text-sm text-signal-red bg-signal-red/10 rounded-md px-3 py-2">
              <TriangleAlert size={14} className="shrink-0" />
              {error}
            </div>
          )}
          <div>
            <label className={labelCls}>Name</label>
            <input
              required
              autoFocus
              value={values.name ?? ""}
              onChange={(e) => set("name", e.target.value)}
              className={inputCls}
            />
          </div>
          <div>
            <label className={labelCls}>Phone (ប្រើសម្រាប់ Login)</label>
            <input
              required
              inputMode="tel"
              value={values.phone ?? ""}
              onChange={(e) => set("phone", e.target.value)}
              className={inputCls}
            />
          </div>
          <div>
            <label className={labelCls}>Password</label>
            <div className="flex items-center gap-2">
              <input
                required
                type={show ? "text" : "password"}
                value={values.password ?? ""}
                onChange={(e) => set("password", e.target.value)}
                className={inputCls}
              />
              <button
                type="button"
                onClick={() => setShow((v) => !v)}
                className="h-9 w-9 shrink-0 rounded-md border border-mist-200 grid place-items-center text-ink-600/60"
                aria-label="Show / hide password"
              >
                {show ? <Icons.EyeOff size={15} /> : <Icons.Eye size={15} />}
              </button>
              <button
                type="button"
                onClick={copyPw}
                className="h-9 px-2.5 shrink-0 rounded-md border border-mist-200 text-xs font-semibold text-ink-700"
              >
                {copied ? "Copied" : "Copy"}
              </button>
              <button
                type="button"
                onClick={() => set("password", generateTempPassword())}
                className="h-9 px-2.5 shrink-0 rounded-md border border-mist-200 text-xs font-semibold text-ink-700"
              >
                Generate
              </button>
            </div>
            <p className="text-xs text-ink-600/45 mt-1">
              យ៉ាងតិច 6 តួអក្សរ — ចម្លងផ្ញើជូនអតិថិជនមុនបិទ Form នេះ។
            </p>
          </div>
          <div>
            <label className={labelCls}>Email (មិនចាំបាច់)</label>
            <input
              type="email"
              value={values.email ?? ""}
              onChange={(e) => set("email", e.target.value)}
              className={inputCls}
            />
          </div>
        </div>
        <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-mist-200">
          <button
            type="button"
            onClick={onClose}
            className="text-sm font-medium text-ink-700 px-3.5 py-2 rounded-md hover:bg-mist-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving}
            className="flex items-center gap-1.5 bg-signal-blue text-white text-sm font-medium px-3.5 py-2 rounded-md hover:bg-signal-blue/90 disabled:opacity-60"
          >
            {saving ? "កំពុងបង្កើត..." : "Create"}
          </button>
        </div>
      </form>
    </div>
  );
}

// ------------------------------------------------------------
// components/CreateStaffUserModal.jsx
// ------------------------------------------------------------
// Used only for the /users module. Unlike CreateRowModal (which inserts
// straight into a table), this calls the "create-staff-user" Edge
// Function so the Auth account (Email + Password) and the `users`
// profile row get created together, atomically, with the service_role
// key staying server-side. See supabase/functions/create-staff-user.
function CreateStaffUserModal({ open, existingRows, onClose, onCreated }) {
  const [values, setValues] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const { user } = useAuth();
  useRoles(); // re-render when roles change
  const { rows: whRows } = useWarehouses();
  // Super Admin: any role. Others: only roles below their own level.
  const roleOptions = assignableRoles(user);
  const selectedRole = roleOptions.find((r) => r.name === values.role);
  const selectedDept = DEPARTMENTS.find((d) => d.name === values.department);
  const whOptions = whRows.filter(
    (w) =>
      w.status !== "Inactive" &&
      (!selectedDept?.country || w.type === selectedDept.country),
  );

  useEffect(() => {
    if (open) {
      setValues({ status: "Active" });
      setError("");
    }
  }, [open]);

  if (!open) return null;

  function set(key, val) {
    setValues((v) => ({ ...v, [key]: val }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setSaving(true);
    setError("");
    try {
      requirePermission(user, "user.create");
      assertCanAssignRole(user, values.role);
      if (selectedRole && selectedRole.scope !== "GLOBAL" && !values.department)
        throw new Error("សូមជ្រើសរើស Department");
      if (
        selectedRole &&
        ["WAREHOUSE", "BRANCH", "TEAM", "SELF"].includes(selectedRole.scope) &&
        !values.warehouse_code
      )
        throw new Error("សូមជ្រើសរើស Warehouse / Branch");
      if (!supabase) {
        // UI-only mode: no Edge Function to call — just add it locally
        // like every other mock module so the page still feels alive.
        onCreated({
          name: values.name,
          role: values.role,
          department: values.department || "",
          warehouse_code: values.warehouse_code || "",
          email: values.email,
          status: values.status || "Active",
        });
        onClose();
        return;
      }

      const { data: session } = await supabase.auth.getSession();
      const { data, error: fnError } = await supabase.functions.invoke(
        "create-staff-user",
        {
          body: values,
          headers: {
            Authorization: `Bearer ${session.session?.access_token}`,
          },
        },
      );
      if (fnError) throw fnError;
      if (data?.error) throw new Error(data.error);

      // Department / warehouse scope (needs users.department and
      // users.warehouse_code columns — see lib/permissions.js).
      await supabase
        .from("users")
        .update({
          department: values.department || null,
          warehouse_code: values.warehouse_code || null,
        })
        .eq("email", values.email);
      onCreated({
        ...data.data,
        department: values.department || "",
        warehouse_code: values.warehouse_code || "",
      });
      onClose();
    } catch (err) {
      setError(err.message || "មិនអាចបង្កើត user បានទេ");
    } finally {
      setSaving(false);
    }
  }

  const statusOptions = [
    ...new Set(existingRows.map((r) => r.status).filter(Boolean)),
  ];

  return (
    <div
      className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <form
        onClick={(e) => e.stopPropagation()}
        onSubmit={handleSubmit}
        className="bg-white rounded-md shadow-lg w-full max-w-md max-h-[85vh] overflow-y-auto"
      >
        <div className="px-5 py-4 border-b border-mist-200">
          <h3 className="font-display font-bold text-base text-ink-900">
            New User
          </h3>
        </div>
        <div className="p-5 space-y-3.5">
          {error && (
            <div className="flex items-center gap-2 text-sm text-signal-red bg-signal-red/10 rounded-md px-3 py-2">
              <TriangleAlert size={14} className="shrink-0" />
              {error}
            </div>
          )}

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Name
            </label>
            <input
              required
              value={values.name ?? ""}
              onChange={(e) => set("name", e.target.value)}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Role
            </label>
            <select
              required
              value={values.role ?? ""}
              onChange={(e) => set("role", e.target.value)}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            >
              <option value="" disabled>
                ជ្រើសរើស...
              </option>
              {roleOptions.map((r) => (
                <option key={r.name} value={r.name}>
                  {r.level == null ? r.name : `${r.name} (Level ${r.level})`}
                </option>
              ))}
            </select>
            {selectedRole && (
              <p className="text-xs text-ink-600/45 mt-1">
                Data scope: {selectedRole.scope} —{" "}
                {SCOPE_HINT[selectedRole.scope]}
              </p>
            )}
          </div>

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Department
            </label>
            <select
              required={!!selectedRole && selectedRole.scope !== "GLOBAL"}
              value={values.department ?? ""}
              onChange={(e) => {
                const d = DEPARTMENTS.find((x) => x.name === e.target.value);
                setValues((v) => ({
                  ...v,
                  department: e.target.value,
                  // drop a warehouse that no longer matches the department
                  warehouse_code:
                    d?.country &&
                    whRows.find((w) => w.code === v.warehouse_code)?.type !==
                      d.country
                      ? ""
                      : v.warehouse_code,
                }));
              }}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            >
              <option value="">—</option>
              {DEPARTMENTS.map((d) => (
                <option key={d.name} value={d.name}>
                  {d.name}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Warehouse / Branch
            </label>
            <select
              required={
                !!selectedRole &&
                ["WAREHOUSE", "BRANCH", "TEAM", "SELF"].includes(
                  selectedRole.scope,
                )
              }
              value={values.warehouse_code ?? ""}
              onChange={(e) => set("warehouse_code", e.target.value)}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            >
              <option value="">—</option>
              {whOptions.map((w) => (
                <option key={w.code} value={w.code}>
                  {w.code} — {w.name}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Email
            </label>
            <input
              required
              type="email"
              value={values.email ?? ""}
              onChange={(e) => set("email", e.target.value)}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Password
            </label>
            <div className="relative">
              <input
                required
                minLength={8}
                type={showPassword ? "text" : "password"}
                value={values.password ?? ""}
                onChange={(e) => set("password", e.target.value)}
                className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 pr-9 text-sm outline-none focus:border-signal-blue"
              />
              <button
                type="button"
                onClick={() => setShowPassword((v) => !v)}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-ink-600/40 hover:text-ink-600"
              >
                {showPassword ? <EyeOff size={15} /> : <Eye size={15} />}
              </button>
            </div>
            <p className="text-xs text-ink-600/45 mt-1">
              ផ្តល់ password នេះទៅ staff ដោយផ្ទាល់ (SMS/Telegram) — កុំផ្ញើតាម
              email ធម្មតា។
            </p>
          </div>

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Status
            </label>
            <select
              value={values.status ?? "Active"}
              onChange={(e) => set("status", e.target.value)}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            >
              {(statusOptions.length
                ? statusOptions
                : ["Active", "Suspended"]
              ).map((opt) => (
                <option key={opt} value={opt}>
                  {opt}
                </option>
              ))}
            </select>
          </div>
        </div>
        <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-mist-200">
          <button
            type="button"
            onClick={onClose}
            className="text-sm font-medium text-ink-700 px-3.5 py-2 rounded-md hover:bg-mist-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving}
            className="flex items-center gap-1.5 bg-signal-blue text-white text-sm font-medium px-3.5 py-2 rounded-md hover:bg-signal-blue/90 disabled:opacity-60"
          >
            {saving ? "កំពុងបង្កើត..." : "បង្កើត User"}
          </button>
        </div>
      </form>
    </div>
  );
}

// ------------------------------------------------------------
// components/CreateTransferModal.jsx
// ------------------------------------------------------------
// Used only for /customer-transfer. The admin must look up the TK (to
// find its current customer) and pick a NEW customer from a live search
// list — free-typing an unmatched customer never enables Confirm. On
// submit this both logs the transfer row AND moves the package's own
// `customer` field, so the TK stops showing under the old customer
// immediately instead of only appearing in a separate transfer log.
// Moves a TK to another customer. Updates the label (packages.customer),
// the real owner (packages.customer_id — what the customer sidebar, the
// customer app and RLS read) and the TK's Order. The Order moves only when
// no other TK of that order stays with the previous customer; otherwise it
// stays where it is. Returns { orderNo, orderMoved }.
async function moveTkToCustomer({
  tk,
  toCustomer,
  toLabel,
  upsertPackage,
  packages,
}) {
  const newId = toCustomer?.uuid || null;
  if (supabase) {
    const { data: before, error: readErr } = await supabase
      .from("packages")
      .select("order_no")
      .eq("tk", tk)
      .maybeSingle();
    if (readErr) throw readErr;
    const patch = { customer: toLabel };
    if (newId) patch.customer_id = newId;
    const { error: updErr } = await supabase
      .from("packages")
      .update(patch)
      .eq("tk", tk);
    if (updErr) throw updErr;
    if (newId)
      await supabase
        .from("cargo_photos")
        .update({ customer_id: newId })
        .eq("tk", tk);
    const orderNo = before?.order_no || null;
    if (!orderNo || !newId) return { orderNo, orderMoved: false };
    const { count } = await supabase
      .from("packages")
      .select("tk", { count: "exact", head: true })
      .eq("order_no", orderNo)
      .neq("tk", tk)
      .neq("customer_id", newId);
    if (count) return { orderNo, orderMoved: false };
    const { error: ordErr } = await supabase
      .from("orders")
      .update({ customer_id: newId, customer: toLabel })
      .eq("order_no", orderNo);
    if (ordErr) throw ordErr;
    return { orderNo, orderMoved: true };
  }

  // UI-only mode
  const pkg = (packages || []).find((x) => x.tk === tk);
  await upsertPackage({
    tk,
    customer: toLabel,
    ...(newId ? { customer_id: newId } : {}),
  });
  const orderNo = pkg?.order_no || null;
  if (!orderNo) return { orderNo, orderMoved: false };
  const stays = (packages || []).some(
    (x) => x.order_no === orderNo && x.tk !== tk && x.customer !== toLabel,
  );
  if (stays) return { orderNo, orderMoved: false };
  writeLocalOrders(
    readLocalOrders().map((o) =>
      o.order_no === orderNo
        ? { ...o, customer: toLabel, ...(newId ? { customer_id: newId } : {}) }
        : o,
    ),
  );
  return { orderNo, orderMoved: true };
}

function CreateTransferModal({ open, onClose, onCreated }) {
  const { user } = useAuth();
  const { findPackage, upsertPackage, packages } = usePackageTracking();
  const [tk, setTk] = useState("");
  const [tkChecked, setTkChecked] = useState(false);
  const [fromLabel, setFromLabel] = useState(null);
  const [reason, setReason] = useState("");
  const [transferType, setTransferType] = useState("uid");
  const [query, setQuery] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const { matched: selectedCustomer, loading: customerLoading } =
    useCustomerLookup(transferType, query);

  useEffect(() => {
    if (open) {
      setTk("");
      setTkChecked(false);
      setFromLabel(null);
      setReason("");
      setTransferType("uid");
      setQuery("");
      setError("");
    }
  }, [open]);

  if (!open) return null;

  // Find which customer currently owns this TK — matches the
  // "KH-000582 · Sothon Shop" combined format /packages already uses.
  async function checkTk() {
    if (!tk.trim()) return;
    if (supabase) {
      const { data } = await supabase
        .from("packages")
        .select("customer")
        .eq("tk", tk.trim())
        .maybeSingle();
      setFromLabel(data?.customer || null);
    } else {
      // Read from the live shared registry (same source Packages/TK and
      // Package Detail read from) instead of the static MODULES mock
      // rows — otherwise a real scanned TK (not one of the 5 sample rows)
      // is never found here even though it's visible everywhere else.
      const record = findPackage(tk.trim());
      setFromLabel(record?.customer || null);
    }
    setTkChecked(true);
  }

  // selectedCustomer comes from useCustomerLookup above — same UID /
  // Name / Phone lookup as the per-order Transfer modal, querying the
  // real customers table when Supabase is connected.
  const toLabel = selectedCustomer
    ? `${selectedCustomer.id} · ${selectedCustomer.name}`
    : null;
  const sameCustomer = Boolean(toLabel && fromLabel && toLabel === fromLabel);
  const canSubmit = Boolean(
    tkChecked &&
    fromLabel &&
    selectedCustomer &&
    !sameCustomer &&
    !customerLoading,
  );

  async function handleSubmit(e) {
    e.preventDefault();
    if (!canSubmit) return;
    setSaving(true);
    setError("");
    try {
      const payload = {
        tk: tk.trim(),
        from: fromLabel,
        to: toLabel,
        reason: reason || null,
        approvedBy: user?.name || null,
        status: "Resolved",
      };

      if (supabase) {
        // Move the package (and its order) to the new customer first...
        await moveTkToCustomer({
          tk: tk.trim(),
          toCustomer: selectedCustomer,
          toLabel,
        });

        // ...then log the transfer for audit history.
        const { data: row, error: insErr } = await supabase
          .from("customer_transfer")
          .insert(payload)
          .select()
          .single();
        if (insErr) throw insErr;
        onCreated(row);
      } else {
        // UI-only mode: write the new customer onto the shared package
        // registry (same store Packages/TK and Package Detail read from
        // via usePackageTracking/findPackage) instead of mutating the
        // static MODULES mock rows, which nothing actually renders from.
        await moveTkToCustomer({
          tk: tk.trim(),
          toCustomer: selectedCustomer,
          toLabel,
          upsertPackage,
          packages,
        });
        onCreated(payload);
      }
      onClose();
    } catch (err) {
      setError(err.message || "Unable to transfer.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div
      className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <form
        onClick={(e) => e.stopPropagation()}
        onSubmit={handleSubmit}
        className="bg-white rounded-md shadow-lg w-full max-w-md max-h-[85vh] overflow-y-auto"
      >
        <div className="px-5 py-4 border-b border-mist-200">
          <h3 className="font-display font-bold text-base text-ink-900">
            New Transfer
          </h3>
        </div>
        <div className="p-5 space-y-3.5">
          {error && (
            <div className="flex items-center gap-2 text-sm text-signal-red bg-signal-red/10 rounded-md px-3 py-2">
              <TriangleAlert size={14} className="shrink-0" />
              {error}
            </div>
          )}

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              TK Number
            </label>
            <input
              required
              value={tk}
              onChange={(e) => {
                setTk(e.target.value);
                setTkChecked(false);
                setFromLabel(null);
              }}
              onBlur={checkTk}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            />
            {tkChecked && (
              <p
                className={`text-xs mt-1 ${fromLabel ? "text-ink-600/55" : "text-signal-red"}`}
              >
                {fromLabel
                  ? `From: ${fromLabel}`
                  : "TK not found នេះទេ — សូមពិនិត្យលេខម្តងទៀត"}
              </p>
            )}
          </div>

          <TransferAccountLookup
            transferType={transferType}
            onTransferTypeChange={(t) => {
              setTransferType(t);
              setQuery("");
            }}
            query={query}
            onQueryChange={setQuery}
            matched={selectedCustomer}
            loading={customerLoading}
            noteText="This transfer takes effect immediately — the TK will be removed from the original customer and appear under the new customer."
          />
          {selectedCustomer && sameCustomer && (
            <p className="text-xs text-signal-red">
              This is already the same customer — please choose a different
              customer.
            </p>
          )}

          <div>
            <label className="block text-xs font-semibold text-ink-600/55 uppercase tracking-wide mb-1">
              Reason
            </label>
            <input
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              className="w-full bg-white border border-mist-200 rounded-md px-3 py-2 text-sm outline-none focus:border-signal-blue"
            />
          </div>
        </div>
        <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-mist-200">
          <button
            type="button"
            onClick={onClose}
            className="text-sm font-medium text-ink-700 px-3.5 py-2 rounded-md hover:bg-mist-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={!canSubmit || saving}
            className="flex items-center gap-1.5 bg-signal-blue text-white text-sm font-medium px-3.5 py-2 rounded-md hover:bg-signal-blue/90 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {saving ? "Transferring..." : "Confirm"}
          </button>
        </div>
      </form>
    </div>
  );
}

// ------------------------------------------------------------
// components/ListPage.jsx
// ------------------------------------------------------------
// Packages / TK, Inbound Origin, Outbound Origin and Sorting describe the
// same physical TKs at different stages, so — unlike every other module
// here, which owns its own independent mock table — these four read and
// write the one shared package registry (see PackageTrackingContext)
// instead of a separate table per page.
const LINKED_TK_PATHS = [
  "/packages",
  "/inbound-origin",
  "/outbound-origin",
  "/sorting",
];

// Each of these three pages is a live, stage-specific slice of the same
// registry — a TK sits on exactly ONE of them at a time (matching its
// current `status`), and drops off automatically once advance() moves it
// past that stage (see PackageTrackingContext). "/packages" is the one
// exception: it's the master directory, so it always lists every TK
// regardless of stage.
//
// Arrival, Customs, Cambodia Warehouse and Delivery are NOT included
// here: their columns (container/port/arrivalDate, declaration/office,
// container/expected/scanned, delivery-id/driver) describe a container,
// customs declaration, or delivery batch — not an individual TK — so a
// package's own status advancing has no single row on those pages to
// move into. Wiring them the same way would mean redesigning each of
// those pages into a per-TK list first.
const STAGE_LIST_PAGES = {
  "/inbound-origin": "Inbound Origin",
  "/outbound-origin": "Outbound Origin",
  "/sorting": "Inbound Warehouse",
};

// ------------------------------------------------------------
// components/QuickOutboundScan.jsx
// ------------------------------------------------------------
// Outbound Origin scan flow:
//   Scan TK → Validate TK → Select existing Container OR Create new
//   Container (auto CNT number) → Assign TK → TK becomes Outbound Origin
//
// No Container Number is typed by hand. Validation reuses the Container
// module's own TK rules (checkTkForContainer), the container list only
// offers containers that can still accept TKs, and the actual writes go
// through the existing store (addTks / createContainer) and the existing
// stage write path (addRow → addLinkedRow), so TK status rules and the
// Container lifecycle are untouched. Container status and TK status stay
// separate: assigning never moves a container, and the TK only ever goes
// to Outbound Origin here (never Arrived / any Cambodia status).
const OB_CSS = `
@keyframes cb-ob-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.cb-ob-in{animation:cb-ob-in .22s cubic-bezier(.2,.7,.2,1) both}
@media (prefers-reduced-motion:reduce){.cb-ob-in{animation:none}}
`;

const pad0 = (n, w = 2) => String(n).padStart(w, "0");

// CNT + YYYYMMDD + 3-digit daily sequence, e.g. CNT20260930001.
// `skip` lets the caller step past a number that turned out to be taken.
function generateContainerNumber(containers, skip = 0) {
  const d = new Date();
  const prefix = `CNT${d.getFullYear()}${pad0(d.getMonth() + 1)}${pad0(d.getDate())}`;
  let max = 0;
  (containers || []).forEach((c) => {
    const no = String(c.container_number || "").toUpperCase();
    if (!no.startsWith(prefix)) return;
    const n = parseInt(no.slice(prefix.length), 10);
    if (Number.isFinite(n) && n > max) max = n;
  });
  return `${prefix}${pad0(max + 1 + skip, 3)}`;
}

// Containers that can still take a TK at Outbound Origin: not cancelled /
// departed / arrived / sealed, and both warehouses still Active (the same
// things departChina and addTks insist on).
function eligibleOutboundContainers(containers, whRows) {
  const okWh = (code, type) => !whRows.length || whIsActive(whRows, code, type);
  return (containers || [])
    .filter((c) => {
      if (!CONTAINER_TK_EDITABLE.includes(normContainerStatus(c.status)))
        return false;
      if (c.departed_at || c.sealed_at || c.seal_number) return false;
      if (!String(c.container_number || "").trim()) return false;
      return (
        okWh(c.origin_wh_code, "china") && okWh(c.dest_wh_code, "cambodia")
      );
    })
    .sort((a, b) =>
      String(b.created_at || "").localeCompare(String(a.created_at || "")),
    );
}

// TK-only validation (no container chosen yet). Same rules as adding a TK
// to a container, plus: a TK sitting in any active container the user
// can't see is still "already assigned".
function checkTkForOutbound({ raw, packages, activeItems, containers }) {
  const key = tkKey(raw);
  const pkg = packages.find((p) => tkKey(p.tk) === key);
  const stray = pkg && activeItems.find((i) => tkKey(i.tk) === key);
  if (stray) {
    const c = containers.find((x) => x.id === stray.container_id);
    if (!c || c.status !== "Cancelled")
      return {
        ok: false,
        pkg,
        error: `TK ${pkg.tk} ត្រូវបានដាក់ក្នុង Container ${c?.container_number || "ផ្សេង"} រួចហើយ`,
      };
  }
  return checkTkForContainer({
    raw,
    container: { id: null, container_number: "", status: "Empty" },
    packages,
    activeItems,
    containers,
  });
}

function outboundContainerDefaults(pkg, whRows) {
  const china = whRows.filter(
    (w) => w.type === "china" && w.status === "Active",
  );
  const kh = whRows.filter(
    (w) => w.type === "cambodia" && w.status === "Active",
  );
  const o = pkg?.origin_wh_code || pkg?.warehouse;
  const d = pkg?.dest_branch_code;
  return {
    origin_wh_code: china.some((w) => w.code === o)
      ? o
      : china.length === 1
        ? china[0].code
        : "",
    dest_wh_code: kh.some((w) => w.code === d)
      ? d
      : kh.length === 1
        ? kh[0].code
        : "",
    container_type: "40HQ",
    shipping_method: "Sea",
  };
}

function OutboundStepper({ idx }) {
  const steps = ["Scan TK", "Container", "Outbound"];
  return (
    <ol className="flex items-center gap-1.5 text-[11px] font-medium">
      {steps.map((label, i) => {
        const done = i < idx || idx === 2;
        const active = i === idx && idx !== 2;
        return (
          <li key={label} className="flex items-center gap-1.5">
            <span
              className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 border transition-colors duration-200 ${
                done
                  ? "bg-signal-teal/10 text-signal-teal border-signal-teal/25"
                  : active
                    ? "bg-signal-blue/10 text-signal-blue border-signal-blue/30"
                    : "bg-white text-ink-600/45 border-mist-200"
              }`}
            >
              {done ? <Check size={11} /> : <span>{i + 1}</span>}
              {label}
            </span>
            {i < steps.length - 1 && (
              <span className="w-3 h-px bg-mist-200" aria-hidden="true" />
            )}
          </li>
        );
      })}
    </ol>
  );
}

// ------------------------------------------------------------
// components/QuickInboundScan.jsx
// ------------------------------------------------------------
// Inline "Scan & Inbound" box on Inbound Origin (same idea as the Outbound
// scanner). Scan a TK:
//   • TK belongs to a CN Order (Assisted Purchase) with a known Customer →
//     saved straight away: Customer auto-assigned, new THN Order, status
//     Inbound Origin, NO freight yet (charged later on Arrive).
//   • Any other TK (customer buys directly) → opens the normal full Inbound
//     form with the TK already filled in (photos / cargo / freight).
function QuickInboundScan({ focusKey = 0, onNeedForm }) {
  const { upsertPackage, syncTimelineToStatus, findPackage, logStatus } =
    usePackageTracking();
  const { user } = useAuth();
  const { rows: whList } = useWarehouses();
  const scan = useScanFeedback();
  const [value, setValue] = useState("");
  const [busy, setBusy] = useState(false);
  const [last, setLast] = useState(null);
  const debounceTimer = useRef(null);
  const busyRef = useRef(false);

  useEffect(() => {
    if (focusKey) scan.focusInput(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [focusKey]);

  async function findCnOwner(tk) {
    if (!supabase) return null;
    const { data } = await supabase
      .from("cn_order_parcels")
      .select("cn_orders(order_id,customer_id,product_name)")
      .ilike(
        "domestic_tracking",
        tk.replace(/[%_\\]/g, (m) => "\\" + m),
      )
      .limit(1);
    const cn = data?.[0]?.cn_orders;
    if (!cn?.customer_id) return null;
    const { data: c } = await supabase
      .from("customers")
      .select("id, customer_code, name, phone")
      .eq("id", cn.customer_id)
      .maybeSingle();
    return c ? { cn, customer: c } : null;
  }

  async function process(raw) {
    const tk = String(raw || "").trim();
    if (!tk || busyRef.current) return;
    if (findPackage(tk)) return scan.fail(`TK "${tk}" មានរួចហើយក្នុងប្រព័ន្ធ`);

    busyRef.current = true;
    setBusy(true);
    scan.begin();
    let newOrder = null;
    let saved = null;
    try {
      const owner = await findCnOwner(tk);
      if (!owner) {
        // Not a CN Order TK → normal inbound form (photos / cargo / freight)
        setValue("");
        scan.fail(`TK "${tk}" មិនមែនជា CN Order — បើក Form Inbound ពេញ`, false);
        onNeedForm?.(tk);
        return;
      }
      const { cn, customer } = owner;
      const userName = user?.name || "Admin";
      const nowIso = new Date().toISOString();

      const d = await readCustomerDefaults(customer.customer_code);
      const activeChina = whList.filter(
        (w) =>
          String(w.type || "").toLowerCase() === "china" &&
          String(w.status || "").toLowerCase() === "active",
      );
      const china = whIsActive(whList, d.china, "china")
        ? d.china
        : whIsActive(whList, user?.defaultWarehouse, "china")
          ? user.defaultWarehouse
          : activeChina[0]?.code || "";
      const khWanted = whIsActive(whList, d.kh, "cambodia") ? d.kh : "";
      const loc = await ensureCustomerInboundAddress(
        customer,
        khWanted,
        whList,
        userName,
      );
      const problem = validateOrderRoute(china, loc.branchCode, whList);
      if (problem) throw new Error(problem);

      const route = {
        china,
        kh: loc.branchCode,
        addressId: loc?.id || null,
      };
      newOrder = supabase
        ? await createOrderRemote(customer, "", route)
        : createLocalOrder(customer, "", route);
      saved = await upsertPackage({
        tk,
        customer_id: customer.id,
        order_id: newOrder.id,
        order_no: newOrder.order_no,
        origin_wh_code: newOrder.china_wh_code,
        dest_branch_code: newOrder.kh_branch_code,
        customer: `${customer.customer_code} · ${customer.name}`,
        product_name: cn.product_name || "",
        cargo_type: null,
        package_type: null,
        size_class: null,
        // CN Order inbound: freight is charged later, on Arrive.
        cbm: null,
        pricing_method: null,
        rate: null,
        freight_fee: null,
        freight_overridden: false,
        warehouse: newOrder.china_wh_code || china,
        status: "Inbound Origin",
        inbound_status: "Ready for Shipment",
        inbound_at: nowIso,
        created_by: userName,
        updated_by: userName,
        updated_at: nowIso,
        ...(supabase ? {} : { created_at: nowIso }),
      });
      syncTimelineToStatus(tk, "Inbound Origin", userName, "Inbound saved");
      logStatus(tk, "Ready for Shipment", userName, "Inbound saved");
      setLast({
        tk,
        customer: `${customer.customer_code} · ${customer.name}`,
        order_no: newOrder.order_no,
        cn_order: cn.order_id,
        at: formatNowTimestamp(),
      });
      setValue("");
      scan.succeed(`TK "${tk}" → Inbound Origin`);
      scan.focusInput(false);
    } catch (e) {
      if (newOrder && !saved) await rollbackNewOrder(newOrder);
      scan.fail(e?.message || "មិនអាច Inbound បានទេ");
    } finally {
      busyRef.current = false;
      setBusy(false);
    }
  }

  useEffect(() => {
    const t = value.trim();
    if (!t) return;
    debounceTimer.current = setTimeout(() => process(t), 250);
    return () => clearTimeout(debounceTimer.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  return (
    <div className="cb-surface cb-card">
      <style>{OB_CSS}</style>
      <div className="px-5 py-3.5 border-b border-mist-200">
        <h2 className="font-display font-bold text-sm text-ink-900">
          Scan &amp; Inbound
        </h2>
        <p className="text-xs text-ink-600/55">
          Scan TK របស់ CN Order → Customer ជាប់ស្វ័យប្រវត្តិ (មិនគិតថ្លៃដឹកទេ
          ចាំគិតពេល Arrive)
        </p>
      </div>
      <div className="p-5 grid gap-5 lg:grid-cols-[minmax(0,26rem)_minmax(0,1fr)] items-start">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            clearTimeout(debounceTimer.current);
            process(value);
          }}
          className="space-y-3"
        >
          <TkScanField
            value={value}
            onChange={(v) => {
              setValue(v);
              scan.onInput(v);
            }}
            scan={scan}
          />
          {busy && <p className="text-xs text-ink-600/55">កំពុង Inbound…</p>}
        </form>
        {last ? (
          <div className="cb-ob-in rounded-md border border-signal-teal/25 bg-signal-teal/10 px-4 py-3 text-xs space-y-1">
            <p className="font-semibold text-signal-teal flex items-center gap-1.5">
              <Check size={13} /> Inbound Origin បានជោគជ័យ
            </p>
            <p className="text-ink-900 font-medium">TK {last.tk}</p>
            <p className="text-ink-600/70">
              {last.customer} · {last.order_no || "—"} · {last.cn_order}
            </p>
            <p className="text-ink-600/50">{last.at}</p>
          </div>
        ) : (
          <div className="hidden lg:flex items-center justify-center min-h-[6rem] rounded-md border border-dashed border-mist-200 text-xs text-ink-600/45 text-center px-6">
            Scan TK របស់ CN Order → Inbound ភ្លាមៗ។ TK ផ្សេង (Customer
            ទិញផ្ទាល់) → បើក Form Inbound ពេញ
          </div>
        )}
      </div>
    </div>
  );
}

function QuickOutboundScan({ addRow, initialTk = "", focusKey = 0 }) {
  // Containers are no longer used here: scanning a valid TK moves it to
  // Outbound Origin immediately (same write path as before: stage row +
  // package status + timeline), with no Container step.
  const { packages } = usePackageTracking();
  const scan = useScanFeedback();
  const [value, setValue] = useState(initialTk);
  const [busy, setBusy] = useState(false);
  const [last, setLast] = useState(null);
  const debounceTimer = useRef(null);
  const busyRef = useRef(false);

  // The page's "Scan TK" button just puts the cursor back in the scan box.
  useEffect(() => {
    if (focusKey) scan.focusInput(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [focusKey]);

  async function process(raw) {
    const trimmed = String(raw || "").trim();
    if (!trimmed || busyRef.current) return;
    const key = tkKey(trimmed);
    const pkg = packages.find((p) => tkKey(p.tk) === key);

    // Validation (same rules as before, minus everything about containers)
    if (!pkg) return scan.fail(`TK not found "${trimmed}" ក្នុងប្រព័ន្ធទេ`);
    if (pkg.status === "Outbound Origin")
      return scan.fail(`TK ${pkg.tk} បាន Outbound Origin រួចហើយ`);
    if (tkCustomerParts(pkg).id === "—")
      return scan.fail(`TK ${pkg.tk} មិនមាន Customer ID ត្រឹមត្រូវ`);
    if (!String(pkg.order_no || "").trim())
      return scan.fail(`TK ${pkg.tk} មិនមាន Order ID`);
    if (pkg.inbound_status && pkg.inbound_status !== "Ready for Shipment")
      return scan.fail(
        `TK ${pkg.tk} មិនទាន់ Ready for Shipment ទេ (Inbound Status: ${pkg.inbound_status})`,
      );
    if (pkg.exception)
      return scan.fail(`TK ${pkg.tk} មាន Exception ត្រូវដោះស្រាយមុន`);
    if (pkg.status && pkg.status !== "Inbound Origin")
      return scan.fail(
        `TK ${pkg.tk} មិនអាចផ្ញើបានទេ (Status បច្ចុប្បន្ន: ${pkg.status})`,
      );

    busyRef.current = true;
    setBusy(true);
    scan.begin();
    try {
      await addRow({ tk: pkg.tk, method: "Sea" });
      const info = tkCustomerParts(pkg);
      setLast({
        tk: pkg.tk,
        customer: `${info.id} · ${info.name}`,
        order_no: pkg.order_no,
        at: formatNowTimestamp(),
      });
      setValue("");
      scan.succeed(`TK "${pkg.tk}" → Outbound Origin`);
      scan.focusInput(false);
    } catch (e) {
      scan.fail(e?.message || "មិនអាច Outbound បានទេ");
    } finally {
      busyRef.current = false;
      setBusy(false);
    }
  }

  // A scanner's burst of characters pauses briefly once done typing.
  useEffect(() => {
    const trimmed = value.trim();
    if (!trimmed) return;
    debounceTimer.current = setTimeout(() => process(trimmed), 250);
    return () => clearTimeout(debounceTimer.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  return (
    <div className="cb-surface cb-card">
      <style>{OB_CSS}</style>
      <div className="px-5 py-3.5 border-b border-mist-200">
        <h2 className="font-display font-bold text-sm text-ink-900">
          Scan &amp; Outbound
        </h2>
        <p className="text-xs text-ink-600/55">
          Scan TK → Outbound Origin ស្វ័យប្រវត្តិ
        </p>
      </div>
      <div className="p-5 grid gap-5 lg:grid-cols-[minmax(0,26rem)_minmax(0,1fr)] items-start">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            clearTimeout(debounceTimer.current);
            process(value);
          }}
          className="space-y-3"
        >
          <TkScanField
            value={value}
            onChange={(v) => {
              setValue(v);
              scan.onInput(v);
            }}
            scan={scan}
          />
          {busy && <p className="text-xs text-ink-600/55">កំពុង Outbound…</p>}
        </form>
        {last ? (
          <div className="cb-ob-in rounded-md border border-signal-teal/25 bg-signal-teal/10 px-4 py-3 text-xs space-y-1">
            <p className="font-semibold text-signal-teal flex items-center gap-1.5">
              <Check size={13} /> Outbound Origin បានជោគជ័យ
            </p>
            <p className="text-ink-900 font-medium">TK {last.tk}</p>
            <p className="text-ink-600/70">
              {last.customer} · {last.order_no || "—"}
            </p>
            <p className="text-ink-600/50">{last.at}</p>
          </div>
        ) : (
          <div className="hidden lg:flex items-center justify-center min-h-[6rem] rounded-md border border-dashed border-mist-200 text-xs text-ink-600/45 text-center px-6">
            Scan TK ណាមួយ → វានឹងក្លាយជា Outbound Origin ភ្លាមៗ
          </div>
        )}
      </div>
    </div>
  );
}

// ------------------------------------------------------------
// components/RowEditModal.jsx + RowDeleteModal.jsx  (Super Admin)
// ------------------------------------------------------------
// Select used by RowEditModal for columns that have fixed options (Users:
// role / department) or that pick from the warehouse master.
function WarehouseOptions({ value, onChange }) {
  const { rows } = useWarehouses();
  return (
    <select
      className={INPUT_CLS}
      value={value}
      onChange={(e) => onChange(e.target.value)}
    >
      <option value="">—</option>
      {value && !rows.some((w) => w.code === value) && (
        <option value={value}>{value}</option>
      )}
      {rows
        .filter((w) => w.status !== "Inactive")
        .map((w) => (
          <option key={w.code} value={w.code}>
            {w.code} — {w.name}
          </option>
        ))}
    </select>
  );
}

function OptionSelect({ column, value, onChange }) {
  if (column.optionsFrom === "warehouses")
    return <WarehouseOptions value={value} onChange={onChange} />;
  const opts = column.options || [];
  return (
    <select
      className={INPUT_CLS}
      value={value}
      onChange={(e) => onChange(e.target.value)}
    >
      <option value="">—</option>
      {value && !opts.includes(value) && <option value={value}>{value}</option>}
      {opts.map((o) => (
        <option key={o} value={o}>
          {o}
        </option>
      ))}
    </select>
  );
}

function RowEditModal({ row, columns, onSave, onClose }) {
  const editable = columns.filter(
    (c) => c.key !== "id" && !c.render && !c.linkTo,
  );
  const [f, setF] = useState(() =>
    Object.fromEntries(editable.map((c) => [c.key, row?.[c.key] ?? ""])),
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  if (!row) return null;

  async function submit(e) {
    e.preventDefault();
    const patch = {};
    editable.forEach((c) => {
      if (String(f[c.key] ?? "") !== String(row[c.key] ?? ""))
        patch[c.key] = f[c.key];
    });
    if (Object.keys(patch).length === 0) return onClose();
    setSaving(true);
    setError("");
    try {
      await onSave(patch);
      onClose();
    } catch (err) {
      setError(err.message || "មិនអាចSaveបានទេ");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div
      className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <form
        onSubmit={submit}
        onClick={(e) => e.stopPropagation()}
        className="bg-white rounded-md shadow-lg w-full max-w-md max-h-[90vh] overflow-y-auto"
      >
        <div className="flex items-center justify-between px-5 py-4 border-b border-mist-200">
          <h3 className="font-display font-bold text-lg text-ink-900">
            Edit {row.id ?? ""}
          </h3>
          <button
            type="button"
            onClick={onClose}
            className="text-ink-600/40 hover:text-ink-900"
          >
            <X size={18} />
          </button>
        </div>
        <div className="px-5 py-4 space-y-3">
          {error && <p className="text-xs text-signal-red">{error}</p>}
          {editable.map((c) => (
            <div key={c.key}>
              <label className={LABEL_CLS}>{c.label}</label>
              {c.options || c.optionsFrom ? (
                <OptionSelect
                  column={c}
                  value={f[c.key] ?? ""}
                  onChange={(val) => setF((v) => ({ ...v, [c.key]: val }))}
                />
              ) : (
                <input
                  className={INPUT_CLS}
                  value={f[c.key] ?? ""}
                  onChange={(e) =>
                    setF((v) => ({ ...v, [c.key]: e.target.value }))
                  }
                />
              )}
            </div>
          ))}
        </div>
        <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-mist-200">
          <button
            type="button"
            onClick={onClose}
            className="text-sm font-medium text-ink-700 px-4 py-2 rounded-md hover:bg-mist-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving}
            className="bg-signal-blue text-white text-sm font-medium px-4 py-2 rounded-md hover:bg-signal-blue/90 disabled:opacity-60"
          >
            {saving ? "កំពុងSave..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

// ------------------------------------------------------------
// Reset a customer's password (admin). Customers sign in with phone +
// password, so a forgotten password is fixed by setting a new one for them.
// Needs the "reset-customer-password" Edge Function (service_role key stays
// server-side) — see supabase/functions/reset-customer-password.
// ------------------------------------------------------------
// Must match the Edge Function name (slug) shown in Supabase → Edge Functions.
const RESET_PASSWORD_FUNCTION = "customer-reset_password-ts";

function generateTempPassword(len = 8) {
  const chars = "ABCDEFGHJKMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789";
  const buf = new Uint32Array(len);
  window.crypto.getRandomValues(buf);
  return Array.from(buf, (n) => chars[n % chars.length]).join("");
}

// supabase-js hides the real reason of a failed Edge Function behind
// "Edge Function returned a non-2xx status code". The reason is in the
// response body (`{ error: "..." }`), so read it from err.context.
async function edgeFnErrorMessage(err, fallback = "") {
  try {
    const text = await err?.context?.text?.();
    if (text) {
      try {
        const body = JSON.parse(text);
        return body.error || body.message || text;
      } catch {
        return text;
      }
    }
  } catch {
    /* fall through to the generic message */
  }
  return err?.message || fallback;
}

function CustomerResetPasswordModal({ row, onClose }) {
  const [pw, setPw] = useState(() => generateTempPassword());
  const [show, setShow] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [done, setDone] = useState(false);
  const [copied, setCopied] = useState(false);
  if (!row) return null;

  async function submit(e) {
    e.preventDefault();
    if (busy) return;
    if (pw.length < 6) return setError("Password ត្រូវមានយ៉ាងតិច 6 តួអក្សរ");
    setBusy(true);
    setError("");
    try {
      if (!supabase) throw new Error("Supabase មិនទាន់តភ្ជាប់");
      const { data: session } = await supabase.auth.getSession();
      const { data, error: fnError } = await supabase.functions.invoke(
        RESET_PASSWORD_FUNCTION,
        {
          body: { customer_code: row.id, new_password: pw },
          headers: {
            Authorization: `Bearer ${session.session?.access_token}`,
          },
        },
      );
      if (fnError) throw fnError;
      if (data?.error) throw new Error(data.error);
      // Force the customer to choose their OWN password on next login, so the
      // temporary password staff just saw becomes useless.
      const { error: flagErr } = await supabase
        .from("customers")
        .update({ must_change_password: true })
        .eq("customer_code", row.id);
      if (flagErr)
        emitCBToast(
          "warn",
          "Reset OK, but customer is not forced to change it",
          "Run: alter table customers add column if not exists must_change_password boolean not null default false;",
        );
      setDone(true);
      emitCBToast(
        "ok",
        "Password reset",
        `${row.name || row.id} អាចចូលប្រើដោយ Password ថ្មីបានភ្លាម។`,
      );
    } catch (err) {
      const msg = await edgeFnErrorMessage(err, "មិនអាច Reset Password បានទេ");
      setError(msg);
      emitCBToast("err", "Reset failed", msg);
    } finally {
      setBusy(false);
    }
  }

  async function copyPw() {
    try {
      await navigator.clipboard.writeText(pw);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {}
  }

  return (
    <div
      className="fixed inset-0 z-50 bg-slate-950/40 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={onClose}
    >
      <form
        onSubmit={submit}
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-md rounded-2xl bg-white shadow-2xl overflow-hidden"
      >
        <div className="px-5 py-4 border-b border-slate-200 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="w-9 h-9 rounded-xl bg-amber-50 text-amber-600 grid place-items-center">
              <Icons.KeyRound size={18} />
            </span>
            <div>
              <h3 className="font-bold text-lg text-slate-900">
                Reset Password
              </h3>
              <p className="text-xs text-slate-500">
                {row.id} · {row.name}
                {row.phone ? ` · ${row.phone}` : ""}
              </p>
            </div>
          </div>
          <button type="button" onClick={onClose}>
            <Icons.X size={18} />
          </button>
        </div>
        <div className="p-5 space-y-4">
          {error && (
            <div className="rounded-xl bg-red-50 text-red-700 px-3 py-2 text-sm">
              {error}
            </div>
          )}
          {done ? (
            <div className="rounded-xl bg-emerald-50 border border-emerald-100 p-4 space-y-2">
              <p className="text-sm font-semibold text-emerald-800">
                Reset បានជោគជ័យ — សូមផ្តល់ Password ថ្មីនេះទៅអតិថិជន
              </p>
              <div className="flex items-center gap-2">
                <code className="flex-1 rounded-lg bg-white border border-emerald-200 px-3 py-2 text-base font-bold tracking-wider text-slate-900 select-all">
                  {pw}
                </code>
                <button
                  type="button"
                  onClick={copyPw}
                  className="h-10 px-3 rounded-xl border border-emerald-200 bg-white text-sm font-semibold text-emerald-700"
                >
                  {copied ? "Copied" : "Copy"}
                </button>
              </div>
              <p className="text-xs text-emerald-700/80">
                Password នេះនឹងមិនបង្ហាញម្តងទៀតទេ បន្ទាប់ពីបិទផ្ទាំងនេះ។
              </p>
              <p className="text-xs text-emerald-700/80">
                ពេលភ្ញៀវ login ដំបូង app នឹងបង្ខំឱ្យគាត់ប្តូរទៅ Password
                ផ្ទាល់ខ្លួន ដូច្នេះ staff នឹងលែងដឹង Password របស់គាត់។
              </p>
            </div>
          ) : (
            <>
              <label className="block">
                <span className="text-xs font-semibold text-slate-500">
                  New Password
                </span>
                <div className="mt-1 flex items-center gap-2">
                  <input
                    autoFocus
                    type={show ? "text" : "password"}
                    value={pw}
                    onChange={(e) => setPw(e.target.value)}
                    className={`${INPUT_CLS} flex-1 font-mono`}
                    autoComplete="new-password"
                  />
                  <button
                    type="button"
                    onClick={() => setShow((v) => !v)}
                    className="h-10 w-10 rounded-xl border border-slate-200 grid place-items-center text-slate-500"
                    aria-label="Show / hide password"
                  >
                    {show ? (
                      <Icons.EyeOff size={16} />
                    ) : (
                      <Icons.Eye size={16} />
                    )}
                  </button>
                  <button
                    type="button"
                    onClick={() => setPw(generateTempPassword())}
                    className="h-10 px-3 rounded-xl border border-slate-200 text-sm font-semibold text-slate-700 whitespace-nowrap"
                  >
                    Generate
                  </button>
                </div>
              </label>
              <p className="text-xs text-slate-500">
                អតិថិជននឹងចូលប្រើដោយលេខទូរស័ព្ទ និង Password ថ្មីនេះភ្លាមៗ ហើយ
                Password ចាស់លែងប្រើបាន។
              </p>
            </>
          )}
        </div>
        <div className="px-5 py-4 border-t border-slate-200 flex justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className="h-10 px-4 rounded-xl border border-slate-200 text-sm font-semibold"
          >
            {done ? "Close" : "Cancel"}
          </button>
          {!done && (
            <button
              disabled={busy}
              className="h-10 px-5 rounded-xl bg-amber-600 text-white text-sm font-bold disabled:opacity-50"
            >
              {busy ? "Resetting…" : "Reset Password"}
            </button>
          )}
        </div>
      </form>
    </div>
  );
}

function RowDeleteModal({
  label,
  notice,
  onConfirm,
  onClose,
  archive = false,
}) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [reason, setReason] = useState("");
  if (!label) return null;
  return (
    <div
      className="fixed inset-0 bg-ink-900/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="bg-white rounded-md shadow-lg w-full max-w-sm"
      >
        <div className="px-5 py-4 border-b border-mist-200 flex items-center gap-2 text-signal-red">
          <TriangleAlert size={18} />
          <h3 className="font-display font-bold text-lg">
            {archive ? "Archive customer" : "Delete"}
          </h3>
        </div>
        <div className="px-5 py-4 text-sm text-ink-700 space-y-2">
          {archive ? (
            <>
              <p>
                Archive <b>{label}</b>? គណនីនឹងត្រូវផ្អាក មិនអាចចូលប្រើបានទេ
                ប៉ុន្តែ Orders, Wallet, Address និងប្រវត្តិទាំងអស់ត្រូវបានរក្សា
                ហើយអាចស្តារឡើងវិញបានពី Customer Recovery។
              </p>
              <label className="block text-xs font-medium text-ink-700">
                Reason (optional)
                <textarea
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  maxLength={300}
                  rows={2}
                  className="mt-1 w-full border border-mist-200 rounded-md px-3 py-2 text-sm"
                />
              </label>
            </>
          ) : (
            <p>
              Are you sure you want to permanently delete <b>{label}</b>{" "}
              ជាអចិន្ត្រៃយ៍មែនទេ? This action cannot be undone.
            </p>
          )}
          {notice && (
            <p className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded-md px-3 py-2">
              {notice}
            </p>
          )}
          {error && <p className="text-xs text-signal-red">{error}</p>}
        </div>
        <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-mist-200">
          <button
            type="button"
            onClick={onClose}
            className="text-sm font-medium text-ink-700 px-4 py-2 rounded-md hover:bg-mist-50"
          >
            Cancel
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={async () => {
              setBusy(true);
              setError("");
              try {
                await onConfirm(reason.trim());
                onClose();
              } catch (err) {
                setError(
                  err.message ||
                    (archive ? "Unable to archive." : "Unable to delete."),
                );
              } finally {
                setBusy(false);
              }
            }}
            className="bg-signal-red text-white text-sm font-medium px-4 py-2 rounded-md hover:bg-signal-red/90 disabled:opacity-50"
          >
            {busy
              ? archive
                ? "Archiving..."
                : "Deleting..."
              : archive
                ? "Archive"
                : "Delete"}
          </button>
        </div>
      </div>
    </div>
  );
}

// Stat cards on list pages are computed from the live server data (never
// typed in). `metric` keys come from MODULES[path].stats.
const STAT_NUM = (n, max = 0) =>
  Number(n || 0).toLocaleString("en-US", { maximumFractionDigits: max });

function computeListStat(metric, { packages, stageRows, rows }) {
  const today = new Date();
  const status = (r) => String(r?.status || "");
  switch (metric) {
    case "total":
      return STAT_NUM(rows.length);
    case "atChina":
      return STAT_NUM(
        packages.filter((p) => !p.status || p.status === "Inbound Origin")
          .length,
      );
    case "inTransit":
      return STAT_NUM(
        packages.filter((p) => IN_TRANSIT_STATUSES.includes(p.status)).length,
      );
    case "delivered":
      return STAT_NUM(packages.filter((p) => p.status === "Completed").length);
    case "receivedToday":
      return STAT_NUM(
        packages.filter((p) =>
          isSameCalendarDay(p.inbound_at || p.created_at, today),
        ).length,
      );
    case "awaitingQc":
      return STAT_NUM(
        packages.filter(
          (p) =>
            (!p.status || p.status === "Inbound Origin") &&
            ["Pending", "Received", "Measuring", "Checked"].includes(
              p.inbound_status,
            ),
        ).length,
      );
    case "notFound":
      return STAT_NUM(
        packages.filter(
          (p) =>
            (!p.status || p.status === "Inbound Origin") &&
            tkCustomerParts(p).id === "—",
        ).length,
      );
    case "totalCbm":
      return STAT_NUM(
        stageRows.reduce((s, r) => s + (Number(r.cbm) || 0), 0),
        2,
      );
    case "totalWeight":
      return STAT_NUM(
        stageRows.reduce(
          (s, r) => s + (Number(r.weight_kg ?? r.weight) || 0),
          0,
        ),
        2,
      );
    case "shipInTransit":
      return STAT_NUM(rows.filter((r) => status(r) === "In Transit").length);
    case "shipArrived":
      return STAT_NUM(rows.filter((r) => status(r) === "Arrived").length);
    case "khScanned":
      return STAT_NUM(rows.reduce((s, r) => s + (Number(r.scanned) || 0), 0));
    case "khMissing":
      return STAT_NUM(rows.reduce((s, r) => s + (Number(r.missing) || 0), 0));
    case "dlvOut":
      return STAT_NUM(
        rows.filter((r) => status(r) === "Out for Delivery").length,
      );
    case "dlvDone":
      return STAT_NUM(rows.filter((r) => status(r) === "Delivered").length);
    case "dlvFailed":
      return STAT_NUM(rows.filter((r) => /^Failed/i.test(status(r))).length);
    case "newThisMonth":
      return STAT_NUM(
        rows.filter((r) => {
          const d = new Date(r.created_at);
          return (
            !Number.isNaN(d.getTime()) &&
            d.getFullYear() === today.getFullYear() &&
            d.getMonth() === today.getMonth()
          );
        }).length,
      );
    default:
      return "—";
  }
}

// ------------------------------------------------------------
// components/StatusHistoryCard.jsx
// ------------------------------------------------------------
// Append-only log (Status / Date-Time / User / Remark). Stages reached
// before this log existed are filled in from the tracking timeline so
// older TKs still show something. China Warehouse / Admin can also move
// the Inbound Status (Pending → ... → Ready for Shipment) from here.
function StatusHistoryCard({ pkg, timeline }) {
  const { getHistory, updateInboundStatus } = usePackageTracking();
  const { user } = useAuth();
  const [status, setStatus] = useState("");
  const [remark, setRemark] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const logged = getHistory(pkg.tk);
  const loggedStatuses = new Set(logged.map((h) => h.status));
  const fromTimeline = timeline
    .filter(
      (s) => s.state !== "pending" && s.time && !loggedStatuses.has(s.label),
    )
    .map((s) => ({
      status: s.label,
      time: s.time,
      user: s.proceedBy || "System Automation",
      remark: "",
    }));
  const rows = [
    ...fromTimeline,
    ...logged.map((h) => ({
      status: h.status,
      time: formatIso(h.at),
      user: h.user,
      remark: h.remark,
    })),
  ].reverse();

  const canUpdate =
    hasPermission(user, "tk.manage_inbound") &&
    pkg.inbound_status &&
    pkg.status === "Inbound Origin";

  async function handleUpdate() {
    setError("");
    if (!status) return setError("សូមជ្រើសរើស Status");
    setBusy(true);
    try {
      await updateInboundStatus(pkg.tk, status, user?.name || "Admin", remark);
      setStatus("");
      setRemark("");
    } catch (err) {
      setError(err.message || "Unable to update.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="bg-white border border-mist-200 rounded-md shadow-panel p-5">
      <div className="flex items-center justify-between mb-4">
        <h2 className="font-display font-bold text-sm text-ink-900">
          Status History
        </h2>
        {pkg.inbound_status && (
          <span className="flex items-center gap-1.5 text-xs text-ink-600/55">
            Inbound Status <StatusBadge label={pkg.inbound_status} />
          </span>
        )}
      </div>

      {canUpdate && (
        <div className="border border-mist-200 rounded-md p-3 mb-4 bg-mist-50/60 space-y-2">
          {error && <p className="text-xs text-signal-red">{error}</p>}
          <div className="flex flex-wrap gap-2">
            <select
              value={status}
              onChange={(e) => setStatus(e.target.value)}
              className={`${INPUT_CLS} sm:max-w-[200px]`}
            >
              <option value="">Update Inbound Status...</option>
              {INBOUND_STATUSES.filter((s) => s !== pkg.inbound_status).map(
                (s) => (
                  <option key={s}>{s}</option>
                ),
              )}
            </select>
            <input
              value={remark}
              onChange={(e) => setRemark(e.target.value)}
              className={`${INPUT_CLS} flex-1 min-w-[160px]`}
            />
            <button
              type="button"
              disabled={busy}
              onClick={handleUpdate}
              className="bg-signal-blue text-white text-sm font-medium px-3.5 py-2 rounded-md hover:bg-signal-blue/90 disabled:opacity-60"
            >
              {busy ? "កំពុង Update..." : "Update"}
            </button>
          </div>
        </div>
      )}

      {rows.length === 0 ? (
        <p className="text-sm text-ink-600/45">No history yet.</p>
      ) : (
        <ol className="divide-y divide-mist-100">
          {rows.map((r, i) => (
            <li
              key={i}
              className="py-2.5 flex flex-wrap items-start gap-x-3 gap-y-1"
            >
              <StatusBadge label={r.status} />
              <div className="min-w-0">
                <div className="text-xs text-ink-600/55">
                  {r.time} · {r.user}
                </div>
                {r.remark && (
                  <div className="text-sm text-ink-800 mt-0.5">{r.remark}</div>
                )}
              </div>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

