function ListPage({
  title,
  subtitle,
  stats,
  columns,
  rows: mockRows,
  primaryAction,
  path,
}) {
  const isLinkedTk = LINKED_TK_PATHS.includes(path);
  const { user } = useAuth();
  const {
    rows: tableRows,
    ready: tableReady,
    addRow: addTableRow,
    refetch,
    prependRow,
    updateRow,
    deleteRow,
    total: tableTotal,
    truncated: tableTruncated,
    loadError: tableLoadError,
  } = useTableRows(path, []);
  const {
    packages,
    ready: packagesReady,
    upsertPackage,
    deletePackage,
    syncTimelineToStatus,
  } = usePackageTracking();
  // Edit / delete follow the module's own permission (Super Admin always).
  const canEditRows = hasPermission(user, PATH_ACTIONS[path]?.edit);
  const canDeleteRows = hasPermission(user, PATH_ACTIONS[path]?.delete);
  const [editingRow, setEditingRow] = useState(null);
  const [deletingRow, setDeletingRow] = useState(null);
  const [resetPwRow, setResetPwRow] = useState(null);
  // Customers only: how many Orders (TK + AIR) lose their owner if this
  // Customer is deleted (the DB trigger keeps them as "Deleted account").
  const [deletingOrderCount, setDeletingOrderCount] = useState(null);
  useEffect(() => {
    setDeletingOrderCount(null);
    if (path !== "/customers" || !deletingRow || !supabase) return;
    let alive = true;
    (async () => {
      try {
        const { data: cust } = await supabase
          .from("customers")
          .select("id")
          .eq("customer_code", deletingRow.id)
          .maybeSingle();
        if (!cust?.id) return;
        // Same sources as the Customer Detail header: Total TK (China)
        // = packages, AIR Orders (Indonesia) = air_orders.
        const countOf = async (table) => {
          const { count, error } = await supabase
            .from(table)
            .select("id", { count: "exact", head: true })
            .eq("customer_id", cust.id);
          return error ? 0 : (count ?? 0);
        };
        const tk = await countOf("packages");
        const air = CHINA_ONLY ? 0 : await countOf("air_orders");
        if (alive) setDeletingOrderCount({ tk, air, total: tk + air });
      } catch {
        /* the notice is optional - never block the delete dialog */
      }
    })();
    return () => {
      alive = false;
    };
  }, [path, deletingRow]);
  const canResetPassword =
    path === "/customers" && hasPermission(user, "customer.reset_password");
  const isUsersModule = path === "/users";
  const isTransferModule = path === "/customer-transfer";
  // Exceptions has no mock table of its own — it's just whichever real
  // packages (see PackageTrackingContext) currently have an `exception`
  // set, the same source the Dashboard's Exception Alerts card reads.
  const isExceptionsModule = path === "/exceptions";
  const exceptionRows = isExceptionsModule
    ? packages
        .filter((p) => p.exception)
        .map((p) => ({
          tk: p.tk,
          customer: p.customer || "—",
          status: p.exception.type,
          detail: p.exception.detail || "—",
        }))
    : [];

  // Each linked page only shows TKs currently AT its stage — once a TK
  // advances past it, it disappears from here (and shows up on whichever
  // page matches its new stage, if that page is wired to this registry).
  const stageForThisPage = STAGE_LIST_PAGES[path];
  const stageRows = stageForThisPage
    ? packages.filter((p) => p.status === stageForThisPage)
    : packages;
  // A Customer only ever sees their own TKs; everyone else sees the
  // stage list. decoratePackageRow adds display-only flat fields.
  const linkedRows = stageRows
    .filter(
      (p) =>
        user?.role !== "Customer" ||
        (user?.customerId && customerIdOf(p) === user.customerId),
    )
    .map(decoratePackageRow);

  // Scanning a TK on any of the three stage pages (Inbound/Outbound
  // Origin, Sorting) writes to the shared registry (by `tk`) instead of a
  // page-local table, so the same TK — and its Status — shows up
  // consistently across all of them. The TK itself must already exist
  // (created via Packages / TK, see CreatePackageModal) — these pages only
  // search for it and advance its stage, per the workflow spec.
  async function addLinkedRow(values) {
    const tk = String(values.tk || "").trim();
    if (!tk) throw new Error("សូមបញ្ចូល TK Number");
    const existing = packages.find(
      (p) => String(p.tk).trim().toLowerCase() === tk.toLowerCase(),
    );
    if (!existing) {
      throw new Error(
        path === "/inbound-origin"
          ? `TK not found "${tk}" ទេ — សូមបង្កើត TK នៅ Packages / TK សិន`
          : path === "/sorting"
            ? `TK not found "${tk}" ទេ — TK នេះមិនទាន់មកដល់ឃ្លាំងកម្ពុជាទេ`
            : `TK not found "${tk}" ទេ — សូម Scan TK នៅ Inbound Origin សិន`,
      );
    }

    // Outbound Origin: no Container needed any more; a TK created
    // through the New TK flow must have finished inbound processing.
    if (path === "/outbound-origin") {
      if (
        existing.inbound_status &&
        existing.inbound_status !== "Ready for Shipment"
      )
        throw new Error(
          `TK "${tk}" មិនទាន់ Ready for Shipment ទេ (Inbound Status: ${existing.inbound_status})`,
        );
    }

    const nextStatus =
      path === "/inbound-origin"
        ? "Inbound Origin"
        : path === "/outbound-origin"
          ? "Outbound Origin"
          : "Inbound Warehouse";

    // Save this stage's own operation/history row (inbound_origin /
    // outbound_origin / sorting), referencing the shared package — keeps
    // per-stage details (supplier, method, location, ...) without
    // cramming them onto the `packages` table itself.
    if (supabase) {
      const { error: stageErr } = await supabase
        .from(pathToTable(path))
        .insert({
          ...values,
          tk: existing.tk,
          package_id: existing.id,
          // outbound_origin keeps who scanned it (see outbound_origin.sql)
          ...(path === "/outbound-origin"
            ? { created_by: user?.name || "Admin" }
            : {}),
        });
      // Don't block the scan (the package status below is the source of
      // truth), but never swallow the failure silently any more — the
      // message tells you which column/policy the table is missing.
      if (stageErr) {
        console.error(`[${pathToTable(path)}] insert failed`, {
          message: stageErr.message,
          details: stageErr.details,
          hint: stageErr.hint,
          code: stageErr.code,
          payload: { ...values, tk: existing.tk, package_id: existing.id },
        });
      }
    }

    return upsertPackage({
      ...values,
      tk: existing.tk,
      status: nextStatus,
      ...(path === "/outbound-origin"
        ? {
            outboundAt: new Date().toISOString(),
            updated_by: user?.name || "Admin",
            updated_at: new Date().toISOString(),
          }
        : {}),
    }).then((saved) => {
      // Keep the Package Detail Tracking Timeline in step with this scan
      // too — upsertPackage alone only moves the record's `status`, the
      // timeline is separate state (see syncTimelineToStatus) and would
      // otherwise still show the previous stage as "active".
      syncTimelineToStatus(
        existing.tk,
        nextStatus,
        user?.name || "Admin",
        values.container_no
          ? `Container ${values.container_no}`
          : path === "/outbound-origin"
            ? "Outbound scan"
            : undefined,
      );
      return saved;
    });
  }

  const displayRows = isLinkedTk
    ? linkedRows
    : isExceptionsModule
      ? exceptionRows
      : tableRows;
  const addRow = (values) => {
    if (!canCreate) throw new Error(NO_PERM_MSG); // guard the action itself
    return (isLinkedTk ? addLinkedRow : addTableRow)(values);
  };
  // Skeleton only while the FIRST server fetch is running.
  const listLoading =
    isLinkedTk || isExceptionsModule ? !packagesReady : !tableReady;
  // Real numbers only: TKs this user may see (customers: only their own).
  const visiblePackages = packages.filter(
    (p) =>
      user?.role !== "Customer" ||
      (user?.customerId && customerIdOf(p) === user.customerId),
  );
  const liveStats = (stats || []).map((s) => ({
    ...s,
    value: computeListStat(s.metric, {
      packages: visiblePackages,
      stageRows: linkedRows,
      rows: isLinkedTk ? linkedRows : tableRows,
    }),
  }));
  // A freshly scanned TK should default to "Inbound Origin" / a real
  // outbound status, not whatever status happens to be first among
  // whatever's already in the registry.
  const statusSeedRows = isLinkedTk
    ? stageForThisPage
      ? [{ status: stageForThisPage }]
      : [{ status: "Inbound Origin" }, { status: "Hold" }]
    : displayRows;
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [showFilterMenu, setShowFilterMenu] = useState(false);
  const [page, setPage] = useState(0);
  // Package Detail's "Move to Outbound" button lands here with ?tk=...
  const [searchParams] = useSearchParams();
  const prefillTk =
    path === "/outbound-origin" ? searchParams.get("tk") || "" : "";
  // Outbound Origin has no modal any more: "Scan TK" focuses the inline scanner.
  const [showCreate, setShowCreate] = useState(
    !!prefillTk && path !== "/outbound-origin",
  );
  const [scanFocusKey, setScanFocusKey] = useState(0);
  const [formTk, setFormTk] = useState(""); // TK handed from the inline Inbound scanner
  const [adv, setAdv] = useState(EMPTY_ADV);
  const [showAdv, setShowAdv] = useState(false);
  const [dateRange, setDateRange] = useState(EMPTY_DATE_RANGE);
  // Each list page has its own date meaning (Registered / Scan In / Scan Out…),
  // so a range picked on one page must not carry over to the next.
  useEffect(() => {
    setDateRange(EMPTY_DATE_RANGE);
    setPage(0);
  }, [path]);
  const filterRef = useRef(null);

  useEffect(() => {
    function onClickOutside(e) {
      if (filterRef.current && !filterRef.current.contains(e.target))
        setShowFilterMenu(false);
    }
    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, []);

  const statusColumn = columns.find((c) => c.status);
  const dateCol = columns.find((c) => c.dateFilter);
  const statusOptions = statusColumn
    ? [...new Set(displayRows.map((r) => r[statusColumn.key]).filter(Boolean))]
    : [];

  const advCount = Object.values(adv).filter(Boolean).length;
  const filteredRows = displayRows.filter((row) => {
    const q = search.toLowerCase();
    // TK lists search Customer ID / Name, Order ID, TK and Container even
    // when a column isn't on screen; other modules search visible columns.
    const matchesSearch =
      !search ||
      (isLinkedTk
        ? [row.tk, row.customer, row.order_no, row.container_no, row.container]
        : columns.map((c) => row[c.key])
      ).some((v) =>
        String(v ?? "")
          .toLowerCase()
          .includes(q),
      );
    const matchesStatus =
      !statusFilter || row[statusColumn?.key] === statusFilter;
    const matchesDate =
      !dateCol ||
      dateInRange(
        dateCol.dateValue ? dateCol.dateValue(row) : row[dateCol.key],
        dateRange,
      );
    if (!isLinkedTk) return matchesSearch && matchesStatus && matchesDate;
    // Local calendar day (slice(0, 10) of an ISO string is UTC, which put scans
    // made 12am-7am in Cambodia on the previous day).
    const day = localDayKey(row.inbound_at || row.created_at);
    const matchesAdv =
      (!adv.inbound || row.inbound_status === adv.inbound) &&
      (!adv.outbound || outboundStatusOf(row) === adv.outbound) &&
      (!adv.cargo || row.cargo_type === adv.cargo) &&
      (!adv.size || row.size_class === adv.size) &&
      (!adv.warehouse || row.warehouse === adv.warehouse) &&
      (!adv.from || (day && day >= adv.from)) &&
      (!adv.to || (day && day <= adv.to));
    return matchesSearch && matchesStatus && matchesAdv && matchesDate;
  });

  const totalPages = Math.max(1, Math.ceil(filteredRows.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages - 1);
  const pagedRows = filteredRows.slice(
    currentPage * PAGE_SIZE,
    currentPage * PAGE_SIZE + PAGE_SIZE,
  );

  // Only warehouse/admin roles create TKs and outbound scans; Customer
  // Service, Customer and the rest get the list read-only.
  // Create needs the module's own "create" permission (Super Admin always).
  const canCreate = hasPermission(user, PATH_ACTIONS[path]?.create);

  // Load failure only applies to server-backed tables (TK lists / Exceptions
  // read the shared package registry, which has its own state).
  const tableError =
    !isLinkedTk && !isExceptionsModule && supabase ? tableLoadError : null;
  const errorInfo = tableError
    ? tableError.code === "42501"
      ? {
          icon: "Lock",
          title: "You don't have permission to view this data",
          hint: "Ask an administrator to grant access, then try again.",
        }
      : tableError.code === "42P01" || tableError.code === "PGRST205"
        ? {
            icon: "Database",
            title: "This list isn't set up yet",
            hint: "The database table for this module hasn't been created. Contact your system administrator.",
          }
        : {
            title: "Couldn't load this list",
            hint: "Check your connection and try again. Nothing was changed.",
          }
    : null;
  const hasActiveFilters = Boolean(
    search || statusFilter || advCount > 0 || dateRangeLabel(dateRange),
  );
  function clearAllFilters() {
    setSearch("");
    setStatusFilter("");
    setAdv(EMPTY_ADV);
    setDateRange(EMPTY_DATE_RANGE);
    setPage(0);
  }

  function resetToFirstPage(fn) {
    return (...args) => {
      setPage(0);
      fn(...args);
    };
  }

  return (
    <div className="space-y-5">
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="font-display font-bold text-xl text-ink-900">
            {title}
          </h1>
          {subtitle && (
            <p className="text-sm text-ink-600/55 mt-0.5">{subtitle}</p>
          )}
        </div>
        {primaryAction && canCreate && (
          <button
            onClick={() =>
              path === "/outbound-origin" || path === "/inbound-origin"
                ? setScanFocusKey((k) => k + 1)
                : setShowCreate(true)
            }
            className="flex items-center gap-1.5 bg-signal-blue text-white text-sm font-medium px-3.5 py-2 rounded-md hover:bg-signal-blue/90 transition-colors"
          >
            <Plus size={16} />
            {primaryAction}
          </button>
        )}
      </div>

      {liveStats.length > 0 &&
        (listLoading ? (
          <StatCardsSkeleton
            count={liveStats.length}
            className="grid grid-cols-2 lg:grid-cols-4 gap-3"
          />
        ) : (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
            {liveStats.map(({ metric, ...s }) => (
              <StatCard key={s.label} {...s} />
            ))}
          </div>
        ))}

      {!isLinkedTk && !isExceptionsModule && tableTruncated && (
        <div className="rounded-md bg-amber-50 text-amber-800 px-3 py-2 text-sm">
          បង្ហាញ {displayRows.length.toLocaleString("en-US")} ក្នុងចំណោម{" "}
          {Number(tableTotal).toLocaleString("en-US")} — លើសកម្រិតដែល load បាន (
          {FETCH_ALL_CAP.toLocaleString("en-US")})។ ទិន្នន័យចាស់ៗមិនទាន់បង្ហាញ
          ហើយតួលេខសរុប/overview អាចមិនពេញលេញ។
        </div>
      )}
      {path === "/customers" && !listLoading && (
        <RegistrationOverview rows={displayRows} />
      )}

      {path === "/inbound-origin" && canCreate && (
        <QuickInboundScan
          focusKey={scanFocusKey}
          onNeedForm={(tk) => {
            setFormTk(tk);
            setShowCreate(true);
          }}
        />
      )}

      {path === "/outbound-origin" && canCreate && (
        <QuickOutboundScan
          addRow={addRow}
          initialTk={prefillTk}
          focusKey={scanFocusKey}
        />
      )}

      {tableError && displayRows.length > 0 && (
        <div
          role="alert"
          className="rounded-md bg-amber-50 text-amber-800 px-3 py-2 text-sm flex items-center gap-3 flex-wrap"
        >
          <span className="flex-1 min-w-[200px]">
            Couldn't refresh this list — showing the last saved copy, which may
            be out of date.
          </span>
          <button type="button" className="cbx-btn" onClick={() => refetch()}>
            <Icon name="RefreshCw" size={15} />
            Retry
          </button>
        </div>
      )}

      <div className="cb-surface cb-card">
        {path === "/customers" && dateCol && (
          <div className="flex items-center gap-1 px-3 lg:px-4 border-b border-mist-200 overflow-x-auto">
            <ListTab
              label="All"
              count={displayRows.length}
              active={!dateRangeLabel(dateRange)}
              onClick={resetToFirstPage(() => setDateRange(EMPTY_DATE_RANGE))}
            />
            <ListTab
              label="New this month"
              count={
                displayRows.filter((r) =>
                  dateInRange(r[dateCol.key], {
                    preset: "thisMonth",
                    from: "",
                    to: "",
                  }),
                ).length
              }
              active={dateRange.preset === "thisMonth"}
              onClick={resetToFirstPage(() =>
                setDateRange({ preset: "thisMonth", from: "", to: "" }),
              )}
            />
          </div>
        )}
        <div className="flex items-center gap-2 px-4 lg:px-5 py-3.5 border-b border-mist-200 flex-wrap">
          <div className="flex items-center gap-2 bg-mist-100 rounded-md px-3 py-2 flex-1 min-w-[180px] max-w-xs">
            <Search size={15} className="text-ink-600/40" aria-hidden="true" />
            <input
              type="search"
              aria-label="Search"
              placeholder="Search…"
              value={search}
              onChange={resetToFirstPage((e) => setSearch(e.target.value))}
              className="bg-transparent outline-none text-sm w-full placeholder:text-ink-600/40"
            />
          </div>

          <div className="relative" ref={filterRef}>
            <button
              type="button"
              aria-haspopup="menu"
              aria-expanded={showFilterMenu}
              onClick={() => setShowFilterMenu((v) => !v)}
              disabled={!statusColumn}
              className="flex items-center gap-1.5 text-sm text-ink-700 border border-mist-200 px-3 py-2 rounded-md hover:bg-mist-50 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <Filter size={14} />
              {statusFilter || "ត្រង"}
            </button>
            {showFilterMenu && statusColumn && (
              <div
                role="menu"
                className="absolute left-0 mt-1 w-44 bg-white border border-mist-200 rounded-md shadow-lg py-1 z-20"
              >
                <button
                  onClick={resetToFirstPage(() => {
                    setStatusFilter("");
                    setShowFilterMenu(false);
                  })}
                  className="w-full text-left px-3 py-1.5 text-sm hover:bg-mist-50 text-ink-600/60"
                >
                  All
                </button>
                {statusOptions.map((opt) => (
                  <button
                    key={opt}
                    onClick={resetToFirstPage(() => {
                      setStatusFilter(opt);
                      setShowFilterMenu(false);
                    })}
                    className="w-full text-left px-3 py-1.5 text-sm hover:bg-mist-50 text-ink-800"
                  >
                    {opt}
                  </button>
                ))}
              </div>
            )}
          </div>

          {dateCol && (
            <DateRangeFilter
              label={dateCol.dateLabel || "Created At"}
              value={dateRange}
              onChange={resetToFirstPage(setDateRange)}
            />
          )}

          {isLinkedTk && (
            <button
              onClick={() => setShowAdv((v) => !v)}
              className="flex items-center gap-1.5 text-sm text-ink-700 border border-mist-200 px-3 py-2 rounded-md hover:bg-mist-50"
            >
              <Icons.SlidersHorizontal size={14} />
              តម្រងលម្អិត
              {advCount > 0 && (
                <span className="bg-signal-blue text-white text-[11px] px-1.5 rounded-sm">
                  {advCount}
                </span>
              )}
            </button>
          )}
          <div className="flex-1" />
          <button
            onClick={() =>
              exportRowsToCSV(`${title}.csv`, columns, filteredRows)
            }
            className="flex items-center gap-1.5 text-sm text-ink-700 border border-mist-200 px-3 py-2 rounded-md hover:bg-mist-50"
          >
            <Download size={14} />
            នាំចេញ
          </button>
        </div>
        {isLinkedTk && showAdv && (
          <AdvancedTkFilters
            adv={adv}
            setAdv={(fn) => {
              setPage(0);
              setAdv(fn);
            }}
            rows={displayRows}
            hideDates={!!dateCol}
          />
        )}
        <DataTable
          columns={columns}
          rows={pagedRows}
          loading={listLoading}
          skeletonRows={8}
          caption={title}
          error={displayRows.length === 0 ? errorInfo : null}
          onRetry={() => refetch()}
          emptyTitle={hasActiveFilters ? "No matching results" : undefined}
          emptyHint={
            hasActiveFilters
              ? "Try a different search, or clear the filters."
              : undefined
          }
          emptyAction={
            hasActiveFilters
              ? { label: "Clear filters", onClick: clearAllFilters }
              : undefined
          }
          rowActions={
            (canEditRows || canDeleteRows || canResetPassword) &&
            !isExceptionsModule &&
            !isTransferModule
              ? (row) => (
                  <div className="inline-flex items-center gap-1">
                    {canResetPassword && (
                      <RowAction
                        label="Reset Password"
                        subject={row.id}
                        icon="KeyRound"
                        tone="warn"
                        onClick={() => setResetPwRow(row)}
                      />
                    )}
                    {canEditRows &&
                      (isLinkedTk ? (
                        <RowAction
                          label="Edit"
                          subject={row.tk}
                          icon="Pencil"
                          tone="primary"
                          to={`/packages/${encodeURIComponent(row.tk)}`}
                        />
                      ) : (
                        <RowAction
                          label="Edit"
                          subject={row.id ?? row.name}
                          icon="Pencil"
                          tone="primary"
                          onClick={() => setEditingRow(row)}
                        />
                      ))}
                    {canDeleteRows && (
                      <RowAction
                        label="Delete"
                        subject={isLinkedTk ? row.tk : (row.id ?? row.name)}
                        icon="Trash2"
                        tone="danger"
                        onClick={() => setDeletingRow(row)}
                      />
                    )}
                  </div>
                )
              : undefined
          }
        />
        {canResetPassword && resetPwRow && (
          <CustomerResetPasswordModal
            key={resetPwRow.id}
            row={resetPwRow}
            onClose={() => setResetPwRow(null)}
          />
        )}
        {canEditRows && editingRow && (
          <RowEditModal
            key={editingRow.id ?? "row"}
            row={editingRow}
            columns={
              isUsersModule
                ? columns.map((c) =>
                    c.key === "role"
                      ? {
                          ...c,
                          options: assignableRoles(user).map((r) => r.name),
                        }
                      : c.key === "department"
                        ? { ...c, options: DEPARTMENTS.map((d) => d.name) }
                        : c.key === "warehouse_code"
                          ? { ...c, optionsFrom: "warehouses" }
                          : c,
                  )
                : columns
            }
            onSave={async (patch) => {
              if (!canEditRows) throw new Error(NO_PERM_MSG);
              if (isUsersModule) {
                // Role / department / warehouse changes need user.assign_role.
                if ("role" in patch) assertCanAssignRole(user, patch.role);
                else if ("department" in patch || "warehouse_code" in patch)
                  requirePermission(user, "user.assign_role");
              }
              const saved = await updateRow(editingRow, patch);
              emitCBToast(
                "ok",
                "Updated",
                `${String(editingRow.id ?? title)} was updated successfully.`,
              );
              return saved;
            }}
            onClose={() => setEditingRow(null)}
          />
        )}
        {canDeleteRows && deletingRow && (
          <RowDeleteModal
            label={
              isLinkedTk
                ? deletingRow.tk
                : String(deletingRow.id ?? deletingRow.name ?? "")
            }
            archive={path === "/customers"}
            notice={
              path === "/customers" && deletingOrderCount?.total > 0
                ? `Order សរុប ${deletingOrderCount.total} (China ${deletingOrderCount.tk} · Indo ${deletingOrderCount.air}) នៅតែភ្ជាប់ជាមួយគណនីនេះ ហើយនឹងមិនបាត់ឡើយ។ (These orders stay linked to the archived account.)`
                : null
            }
            onConfirm={async (reason) => {
              if (!canDeleteRows) throw new Error(NO_PERM_MSG);
              const delLabel = String(
                isLinkedTk
                  ? deletingRow.tk
                  : (deletingRow.id ?? deletingRow.name ?? ""),
              );
              const res = await (isLinkedTk
                ? deletePackage(deletingRow.tk)
                : deleteRow(deletingRow, reason));
              emitCBToast(
                "ok",
                path === "/customers" ? "Archived" : "Deleted",
                path === "/customers"
                  ? `${delLabel} was archived. Restore it from Customer Recovery.`
                  : `${delLabel} was deleted.`,
              );
              return res;
            }}
            onClose={() => setDeletingRow(null)}
          />
        )}
        <div className="flex items-center justify-between px-4 lg:px-5 py-3 border-t border-mist-200 text-xs text-ink-600/50">
          {listLoading ? (
            <Skeleton className="h-3 w-40" />
          ) : (
            <span>
              បង្ហាញ {pagedRows.length} នៃ {filteredRows.length} លទ្ធផល
            </span>
          )}
          <nav aria-label="Pagination" className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={currentPage === 0}
              className="px-2.5 py-1.5 rounded-sm border border-mist-200 hover:bg-mist-50 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              Previous
            </button>
            <span
              aria-current="page"
              className="px-2.5 py-1.5 rounded-sm bg-signal-blue text-white"
            >
              {currentPage + 1} / {totalPages}
            </span>
            <button
              type="button"
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={currentPage >= totalPages - 1}
              className="px-2.5 py-1.5 rounded-sm border border-mist-200 hover:bg-mist-50 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </nav>
        </div>
      </div>

      {isUsersModule ? (
        <CreateStaffUserModal
          open={showCreate}
          existingRows={tableRows}
          onClose={() => setShowCreate(false)}
          onCreated={(row) => {
            emitCBToast(
              "ok",
              "User created",
              `${row?.name || row?.email || "User"} was created successfully.`,
            );
            return supabase ? refetch() : prependRow(row);
          }}
        />
      ) : path === "/customers" && supabase ? (
        <CreateCustomerAccountModal
          open={showCreate}
          onClose={() => setShowCreate(false)}
          onCreated={(row) => {
            emitCBToast(
              "ok",
              "Customer created",
              `${row?.customer_code || ""} ${row?.name || ""} អាចចូលប្រើដោយ Phone + Password បានភ្លាម។`,
            );
            return refetch();
          }}
        />
      ) : isTransferModule ? (
        <CreateTransferModal
          open={showCreate}
          onClose={() => setShowCreate(false)}
          onCreated={(row) => {
            emitCBToast(
              "ok",
              "Transfer completed",
              `${row?.tk || "TK"} was transferred.`,
            );
            return supabase ? refetch() : prependRow(row);
          }}
        />
      ) : path === "/packages" || path === "/inbound-origin" ? (
        <CreatePackageModal
          open={showCreate}
          initialTk={formTk}
          onClose={() => {
            setShowCreate(false);
            setFormTk("");
          }}
        />
      ) : path === "/outbound-origin" ? null : path === "/arrival" ? (
        <CreateArrivalModal
          open={showCreate}
          onClose={() => setShowCreate(false)}
          onCreated={(row) => {
            emitCBToast(
              "ok",
              "Arrival created",
              `${row?.shipment_no || "Arrival"} was recorded.`,
            );
            return supabase ? refetch() : prependRow(row);
          }}
        />
      ) : (
        <CreateRowModal
          open={showCreate}
          title={primaryAction || title}
          columns={columns}
          existingRows={statusSeedRows}
          onClose={() => setShowCreate(false)}
          onSubmit={async (values) => {
            const created = await addRow(values);
            emitCBToast("ok", "Created", `${title} was created successfully.`);
            return created;
          }}
        />
      )}
    </div>
  );
}

// ------------------------------------------------------------
// context/AuthContext.jsx
// ------------------------------------------------------------
const AuthContext = createContext(null);
const MOCK_KEY = "cargo_bridge_mock_user";

// Merge the Supabase auth user with their row in `customers` (name, phone,
// customer_code...) so the rest of the app only ever deals with one shape.
async function hydrateProfile(authUser) {
  if (!authUser) return null;

  // Staff first: match by auth_user_id if already linked, else by email
  // on their very first login — then stamp auth_user_id onto that row.
  // department / warehouse_code are new columns — fall back to the old
  // select if the migration has not been run yet so nobody gets locked out.
  const staffFilter = `auth_user_id.eq.${authUser.id},email.eq.${authUser.email}`;
  let { data: staffRow, error: staffErr } = await supabase
    .from("users")
    .select(
      "id, auth_user_id, name, role, email, status, department, warehouse_code, avatar_url",
    )
    .or(staffFilter)
    .maybeSingle();
  if (staffErr) {
    ({ data: staffRow } = await supabase
      .from("users")
      .select("id, auth_user_id, name, role, email, status")
      .or(staffFilter)
      .maybeSingle());
  }

  if (staffRow) {
    if (!staffRow.auth_user_id) {
      await supabase
        .from("users")
        .update({ auth_user_id: authUser.id })
        .eq("id", staffRow.id);
    }
    // Load the shared role matrix BEFORE the first render so the user never
    // flashes a wrong "no access" page.
    await syncRolesFromServer();
    return {
      id: authUser.id,
      email: authUser.email,
      name: staffRow.name || authUser.email?.split("@")[0],
      role: staffRow.role,
      department: staffRow.department || null,
      warehouse: staffRow.warehouse_code || null,
      avatarUrl: staffRow.avatar_url || null,
      isStaff: true,
      allowedPaths: [], // recomputed live from the role matrix (withLivePaths)
    };
  }

  // Fall back to the existing customer profile flow.
  const { data } = await supabase
    .from("customers")
    .select("name, phone, customer_code, warehouse")
    .eq("auth_user_id", authUser.id)
    .maybeSingle();

  return {
    id: authUser.id,
    email: authUser.email,
    name: data?.name || authUser.email?.split("@")[0],
    phone: data?.phone || null,
    customerId: data?.customer_code || null,
    defaultWarehouse: data?.warehouse || null,
    role: "Customer",
    isStaff: false,
    allowedPaths: [], // customers have NO admin paths (admin routes are staff-only)
  };
}

export function AuthProvider({ children }) {
  const [baseUser, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  // Permissions are resolved LIVE from the role store: editing a role in
  // Role Management updates every signed-in user of that role at once.
  const rolesSnapshot = useRoles();
  const user = React.useMemo(
    () => withLivePaths(baseUser),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [baseUser, rolesSnapshot, rolesStore.version],
  );

  useEffect(() => {
    if (!supabase) {
      // UI-only mode: no backend configured yet, restore a mock session if one exists
      const saved = localStorage.getItem(MOCK_KEY);
      if (saved) setUser(JSON.parse(saved));
      setLoading(false);
      return;
    }

    // Always leave the loading state — even if restoring the session or the
    // profile fails — so a refresh can never get stuck on the skeleton.
    supabase.auth
      .getSession()
      .then(async ({ data }) => {
        setUser(await hydrateProfile(data.session?.user));
      })
      .catch(() => setUser(null))
      .finally(() => setLoading(false));

    const { data: listener } = supabase.auth.onAuthStateChange(
      async (_event, session) => {
        setUser(await hydrateProfile(session?.user));
      },
    );
    return () => listener.subscription.unsubscribe();
  }, []);

  async function login(email, password) {
    if (!supabase) {
      // No Supabase configured — accept any credentials so the UI is usable end-to-end.
      // Defaults to Super Admin so Process-Status actions stay testable before
      // the `users` table (with real roles) is wired up.
      const mockUser = {
        email,
        name: email.split("@")[0],
        role: "Super Admin",
        allowedPaths: "*",
      };
      localStorage.setItem(MOCK_KEY, JSON.stringify(mockUser));
      setUser(mockUser);
      return { error: null };
    }
    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) return { error };
    setUser(await hydrateProfile(data.user));
    return { error: null };
  }

  // Customer self-registration (blueprint section 3). Creates the auth
  // user, then a matching row in `customers` — the Customer ID comes back
  // from the `customer_code` column, generated server-side by the trigger
  // in supabase/schema.sql.
  async function signUp({ name, phone, email, password }) {
    if (!supabase) {
      const customerId = generateMockCustomerId();
      const mockUser = { email, name, phone, customerId };
      localStorage.setItem(MOCK_KEY, JSON.stringify(mockUser));
      setUser(mockUser);
      return { error: null, customerId };
    }

    const { data, error } = await supabase.auth.signUp({ email, password });
    if (error) return { error };

    if (!data.session) {
      // Email confirmation is required before a session exists — the
      // customers row (and its Customer ID) gets created on first login
      // instead, once the account is confirmed.
      return { error: null, pendingConfirmation: true };
    }

    const { data: row, error: insertError } = await supabase
      .from("customers")
      .insert({
        auth_user_id: data.user.id,
        name,
        phone,
        email,
        warehouse: "CN-GZ-01",
      })
      .select("customer_code")
      .single();

    if (insertError) return { error: insertError };

    setUser({
      id: data.user.id,
      email,
      name,
      phone,
      customerId: row.customer_code,
    });
    return { error: null, customerId: row.customer_code };
  }

  async function logout() {
    if (supabase) await supabase.auth.signOut();
    localStorage.removeItem(MOCK_KEY);
    setUser(null);
  }

  // Profile photo: update the in-memory user so the Topbar refreshes at once.
  function updateAvatar(url) {
    setUser((u) => (u ? { ...u, avatarUrl: url } : u));
  }

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        login,
        signUp,
        logout,
        updateAvatar,
        isMock: !supabase,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}

