// ------------------------------------------------------------
// pages/Dashboard.jsx
// ------------------------------------------------------------
// Everything below used to be static demo numbers (STATS/RECENT/
// EXCEPTIONS arrays with fixed values like "1,245" / "+8.2%"). All of it
// is now derived at render time from the one real, shared registry
// (usePackageTracking().packages — see PackageTrackingContext), the same
// data source Packages/TK, Inbound Origin, Outbound Origin etc. already
// read and write. No more separate hardcoded copies for the Dashboard.
//
// Two things intentionally have NO card anymore because there is no real
// field or table backing them anywhere in this app yet:
//   - "Customs Pending" — there's no Customs stage/status tracked on a
//     package (PACKAGE_STAGES has no such stage), so there's nothing real
//     to count. Add it back once a real customs-hold concept exists.
//   - Delta chips ("+8.2%", "-3") — there's no stored "yesterday" baseline
//     to diff against, so a delta can't be computed honestly. Once daily
//     snapshots exist, wire real deltas back in via the `delta` prop
//     StatCard already supports.

// A package counts toward "In Transit" for any status between having left
// origin and having actually been received into the Cambodia warehouse.
const IN_TRANSIT_STATUSES = [
  "Outbound Origin",
  "Arrived Destination",
  "Shipping To Branch",
];

function isSameCalendarDay(iso, reference) {
  if (!iso) return false;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return false;
  return (
    d.getFullYear() === reference.getFullYear() &&
    d.getMonth() === reference.getMonth() &&
    d.getDate() === reference.getDate()
  );
}

// Coarse "N min/hr/d ago" label for whatever real timestamp a package row
// happens to carry (updated_at from Supabase if present, else the most
// recent stage-specific timestamp it has).
function timeAgoLabel(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  const diffMin = Math.max(0, Math.round((Date.now() - d.getTime()) / 60000));
  if (diffMin < 1) return "just now";
  if (diffMin < 60) return `${diffMin} min ago`;
  const diffHr = Math.round(diffMin / 60);
  if (diffHr < 24) return `${diffHr} hr ago`;
  return `${Math.round(diffHr / 24)} d ago`;
}

// Most-recent real timestamp a package row carries, whichever stage it
// came from — used both to sort "Recent Activity" and to label it.
function lastActivityAt(pkg) {
  return pkg.updated_at || pkg.outboundAt || pkg.created_at || null;
}

function packageCustomerLabel(pkg) {
  // Never expose the database UUID in dashboard activity/exception lists.
  // Prefer the human-readable customer code, then the customer label.
  const raw = String(pkg.customer || "").trim();
  const UUID_RE =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const parts = raw
    .split(" · ")
    .map((v) => v.trim())
    .filter(Boolean);
  const withoutUuid = parts.filter((part) => !UUID_RE.test(part));

  if (withoutUuid.length) {
    // If the package already stores `KH-000024 · Hip hop`, keep it as-is.
    return withoutUuid.join(" · ");
  }

  const code =
    pkg.customer_code || pkg.customerCode || pkg.customer_code_display;
  if (code) {
    const name = pkg.customer_name || pkg.customerName || "";
    return name ? `${code} · ${name}` : String(code);
  }

  return pkg.customer || "Unknown Customer";
}

function statusTone(pkg) {
  if (pkg.exception) return "red";
  if (pkg.status === "Completed") return "teal";
  if (pkg.status === "Inbound Origin") return "blue";
  return "ink";
}

const DOT = {
  blue: "bg-signal-blue",
  teal: "bg-signal-teal",
  red: "bg-signal-red",
  amber: "bg-signal-amber",
  ink: "bg-ink-600",
};

// ------------------------------------------------------------
// Dashboard · AIR (Indonesia → Cambodia)
// Live counts from the AIR module (air_orders), shown next to the China
// pipeline so staff see BOTH sources on the same dashboard.
// ------------------------------------------------------------
function useAirDashboardRows() {
  const [rows, setRows] = useState([]);
  const [ready, setReady] = useState(false);
  const load = React.useCallback(async () => {
    try {
      if (!supabase) {
        setRows(airOrderLocalRows().map(normalizeAirRow));
      } else {
        const { data } = await supabase
          .from("air_orders")
          .select(
            "id, order_id, customer, shop_name, tk, status, created_at, updated_at",
          )
          .order("updated_at", { ascending: false })
          .limit(5000);
        setRows((data || []).map(normalizeAirRow));
      }
    } catch {
      setRows([]);
    }
    setReady(true);
  }, []);
  useEffect(() => {
    load();
    const onVis = () => document.visibilityState === "visible" && load();
    document.addEventListener("visibilitychange", onVis);
    const t = setInterval(load, 60000);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      clearInterval(t);
    };
  }, [load]);
  return { rows, ready, reload: load };
}

const AIR_STAGE_ICONS = {
  "Order Processing": "ClipboardList",
  "In Transit": "Plane",
  "Received at Indonesia Warehouse": "PackageCheck",
  "Departed Indonesia Warehouse": "PlaneTakeoff",
  "Received at Cambodia Warehouse": "Warehouse",
};

function AirDashboardSection() {
  const navigate = useNavigate();
  const { user: authUser } = useAuth();
  const canOpenAir = canOpenAirPages(authUser);
  const { rows, ready } = useAirDashboardRows();
  const stages = AIR_ORDER_STATUS_FLOW.filter((x) => x !== "Complete Order");
  const countOf = (label) =>
    rows.filter((r) => canonicalAirStatus(r.status) === label).length;
  const counts = stages.reduce((a, l) => ((a[l] = countOf(l)), a), {});
  const completed = countOf("Complete Order");
  const refunded = countOf(AIR_ORDER_TERMINAL);

  let activeIndex = 0;
  for (let i = stages.length - 1; i >= 0; i--) {
    if (counts[stages[i]] > 0) {
      activeIndex = i;
      break;
    }
  }
  const stageShort = {
    "Order Processing": "Order Processing",
    "In Transit": "In Transit",
    "Received at Indonesia Warehouse": "Received at Indonesia WH",
    "Departed Indonesia Warehouse": "Departed Indonesia WH",
    "Received at Cambodia Warehouse": "Received at Cambodia WH",
  };

  const stats = [
    {
      icon: "Plane",
      label: "AIR Orders (total)",
      value: String(rows.length),
      tone: "blue",
    },
    {
      icon: "PlaneTakeoff",
      label: "In Transit",
      value: String(counts["In Transit"] || 0),
      tone: "amber",
    },
    {
      icon: "Warehouse",
      label: "In Indonesia WH",
      value: String(
        (counts["Received at Indonesia Warehouse"] || 0) +
          (counts["Departed Indonesia Warehouse"] || 0),
      ),
      tone: "violet",
    },
    {
      icon: "PackageCheck",
      label: "At Cambodia WH",
      value: String(counts["Received at Cambodia Warehouse"] || 0),
      tone: "teal",
    },
    {
      icon: "RotateCcw",
      label: "Refund Orders",
      value: String(refunded),
      tone: "red",
    },
  ];

  const recent = [...rows]
    .sort(
      (a, b) =>
        new Date(b.updated_at || b.created_at || 0) -
        new Date(a.updated_at || a.created_at || 0),
    )
    .slice(0, 5);

  return (
    <div className="space-y-4">
      <PipelineCard
        flag="ID"
        title="Indonesia → Cambodia AIR Pipeline"
        subtitle="Independent AIR shipment lifecycle"
        headerBg="#ECFDF5"
        chipBg="#D1FAE5"
        chipFg="#047857"
        chip={canOpenAir ? "View AIR" : null}
        onChip={() => navigate("/air-shipments")}
        ready={ready}
        activeIndex={activeIndex}
        extra={
          <>
            <span className="px-2.5 py-1 rounded-full bg-emerald-100 text-emerald-700 font-medium">
              Complete Order — {completed}
            </span>
            <span className="px-2.5 py-1 rounded-full bg-red-100 text-red-600 font-medium">
              Refund — {refunded}
            </span>
          </>
        }
        steps={stages.map((label) => ({
          label: stageShort[label],
          count: counts[label],
          icon: AIR_STAGE_ICONS[label],
        }))}
      />

      {ready ? (
        <div className="grid grid-cols-2 lg:grid-cols-5 gap-3 cb-fade-in">
          {stats.map((st) => (
            <StatCard key={st.label} {...st} />
          ))}
        </div>
      ) : (
        <StatCardsSkeleton
          count={5}
          className="grid grid-cols-2 lg:grid-cols-5 gap-3"
        />
      )}

      <DashPanel
        icon="Clock"
        title="Recent AIR Activity"
        action={canOpenAir ? "View All" : null}
        onAction={() => navigate("/air-shipments")}
      >
        {!ready ? (
          <SkeletonListRows rows={3} />
        ) : recent.length === 0 ? (
          <p className="text-sm text-ink-600/45 px-5 py-6 text-center">
            No AIR orders yet.
          </p>
        ) : (
          <div className="px-3 pb-3 overflow-x-auto cb-fade-in">
            <table className="w-full text-left min-w-[520px]">
              <thead>
                <tr className="text-[11px] uppercase tracking-wide text-ink-600/45">
                  <th className="font-semibold px-2 py-2">Time</th>
                  <th className="font-semibold px-2 py-2">Order ID</th>
                  <th className="font-semibold px-2 py-2">Customer</th>
                  <th className="font-semibold px-2 py-2">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-mist-100">
                {recent.map((r) => (
                  <tr key={r.id || r.order_id} className="cb-table-row">
                    <td className="px-2 py-3 text-xs text-ink-600/55 whitespace-nowrap">
                      {timeAgoLabel(r.updated_at || r.created_at)}
                    </td>
                    <td className="px-2 py-3">
                      {canOpenAir ? (
                        <Link
                          to={`/air-shipments/${encodeURIComponent(r.order_id)}`}
                          className="text-sm font-semibold text-ink-900 hover:text-signal-blue"
                        >
                          {r.order_id}
                        </Link>
                      ) : (
                        <span className="text-sm font-semibold text-ink-900">
                          {r.order_id}
                        </span>
                      )}
                    </td>
                    <td className="px-2 py-3 text-xs text-ink-700 max-w-[240px] truncate">
                      {r.customer || "—"}
                      {r.shop_name ? ` · ${r.shop_name}` : ""}
                    </td>
                    <td className="px-2 py-3">
                      <AirStatusBadge status={r.status} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </DashPanel>

      <AirSlaSection />
    </div>
  );
}

