function FinancialRevenueChart({ points, currency = "USD", onSelectPoint }) {
  const [hovered, setHovered] = useState(null);
  const max = Math.max(1, ...points.map((p) => p.value));
  const shown =
    points.length > 31
      ? points.filter((_, i) => i % Math.ceil(points.length / 31) === 0)
      : points;
  return (
    <div className="px-4 pb-4 pt-3">
      <div className="mb-2 flex items-center justify-between text-[11px] text-ink-600/55">
        <span>Revenue ({currency})</span>
        <span>Hover over a bar for details</span>
      </div>
      <div className="relative flex h-60 items-end gap-1 border-b border-l border-mist-200 px-2 pb-0">
        {shown.map((p) => {
          const active = hovered?.key === p.key;
          return (
            <button
              key={p.key}
              type="button"
              className="group relative flex h-full min-w-0 flex-1 items-end justify-center rounded-t-md outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2"
              onMouseEnter={() => setHovered(p)}
              onMouseLeave={() => setHovered(null)}
              onFocus={() => setHovered(p)}
              onBlur={() => setHovered(null)}
              onClick={() => onSelectPoint?.(p)}
              aria-label={`View revenue details for ${p.key}: ${finMoney(p.value, currency)}`}
              title={`Click to view ${p.key}`}
            >
              <div
                className="pointer-events-none absolute inset-x-0 top-0 border-t border-mist-100"
                style={{ top: "25%" }}
              />
              <div
                className={`w-full max-w-8 rounded-t-md transition-all duration-300 ease-out ${active ? "bg-blue-700 shadow-lg shadow-blue-500/25 -translate-y-1 scale-x-110" : "bg-blue-500/90 group-hover:bg-blue-600 group-hover:-translate-y-0.5"}`}
                style={{
                  height: `${Math.max(p.value > 0 ? 2 : 0, (p.value / max) * 100)}%`,
                  minHeight: p.value > 0 ? 3 : 0,
                }}
              />
            </button>
          );
        })}
        {hovered && (
          <div className="pointer-events-none absolute left-3 top-3 z-20 min-w-44 rounded-xl border border-mist-200 bg-white/95 px-3 py-2.5 text-xs shadow-xl backdrop-blur-md transition-all duration-200 ease-out">
            <p className="font-semibold text-ink-900">{hovered.key}</p>
            <div className="mt-1.5 flex items-center justify-between gap-5">
              <span className="flex items-center gap-1.5 text-ink-600">
                <span className="h-2 w-2 rounded-sm bg-blue-500" />
                Total revenue
              </span>
              <strong className="tabular-nums text-ink-900">
                {finMoney(hovered.value, currency)}
              </strong>
            </div>
            {[
              ["CN Purchase Orders", hovered.cn || 0],
              ["Shipping fees (Shipment)", hovered.shipping || 0],
            ].map(([label, amount]) => (
              <div
                key={label}
                className="mt-1 flex items-center justify-between gap-5 text-[11px] text-ink-600"
              >
                <span>{label}</span>
                <span className="tabular-nums">
                  {finMoney(amount, currency)}
                </span>
              </div>
            ))}
            <p className="mt-2 border-t border-mist-100 pt-2 text-[10px] text-blue-600">
              Click bar to view this date
            </p>
          </div>
        )}
      </div>
      <div className="mt-2 flex justify-between gap-2 text-[10px] text-ink-600/55">
        <span>{shown[0]?.label || "—"}</span>
        <span>{shown[Math.floor(shown.length / 2)]?.label || "—"}</span>
        <span>{shown[shown.length - 1]?.label || "—"}</span>
      </div>
      {points.every((p) => p.value === 0) && (
        <p className="mt-3 text-center text-sm text-ink-600/55">
          No revenue recorded for this period.
        </p>
      )}
    </div>
  );
}

function FinancialPeriodPicker({ range, from, to, setRange, setFrom, setTo }) {
  const [open, setOpen] = useState(false);
  const [calendarMonth, setCalendarMonth] = useState(() => {
    const d = from ? new Date(`${from.slice(0, 10)}T12:00:00`) : new Date();
    return new Date(d.getFullYear(), d.getMonth(), 1);
  });
  const [draftStart, setDraftStart] = useState("");
  const [hoverDate, setHoverDate] = useState("");
  const today = new Date();
  const dayMs = 86400000;
  const toIso = (d) =>
    `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const fromIso = (value) =>
    value ? new Date(`${value}T12:00:00`) : new Date();
  const shiftDays = (d, n) =>
    new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
  const fmt = (value) =>
    value
      ? fromIso(value).toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        })
      : "Select date range";
  const startValue = range === "month" && from ? `${from}-01` : from;
  const endValue = range === "date" ? from : to || from;
  const displayText =
    range === "week"
      ? (() => {
          const d = fromIso(from);
          d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
          return `${fmt(toIso(d))} – ${fmt(toIso(shiftDays(d, 6)))}`;
        })()
      : range === "month"
        ? fromIso(`${from || toIso(today).slice(0, 7)}-01`).toLocaleDateString(
            "en-GB",
            { month: "long", year: "numeric" },
          )
        : range === "custom"
          ? `${fmt(from)} – ${fmt(to)}`
          : range === "last7"
            ? `Last 7 days · ${fmt(toIso(shiftDays(today, -6)))} – ${fmt(toIso(today))}`
            : range === "last30"
              ? `Last 30 days · ${fmt(toIso(shiftDays(today, -29)))} – ${fmt(toIso(today))}`
              : range === "yesterday"
                ? fmt(toIso(shiftDays(today, -1)))
                : fmt(from || toIso(today));
  const applyPreset = (preset) => {
    const now = new Date();
    const todayIso = toIso(now);
    if (preset === "today") {
      setRange("date");
      setFrom(todayIso);
      setTo("");
    }
    if (preset === "yesterday") {
      setRange("date");
      setFrom(toIso(shiftDays(now, -1)));
      setTo("");
    }
    if (preset === "last7") {
      setRange("custom");
      setFrom(toIso(shiftDays(now, -6)));
      setTo(todayIso);
    }
    if (preset === "last30") {
      setRange("custom");
      setFrom(toIso(shiftDays(now, -29)));
      setTo(todayIso);
    }
    if (preset === "thisMonth") {
      setRange("month");
      setFrom(todayIso.slice(0, 7));
      setTo("");
    }
    if (preset === "lastMonth") {
      const d = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      setRange("custom");
      setFrom(toIso(d));
      setTo(toIso(new Date(now.getFullYear(), now.getMonth(), 0)));
    }
    setDraftStart("");
    if (
      [
        "today",
        "yesterday",
        "last7",
        "last30",
        "thisMonth",
        "lastMonth",
      ].includes(preset)
    )
      setOpen(false);
  };
  const selectDay = (value) => {
    if (range === "date") {
      setFrom(value);
      setTo("");
      setOpen(false);
      return;
    }
    if (range === "week") {
      setFrom(value);
      setTo("");
      setOpen(false);
      return;
    }
    if (range === "month") {
      setFrom(value.slice(0, 7));
      setTo("");
      setOpen(false);
      return;
    }
    if (!draftStart) {
      setDraftStart(value);
      setFrom(value);
      setTo("");
      setHoverDate("");
      return;
    }
    const a = draftStart <= value ? draftStart : value;
    const b = draftStart <= value ? value : draftStart;
    setRange("custom");
    setFrom(a);
    setTo(b);
    setDraftStart("");
    setHoverDate("");
    setOpen(false);
  };
  const calendar = (monthDate) => {
    const year = monthDate.getFullYear(),
      month = monthDate.getMonth();
    const first = new Date(year, month, 1);
    const offset = (first.getDay() + 6) % 7;
    const cells = Array.from({ length: 42 }, (_, i) => {
      const d = new Date(year, month, i - offset + 1);
      return { d, value: toIso(d), inMonth: d.getMonth() === month };
    });
    const rangeEnd =
      to ||
      (draftStart && hoverDate
        ? draftStart < hoverDate
          ? hoverDate
          : draftStart
        : "");
    const rangeStart =
      draftStart && hoverDate
        ? draftStart < hoverDate
          ? draftStart
          : hoverDate
        : draftStart || from;
    return (
      <div className="min-w-0 flex-1" key={`${year}-${month}`}>
        <div className="mb-2 text-center text-[13px] font-semibold text-slate-800">
          {monthDate.toLocaleDateString("en-US", {
            month: "long",
            year: "numeric",
          })}
        </div>
        <div className="mb-2 grid grid-cols-7 border-b border-slate-100 pb-2">
          {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((x) => (
            <div
              key={x}
              className="text-center text-[10px] font-semibold text-slate-400"
            >
              {x}
            </div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-y-0.5">
          {cells.map(({ d, value, inMonth }) => {
            const selectedSingle = range === "date" && value === from;
            const isStart =
              value === (draftStart || from) &&
              (range === "custom" || range === "last7" || range === "last30");
            const isEnd = value === to && !!to;
            const between =
              !!rangeEnd &&
              !!rangeStart &&
              value >= rangeStart &&
              value <= rangeEnd;
            const isToday = value === toIso(today);
            return (
              <button
                key={value}
                type="button"
                onMouseEnter={() => draftStart && setHoverDate(value)}
                onClick={() => selectDay(value)}
                className={`relative mx-auto grid h-8 w-8 place-items-center rounded-full text-[12px] transition-all duration-150 hover:scale-105 hover:bg-blue-50 hover:text-blue-700 ${between ? "!rounded-lg bg-blue-50 text-blue-700" : ""} ${selectedSingle || isStart || isEnd ? "!bg-blue-600 !text-white shadow-md shadow-blue-600/20" : isToday ? "ring-1 ring-blue-200 text-blue-700" : inMonth ? "text-slate-700" : "text-slate-300"}`}
              >
                {d.getDate()}
              </button>
            );
          })}
        </div>
      </div>
    );
  };
  return (
    <div className="relative">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => {
          setOpen((v) => !v);
          setDraftStart("");
          setHoverDate("");
          const d = from
            ? fromIso(from.length === 7 ? `${from}-01` : from)
            : today;
          setCalendarMonth(new Date(d.getFullYear(), d.getMonth(), 1));
        }}
        className={`flex h-11 min-w-[250px] max-w-full items-center gap-2 rounded-xl border bg-white px-3 text-left text-sm font-medium text-slate-700 shadow-sm transition-all hover:border-blue-300 hover:shadow-md focus:outline-none focus:ring-2 focus:ring-blue-500/20 ${open ? "border-blue-500 ring-2 ring-blue-500/10" : "border-slate-200"}`}
      >
        <Icon
          name="CalendarDays"
          size={16}
          className="shrink-0 text-slate-400"
        />
        <span className="min-w-0 flex-1 truncate">{displayText}</span>
        <Icon
          name={open ? "ChevronUp" : "ChevronDown"}
          size={15}
          className="shrink-0 text-slate-400"
        />
      </button>
      {open && (
        <>
          <button
            type="button"
            aria-label="Close date picker"
            className="fixed inset-0 z-[80] cursor-default"
            onClick={() => {
              setOpen(false);
              setDraftStart("");
            }}
          />
          <div
            className="jenz-period-pop absolute right-0 z-[90] mt-2 w-[min(94vw,500px)] overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl shadow-slate-900/15"
            style={{
              animation: "jenzCalendarIn .18s cubic-bezier(.2,.8,.2,1)",
            }}
          >
            <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-4 py-3 sm:px-5">
              <div>
                <p className="text-sm font-semibold text-slate-800">
                  Select reporting period
                </p>
                <p className="mt-0.5 text-xs text-slate-400">
                  {draftStart
                    ? "Choose an end date"
                    : "Choose a preset or select dates"}
                </p>
              </div>
              <select
                aria-label="Calendar period type"
                value={
                  range === "custom" ||
                  range === "last7" ||
                  range === "last30" ||
                  range === "yesterday"
                    ? "custom"
                    : range
                }
                onChange={(e) => {
                  const next = e.target.value;
                  setRange(next);
                  setDraftStart("");
                  if (next === "date") {
                    setFrom(toIso(today));
                    setTo("");
                  } else if (next === "week") {
                    setFrom(toIso(today));
                    setTo("");
                  } else if (next === "month") {
                    setFrom(toIso(today).slice(0, 7));
                    setTo("");
                  } else {
                    setRange("custom");
                    setFrom("");
                    setTo("");
                  }
                }}
                className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-blue-500"
              >
                <option value="date">Date</option>
                <option value="week">Week</option>
                <option value="month">Month</option>
                <option value="custom">Custom range</option>
              </select>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-[112px_minmax(0,1fr)]">
              <div className="border-b border-slate-100 p-2 sm:border-b-0 sm:border-r sm:p-2">
                {[
                  ["today", "Today"],
                  ["yesterday", "Yesterday"],
                  ["last7", "Last 7 days"],
                  ["last30", "Last 30 days"],
                  ["thisMonth", "This month"],
                  ["lastMonth", "Last month"],
                ].map(([key, label]) => (
                  <button
                    key={key}
                    type="button"
                    onClick={() => applyPreset(key)}
                    className="block w-full rounded-lg px-2.5 py-2 text-left text-[13px] text-slate-600 transition-colors hover:bg-blue-50 hover:text-blue-700"
                  >
                    {label}
                  </button>
                ))}
                <div className="mt-1.5 border-t border-slate-100 px-2 pt-2 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-400">
                  Custom range
                </div>
                <div className="px-2 pb-1 pt-1 text-[11px] text-slate-500">
                  {from && to
                    ? `${fmt(from)} – ${fmt(to)}`
                    : draftStart
                      ? `Start: ${fmt(draftStart)}`
                      : "Select start and end"}
                </div>
              </div>
              <div className="min-w-0 p-3">
                <div className="mb-3 flex items-center justify-between gap-2">
                  <button
                    type="button"
                    aria-label="Previous month"
                    onClick={() =>
                      setCalendarMonth(
                        new Date(
                          calendarMonth.getFullYear(),
                          calendarMonth.getMonth() - 1,
                          1,
                        ),
                      )
                    }
                    className="grid h-8 w-8 place-items-center rounded-lg text-slate-500 transition hover:bg-blue-50 hover:text-blue-700"
                  >
                    <Icon name="ChevronLeft" size={17} />
                  </button>
                  <div className="text-xs text-slate-400">
                    {draftStart ? "Select the end date" : "Select a date"}
                  </div>
                  <button
                    type="button"
                    aria-label="Next month"
                    onClick={() =>
                      setCalendarMonth(
                        new Date(
                          calendarMonth.getFullYear(),
                          calendarMonth.getMonth() + 1,
                          1,
                        ),
                      )
                    }
                    className="grid h-8 w-8 place-items-center rounded-lg text-slate-500 transition hover:bg-blue-50 hover:text-blue-700"
                  >
                    <Icon name="ChevronRight" size={17} />
                  </button>
                </div>
                <div className="mx-auto w-full max-w-[280px]">
                  {calendar(calendarMonth)}
                </div>
                <div className="mt-3 flex flex-wrap items-center justify-between gap-2 border-t border-slate-100 pt-2">
                  <button
                    type="button"
                    onClick={() => {
                      setRange("date");
                      setFrom("");
                      setTo("");
                      setDraftStart("");
                    }}
                    className="rounded-lg px-3 py-2 text-sm text-slate-500 transition hover:bg-slate-100"
                  >
                    Clear
                  </button>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => applyPreset("today")}
                      className="rounded-lg px-3 py-2 text-sm font-medium text-blue-600 transition hover:bg-blue-50"
                    >
                      Today
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        if (range === "custom" && from && to) setOpen(false);
                        else if (draftStart && to) setOpen(false);
                        else if (draftStart) {
                          setFrom(draftStart);
                          setTo(draftStart);
                          setRange("custom");
                          setDraftStart("");
                          setOpen(false);
                        }
                      }}
                      className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700"
                    >
                      Apply
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

function FinancialDashboard({ showChina, onRefresh, refreshing }) {
  const localToday = () => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  };
  const [range, setRange] = useState("date");
  const [from, setFrom] = useState(localToday());
  const [to, setTo] = useState("");
  const [view, setView] = useState("chart");
  const [rows, setRows] = useState({
    cn: [],
    packages: [],
    wallet: [],
    costs: [],
  });
  const [loading, setLoading] = useState(true);
  const [errors, setErrors] = useState([]);
  const [lastUpdated, setLastUpdated] = useState(null);

  const load = React.useCallback(async () => {
    if (!supabase) {
      setErrors([
        "Supabase is not configured. Financial figures cannot be loaded.",
      ]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const tasks = await Promise.all([
      showChina
        ? supabase
            .from("cn_orders")
            .select("*")
            .order("created_at", { ascending: false })
            .limit(10000)
        : Promise.resolve({ data: [], error: null }),
      showChina
        ? supabase
            .from("packages")
            .select(
              "id,tk,status,freight_fee,paid_amount,created_at,updated_at,customer_id,cn_order_id",
            )
            .order("created_at", { ascending: false })
            .limit(20000)
        : Promise.resolve({ data: [], error: null }),
      supabase
        .from("wallet_transactions")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(10000),
      // Internal actual cost (USD) per CN order. Staff-only table; a missing
      // table / no permission just means "no costs recorded yet".
      showChina
        ? supabase
            .from("cn_order_costs")
            .select("cn_order_id,actual_cost_usd")
            .limit(20000)
        : Promise.resolve({ data: [], error: null }),
    ]);
    const labels = [
      "CN Purchase Orders",
      "Shipping fees",
      "Wallet activity",
      "CN order costs",
    ];
    const nextErrors = tasks
      .map((r, i) =>
        r?.error && i !== 3
          ? `${labels[i]}: ${r.error.message || "Unable to load data"}`
          : null,
      )
      .filter(Boolean);
    setRows({
      cn: tasks[0]?.data || [],
      packages: tasks[1]?.data || [],
      wallet: tasks[2]?.data || [],
      costs: tasks[3]?.error ? [] : tasks[3]?.data || [],
    });
    setErrors(nextErrors);
    setLastUpdated(new Date());
    setLoading(false);
  }, [showChina]);

  useEffect(() => {
    load();
    const timer = setInterval(load, 60000);
    return () => clearInterval(timer);
  }, [load]);

  const [start, end] = financialRangeBounds(range, from, to);
  const scoped = (list) => list.filter((r) => finDateInRange(r, start, end));
  const cn = scoped(rows.cn);
  const packages = scoped(rows.packages);
  const wallet = scoped(rows.wallet);
  const activeCn = cn.filter((r) => !finIsRefunded(r));
  const cnRevenue = activeCn.reduce((s, r) => s + finCharge(r), 0);
  // Shipping fee revenue = Shipment packages only. A TK linked to a CN order
  // (Parse Link) is already inside that order's total, so it is skipped.
  const shippingRows = packages.filter(
    (r) =>
      !r.cn_order_id &&
      r.freight_fee !== null &&
      r.freight_fee !== undefined &&
      String(r.freight_fee).trim() !== "" &&
      Number.isFinite(Number(r.freight_fee)),
  );
  const shippingRevenue = shippingRows.reduce(
    (s, r) => s + Math.max(0, Number(r.freight_fee) || 0),
    0,
  );
  const totalRevenue = cnRevenue + shippingRevenue;
  const totalCollected =
    activeCn.reduce((s, r) => s + finPaid(r), 0) +
    shippingRows.reduce(
      (s, r) => s + Math.max(0, finNum(r.paid_amount) ?? 0),
      0,
    );
  const outstanding = Math.max(
    0,
    activeCn.reduce((s, r) => s + Math.max(0, finCharge(r) - finPaid(r)), 0) +
      shippingRows.reduce(
        (s, r) =>
          s +
          Math.max(
            0,
            (Number(r.freight_fee) || 0) - (Number(r.paid_amount) || 0),
          ),
        0,
      ),
  );
  const refundedCn = cn
    .filter(finIsRefunded)
    .reduce(
      (s, r) =>
        s +
        (finNum(
          r.refund_amount_usd,
          r.refunded_amount_usd,
          r.amount_refunded_usd,
          r.amount_paid_usd,
        ) ?? 0),
      0,
    );
  const refunds = refundedCn;
  // Actual cost per CN order: the staff-only USD cost first, then the older
  // CNY/rate fields. A missing cost is never treated as zero.
  const costByOrder = new Map(
    (rows.costs || []).map((c) => [
      String(c.cn_order_id),
      finNum(c.actual_cost_usd),
    ]),
  );
  const purchaseCosts = activeCn.map(
    (r) => costByOrder.get(String(r.id)) ?? finPurchaseCost(r),
  );
  const costComplete =
    purchaseCosts.length > 0 && purchaseCosts.every((v) => v !== null);
  const costCount = purchaseCosts.filter((v) => v !== null).length;
  const purchaseAmount = purchaseCosts.reduce((s, v) => s + (v ?? 0), 0);
  // Purchase Profit = billed charge - actual cost, only for orders whose
  // cost is known. Shipment shipping fees have no cost field yet, so they
  // are not part of this profit figure.
  const purchaseProfit =
    costCount > 0
      ? activeCn.reduce((sum, r, i) => {
          const cost = purchaseCosts[i];
          return cost === null ? sum : sum + (finCharge(r) - cost);
        }, 0)
      : null;
  const walletTopups = wallet
    .filter((r) =>
      ["top_up", "deposit", "credit", "topup"].includes(
        String(r.type || "").toLowerCase(),
      ),
    )
    .reduce(
      (s, r) => s + Math.abs(finNum(r.amount, r.amount_usd, r.value) ?? 0),
      0,
    );
  const walletWithdrawals = wallet
    .filter((r) =>
      ["withdraw", "withdrawal", "debit", "top_up_reversal"].includes(
        String(r.type || "").toLowerCase(),
      ),
    )
    .reduce(
      (s, r) => s + Math.abs(finNum(r.amount, r.amount_usd, r.value) ?? 0),
      0,
    );

  const chartPoints = useMemo(() => {
    const all = [
      ...cn
        .filter((r) => !finIsRefunded(r))
        .map((r) => ({
          date: r.created_at,
          amount: finCharge(r),
          source: "cn",
        })),
      ...shippingRows.map((r) => ({
        date: r.created_at,
        amount: Math.max(0, Number(r.freight_fee) || 0),
        source: "shipping",
      })),
    ];
    const map = new Map();
    all.forEach((r) => {
      if (!r.date) return;
      const d = new Date(r.date);
      if (Number.isNaN(d.getTime())) return;
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
      const item = map.get(key) || { value: 0, cn: 0, shipping: 0 };
      item.value += r.amount;
      item[r.source] += r.amount;
      map.set(key, item);
    });
    const days = [];
    if (start && end) {
      for (
        let d = new Date(start);
        d < end && days.length < 370;
        d.setDate(d.getDate() + 1)
      ) {
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
        const amounts = map.get(key) || {
          value: 0,
          cn: 0,
          shipping: 0,
        };
        days.push({
          key,
          label: `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`,
          ...amounts,
        });
      }
    } else {
      [...map.keys()].sort().forEach((key) =>
        days.push({
          key,
          label: key.slice(5).replace("-", "/"),
          ...map.get(key),
        }),
      );
    }
    return days;
  }, [rows, range, from, to, showChina]);

  const dateText =
    start && end
      ? `${start.toLocaleDateString("en-GB")} – ${new Date(end.getTime() - 86400000).toLocaleDateString("en-GB")}`
      : "All dates";
  const statCards = [
    {
      label: "Total Revenue",
      value: finMoney(totalRevenue),
      detail: "CN orders + Shipment shipping fees",
      tone: "blue",
      icon: "TrendingUp",
    },
    {
      label: "Total Collected",
      value: finMoney(totalCollected),
      detail: "Recorded payments only",
      tone: "green",
      icon: "Wallet",
    },
    {
      label: "Outstanding Balance",
      value: finMoney(outstanding),
      detail: "Unpaid customer charges",
      tone: "amber",
      icon: "Clock3",
    },
    {
      label: "Purchase Amount",
      value: finMoney(purchaseAmount),
      detail: costComplete
        ? "Actual costs available"
        : `${costCount} of ${purchaseCosts.length} CN orders have cost`,
      tone: "violet",
      icon: "ShoppingCart",
    },
    {
      label: "Refunds",
      value: finMoney(refunds),
      detail: "Refunded CN orders",
      tone: "red",
      icon: "RotateCcw",
    },
    {
      label: "Purchase Profit (CN Orders)",
      value:
        purchaseProfit === null ? "Cost pending" : finMoney(purchaseProfit),
      detail:
        purchaseProfit === null
          ? "No actual cost recorded yet"
          : costComplete
            ? purchaseProfit >= 0
              ? "Billed amount less actual cost"
              : "Actual cost exceeds billed amount"
            : `Only the ${costCount} orders that have cost`,
      tone:
        purchaseProfit === null
          ? "slate"
          : purchaseProfit >= 0
            ? "green"
            : "red",
      icon: "Scale",
    },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="cbx-h1 cb-page-title text-2xl font-bold tracking-tight">
            Financial &amp; Business Overview
          </h1>
          <p className="cbx-sub mt-1 text-sm">
            Revenue, collections, balances and purchase performance from
            recorded system data.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className="cbx-pill">
            {new Date().toLocaleDateString("en-GB", {
              weekday: "short",
              day: "2-digit",
              month: "short",
              year: "numeric",
            })}
          </span>
          <button
            type="button"
            className="cbx-btn"
            onClick={async () => {
              await load();
              await onRefresh?.();
            }}
            disabled={loading || refreshing}
          >
            <Icon
              name="RefreshCw"
              size={15}
              className={loading || refreshing ? "animate-spin" : ""}
            />{" "}
            Refresh
          </button>
        </div>
      </div>

      <div className="cb-surface rounded-2xl border border-mist-100 p-3 sm:p-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <p className="text-sm font-semibold text-ink-900">
              Reporting period
            </p>
            <p className="mt-0.5 text-xs text-ink-600/55">
              {dateText}
              {lastUpdated
                ? ` · Updated ${lastUpdated.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })}`
                : ""}
            </p>
          </div>
          <div className="flex items-end gap-2.5">
            <FinancialPeriodPicker
              range={range}
              from={from}
              to={to}
              setRange={setRange}
              setFrom={setFrom}
              setTo={setTo}
            />
          </div>
        </div>
      </div>

      {errors.length > 0 && (
        <div
          role="alert"
          className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900"
        >
          <p className="font-semibold">
            Some financial sources could not be loaded.
          </p>
          <ul className="mt-1 list-disc pl-5">
            {errors.map((e) => (
              <li key={e}>{e}</li>
            ))}
          </ul>
          <p className="mt-1 text-xs">
            Displayed totals may be incomplete. Check Supabase table access and
            Row Level Security policies.
          </p>
        </div>
      )}

      {loading ? (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {Array.from({ length: 6 }, (_, i) => (
            <div
              key={i}
              className="cb-surface h-32 animate-pulse rounded-2xl border border-mist-100 bg-mist-50"
            />
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {statCards.map((card) => (
            <FinancialStat key={card.label} {...card} />
          ))}
        </div>
      )}

      {!costComplete && !loading && (
        <div className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50/70 px-4 py-3 text-sm text-amber-900">
          <Icon name="Info" size={18} className="mt-0.5 shrink-0" />
          <div>
            <p className="font-semibold">
              Purchase Profit counts only orders with a recorded cost.
            </p>
            <p className="mt-0.5 text-xs leading-5">
              Orders without an actual cost are left out, not treated as zero.
              Record it later from CN Purchase Orders, Actual Cost. Shipping
              profit is not included until a shipping cost is tracked.
            </p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4 xl:grid-cols-3">
        <section className="cb-surface overflow-hidden rounded-2xl border border-mist-100 xl:col-span-2">
          <div className="flex flex-wrap items-center justify-between gap-3 border-b border-mist-100 px-4 py-4 sm:px-5">
            <div>
              <h2 className="font-semibold text-ink-900">Revenue Trend</h2>
              <p className="mt-0.5 text-xs text-ink-600/55">
                Daily billed revenue from CN orders and Shipment shipping fees
              </p>
            </div>
            <div className="inline-flex rounded-lg border border-mist-200 p-1">
              <button
                type="button"
                onClick={() => setView("chart")}
                className={`rounded-md px-3 py-1.5 text-xs font-semibold ${view === "chart" ? "bg-blue-600 text-white" : "text-ink-600"}`}
              >
                Chart View
              </button>
              <button
                type="button"
                onClick={() => setView("table")}
                className={`rounded-md px-3 py-1.5 text-xs font-semibold ${view === "table" ? "bg-blue-600 text-white" : "text-ink-600"}`}
              >
                Table View
              </button>
            </div>
          </div>
          {loading ? (
            <div className="h-64 animate-pulse bg-mist-50" />
          ) : view === "chart" ? (
            <FinancialRevenueChart
              points={chartPoints}
              onSelectPoint={(point) => {
                setRange("date");
                setFrom(point.key);
                setTo("");
              }}
            />
          ) : (
            <div className="max-h-72 overflow-auto">
              <table className="w-full text-left text-sm">
                <thead className="sticky top-0 bg-mist-50 text-xs text-ink-600/65">
                  <tr>
                    <th className="px-4 py-3 font-semibold">Date</th>
                    <th className="px-4 py-3 text-right font-semibold">
                      Revenue
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-mist-100">
                  {chartPoints
                    .filter((p) => p.value > 0)
                    .slice()
                    .reverse()
                    .map((p) => (
                      <tr key={p.key}>
                        <td className="px-4 py-3">{p.key}</td>
                        <td className="px-4 py-3 text-right font-semibold tabular-nums">
                          {finMoney(p.value)}
                        </td>
                      </tr>
                    ))}
                  {chartPoints.every((p) => p.value === 0) && (
                    <tr>
                      <td
                        colSpan={2}
                        className="px-4 py-8 text-center text-ink-600/55"
                      >
                        No revenue recorded for this period.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </section>

        <section className="cb-surface overflow-hidden rounded-2xl border border-mist-100">
          <div className="border-b border-mist-100 px-4 py-4">
            <h2 className="font-semibold text-ink-900">Wallet Activity</h2>
            <p className="mt-0.5 text-xs text-ink-600/55">
              Recorded wallet transactions in the selected period
            </p>
          </div>
          <div className="space-y-4 p-4">
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <span className="grid h-9 w-9 place-items-center rounded-xl bg-emerald-50 text-emerald-600">
                  <Icon name="ArrowDownLeft" size={17} />
                </span>
                <div>
                  <p className="text-sm font-medium text-ink-800">
                    Top-ups / Deposits
                  </p>
                  <p className="text-xs text-ink-600/50">Wallet funding</p>
                </div>
              </div>
              <p className="font-semibold tabular-nums text-emerald-600">
                {finMoney(walletTopups)}
              </p>
            </div>
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <span className="grid h-9 w-9 place-items-center rounded-xl bg-amber-50 text-amber-700">
                  <Icon name="ArrowUpRight" size={17} />
                </span>
                <div>
                  <p className="text-sm font-medium text-ink-800">
                    Withdrawals / Reversals
                  </p>
                  <p className="text-xs text-ink-600/50">Wallet outflow</p>
                </div>
              </div>
              <p className="font-semibold tabular-nums text-amber-700">
                {finMoney(walletWithdrawals)}
              </p>
            </div>
            <div className="border-t border-mist-100 pt-3">
              <p className="text-xs text-ink-600/55">Transactions loaded</p>
              <p className="mt-1 text-lg font-bold text-ink-900">
                {wallet.length.toLocaleString("en-US")}
              </p>
              <p className="mt-1 text-[11px] leading-4 text-ink-600/50">
                Wallet funding is shown separately from customer order revenue
                to avoid double counting.
              </p>
            </div>
          </div>
        </section>
      </div>

      <section className="cb-surface overflow-hidden rounded-2xl border border-mist-100">
        <div className="border-b border-mist-100 px-4 py-4 sm:px-5">
          <h2 className="font-semibold text-ink-900">
            Financial Source Breakdown
          </h2>
          <p className="mt-0.5 text-xs text-ink-600/55">
            Actual rows returned by Supabase for the selected reporting period
          </p>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full min-w-[560px] text-left text-sm">
            <thead className="bg-mist-50 text-xs uppercase tracking-wide text-ink-600/60">
              <tr>
                <th className="px-4 py-3 font-semibold">Source</th>
                <th className="px-4 py-3 text-right font-semibold">
                  Orders / Rows
                </th>
                <th className="px-4 py-3 text-right font-semibold">Revenue</th>
                <th className="px-4 py-3 text-right font-semibold">
                  Collected
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-mist-100">
              <tr>
                <td className="px-4 py-3 font-medium">CN Purchase Orders</td>
                <td className="px-4 py-3 text-right tabular-nums">
                  {cn.length.toLocaleString("en-US")}
                </td>
                <td className="px-4 py-3 text-right tabular-nums">
                  {finMoney(cnRevenue)}
                </td>
                <td className="px-4 py-3 text-right tabular-nums">
                  {finMoney(activeCn.reduce((s, r) => s + finPaid(r), 0))}
                </td>
              </tr>
              <tr>
                <td className="px-4 py-3 font-medium">
                  Shipping Fees (Shipment)
                </td>
                <td className="px-4 py-3 text-right tabular-nums">
                  {shippingRows.length.toLocaleString("en-US")}
                </td>
                <td className="px-4 py-3 text-right tabular-nums">
                  {finMoney(shippingRevenue)}
                </td>
                <td className="px-4 py-3 text-right tabular-nums">
                  {finMoney(
                    shippingRows.reduce(
                      (s, r) => s + Math.max(0, finNum(r.paid_amount) ?? 0),
                      0,
                    ),
                  )}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}

function Dashboard() {
  const { user } = useAuth();
  const { refetch } = usePackageTracking();
  const [refreshing, setRefreshing] = useState(false);
  const showChina = hasPermission(user, "dashboard.china");
  const handleRefresh = async () => {
    if (refreshing) return;
    setRefreshing(true);
    try {
      await refetch();
    } finally {
      setRefreshing(false);
    }
  };
  if (!showChina) {
    return (
      <div className="cb-surface p-8 text-center">
        <Icons.LayoutDashboard
          size={28}
          className="mx-auto text-ink-600/25 mb-3"
        />
        <p className="font-medium text-ink-800">
          No dashboard sections are assigned to your role.
        </p>
        <p className="mt-1 text-sm text-ink-600/50">
          Ask an administrator to enable Dashboard permissions in Role
          Management.
        </p>
      </div>
    );
  }
  return (
    <FinancialDashboard
      showChina={showChina}
      onRefresh={handleRefresh}
      refreshing={refreshing}
    />
  );
}

