    tk,
    customer: "Unknown Customer",
    customerId: "—",
    order: "—",
    supplier: "—",
    weight: "—",
    dimension: "—",
    cbm: "—",
    warehouse: "—",
    shipment: null,
    container: null,
    exception: null,
    timeline: PACKAGE_STAGES.map((label, i) => ({
      label,
      time: null,
      state: i === 0 ? "active" : "pending",
      proceedBy: null,
    })),
