  function Row({ s }) {
    const nav = useNavigate();
    const { tr } = useApp();
    return (
      <Card
        onClick={() => nav(P("/shipments/" + s.tk))}
        className="p-3.5 flex items-center gap-3 cursor-pointer active:bg-slate-50"
      >
        <Icon i={Package} />
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between gap-2">
            <b className="text-[15px] truncate">{s.tk}</b>
            <Badge n={s.step} fee={s.fee} />
          </div>
          <p className="text-[13px] text-slate-500 truncate">
            {s.shop} · {s.desc}
          </p>
          <p className="text-xs text-slate-400">
            {tr("Shipped", "ថ្ងៃផ្ញើ")}: {fmtDate(s.createdAt)}
          </p>
        </div>
        <ChevronRight size={18} className="text-slate-300" />
      </Card>
    );
  }

  // ---------- Home ----------
  function HomePage() {
    const { me, ships, airShips, cnOrders, wallet, unread, tr } = useApp();
    // Company name + logo come from Admin → Settings → Company Profile.
    const brand = useSystemSettings()?.company;
    const brandName = brand?.name || "Cargo Bridge";
    const brandLogo = brand?.logoUrl || brand?.logoDataUrl || "";
    const feat = useCustomerFeatures();
    const nav = useNavigate();
    const [q, setQ] = useState("");
    const owed = ships.filter(
      (s) => s.step === 4 && s.fee?.state === "due" && s.fee.total > 0,
    );
    const owedTotal = owed.reduce((a, s) => a + s.fee.due, 0);
    const cnt = (f) => ships.filter((s) => f(s.step)).length;
    // AIR shipments use their own status flow → map onto the same dashboard cards.
    const airCnt = (f) =>
      airShips.filter((s) =>
        f(airStatusIndex(s.status), canonicalAirStatus(s.status)),
      ).length;
    // CN Purchase Orders map onto the same dashboard cards.
    const cnCnt = (names) =>
      cnOrders.filter(
        (o) =>
          !cnNeedsCustomerWalletPayment(o) &&
          names.includes(cnNormalizeStatus(o.status)),
      ).length;
    const stats = [
      [
        "Total",
        "សរុប",
        ships.length + airShips.length + cnOrders.length,
        "bg-slate-100 text-slate-700",
        Package,
      ],
      [
        "In Transit",
        "កំពុងដឹក",
        cnt((n) => n >= 0 && n <= 1) +
          airCnt((i) => i >= 0 && i <= 3) +
          cnCnt([
            "Order Processing",
            "Purchased",
            "Shipping to China WH",
            "Inbound",
            "Outbound",
          ]),
        "bg-blue-50 text-blue-600",
        Ship,
      ],
      [
        "Arrived",
        "មកដល់",
        cnt((n) => n === 2 || n === 3) +
          cnCnt(["Arrived", "Shipping to Branch"]),
        "bg-green-50 text-green-600",
        Check,
      ],
      [
        "Ready for Pickup",
        "ត្រៀមយក",
        cnt((n) => n === 4) +
          airCnt((i) => i === 4) +
          cnCnt(["Inbound Warehouse"]),
        "bg-orange-50 text-orange-500",
        Warehouse,
      ],
      [
        "Completed",
        "បញ្ចប់",
        cnt((n) => n === 5) +
          airCnt((i) => i === 5) +
          cnCnt(["Complete Order"]),
        "bg-violet-50 text-violet-600",
        ShieldCheck,
      ],
    ];
    // One merged, newest-first feed of sea/land + AIR shipments.
    const ts = (v) => {
      const t = v ? new Date(v).getTime() : 0;
      return Number.isFinite(t) ? t : 0;
    };
    const feed = [
      ...(feat("tab_shipments") ? ships : []).map((s) => ({
        kind: "sea",
        key: "s-" + s.tk,
        t: ts(s.createdAt),
        s,
      })),
      ...(feat("tab_air") ? airShips : []).map((s) => ({
        kind: "air",
        key: "a-" + (s.id || s.order_id),
        t: ts(s.updated_at || s.created_at),
        s,
      })),
      ...(feat("tab_cn_orders") ? cnOrders : []).map((s) => ({
        kind: "cn",
        key: "c-" + s.id,
        t: ts(s.updated_at || s.created_at),
        s,
      })),
    ].sort((a, b) => b.t - a.t);
    const needle = q.trim().toLowerCase();
    const hit =
      needle &&
      feed.filter(({ kind, s }) =>
        kind === "sea"
          ? String(s.tk || "")
              .toLowerCase()
              .includes(needle)
          : [s.order_id, s.tk, s.shop_name, s.product_name].some((v) =>
              String(v || "")
                .toLowerCase()
                .includes(needle),
            ),
      );
    const renderItem = ({ kind, key, s }) =>
      kind === "sea" ? (
        <Row key={key} s={s} />
      ) : kind === "cn" ? (
        <CnRow key={key} s={s} />
      ) : (
        <AirRow key={key} s={s} />
      );
    return (
      <>
        <header className="bg-blue-600 text-white px-5 pt-6 pb-16 rounded-b-3xl">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-xl font-bold">
                {tr(`Hello ${me.name} `, `សួស្តី ${me.name} `)}
              </h1>
              <p className="text-blue-100 text-sm flex items-center gap-1.5">
                {brandLogo ? (
                  <img
                    src={brandLogo}
                    alt={`${brandName} logo`}
                    className="w-5 h-5 rounded object-cover bg-white/20"
                  />
                ) : null}
                {tr(
                  `Welcome to ${brandName}`,
                  `សូមស្វាគមន៍មកកាន់ ${brandName}`,
                )}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <LangBtn />
              {feat("notifications") && (
                <button
                  type="button"
                  aria-label={tr("Notifications", "ការជូនដំណឹង")}
                  onClick={() => nav(P("/notifications"))}
                  className="relative w-10 h-10 grid place-items-center rounded-full bg-white/15"
                >
                  <Bell size={20} />
                  {unread > 0 && (
                    <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 rounded-full bg-red-500 text-white text-[10px] font-bold grid place-items-center">
                      {unread > 9 ? "9+" : unread}
                    </span>
                  )}
                </button>
              )}
            </div>
          </div>
          {feat("home_search") && (
            <div className="mt-4 flex items-center gap-2 h-12 bg-white rounded-xl px-3.5 text-slate-900">
              <Search size={18} className="text-slate-400" />
              <input
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder={tr("Search tracking number", "ស្វែងរកលេខតាមដាន")}
                className="flex-1 outline-none text-[15px]"
              />
            </div>
          )}
        </header>
        <div className="px-4 -mt-9 space-y-5">
          {q ? (
            <div className="space-y-2.5 pt-10">
              {hit.length ? (
                hit.map(renderItem)
              ) : (
                <p className="text-center text-sm text-slate-400 py-6">
                  {tr(
                    "No matching tracking number found in your account.",
                    "រកមិនឃើញលេខតាមដានដែលត្រូវគ្នាក្នុងគណនីរបស់អ្នកទេ។",
                  )}
                </p>
              )}
            </div>
          ) : (
            <>
              {feat("home_stats") && (
                <div className="grid grid-cols-2 gap-3">
                  {stats.map(([l, k, n, c, I], i) => (
                    <Card
                      key={l}
                      className={`p-3.5 flex items-center gap-3 ${i === 0 ? "col-span-2" : ""}`}
                    >
                      <Icon i={I} c={c} />
                      <div>
                        <p className="text-xs text-slate-500">{tr(l, k)}</p>
                        <p className="text-2xl font-bold leading-tight">{n}</p>
                      </div>
                    </Card>
                  ))}
                </div>
              )}
              {feat("wallet") && (
                <Card
                  onClick={() => nav(P("/wallet"))}
                  className="p-4 flex items-center gap-3 cursor-pointer"
                >
                  <Icon i={Wallet} c="bg-emerald-50 text-emerald-600" />
                  <div className="flex-1">
                    <p className="text-xs text-slate-500">
                      {tr("My Wallet", "កាបូបរបស់ខ្ញុំ")}
                    </p>
                    <b
                      className={`text-xl ${wallet.balance < 0 ? "text-red-600" : ""}`}
                    >
                      {moneyS(wallet.balance)}
                    </b>
                  </div>
                  <ChevronRight size={18} className="text-slate-300" />
                </Card>
              )}
              {feat("home_pay_alert") &&
                feat("tab_shipments") &&
                feat("pay_shipping") &&
                owed.length > 0 && (
                  <Card
                    onClick={() => nav(P("/shipments"))}
                    className="p-4 flex items-center gap-3 cursor-pointer border border-red-100 bg-red-50/60"
                  >
                    <Icon i={Info} c="bg-red-100 text-red-600" />
                    <div className="flex-1">
                      <b className="text-[15px] text-red-700">
                        {tr(
                          `${owed.length} shipment${owed.length > 1 ? "s" : ""} waiting for payment`,
                          `${owed.length} ការដឹកជញ្ជូនកំពុងរង់ចាំការបង់ប្រាក់`,
                        )}
                      </b>
                      <p className="text-xs text-slate-600">
                        {tr(
                          `Total due ${money(owedTotal)} · tap to pay`,
                          `សរុបត្រូវបង់ ${money(owedTotal)} · ចុចដើម្បីបង់`,
                        )}
                      </p>
                    </div>
                    <ChevronRight size={18} className="text-slate-300" />
                  </Card>
                )}
              {feat("warehouse") && (
                <Card
                  onClick={() => nav(P("/warehouse"))}
                  className="p-4 flex items-center gap-3 cursor-pointer bg-gradient-to-r from-blue-50 to-white"
                >
                  <Icon i={Warehouse} />
                  <div className="flex-1">
                    <b className="text-[15px]">
                      {tr("My China Warehouse", "ឃ្លាំងចិនរបស់ខ្ញុំ")}
                    </b>
                    <p className="text-xs text-slate-500">
                      {tr(
                        "Copy your China warehouse address and send it to your seller",
                        "ចម្លងអាសយដ្ឋានឃ្លាំងចិន ផ្ញើទៅអ្នកលក់",
                      )}
                    </p>
                  </div>
                  <ChevronRight size={18} className="text-slate-300" />
                </Card>
              )}
              {feat("home_recent") && (
                <section>
                  <div className="flex justify-between items-center mb-2.5">
                    <h2 className="font-bold">
                      {tr("Recent Shipments", "ការដឹកជញ្ជូនថ្មីៗ")}
                    </h2>
                    {feat("tab_shipments") && (
                      <button
                        onClick={() => nav(P("/shipments"))}
                        className="text-sm text-blue-600 font-medium"
                      >
                        {tr("View all", "មើលទាំងអស់")}
                      </button>
                    )}
                  </div>
                  <div className="space-y-2.5">
                    {feed.slice(0, 5).map(renderItem)}
                  </div>
                  {!feed.length && (
                    <p className="text-center text-sm text-slate-400 py-6">
                      {tr("No shipments yet", "មិនទាន់មានការដឹកជញ្ជូនទេ")}
                    </p>
                  )}
                </section>
              )}
            </>
          )}
        </div>
      </>
    );
  }

  // ---------- Shipments list ----------
  function Shipments() {
    const { ships, airShips, tr } = useApp();
    const [t, setT] = useState("All");
    // Customer shipment filters use the same customer-facing status names as
    // CN Order Table / TK tracking. The underlying numeric TK step stays intact.
    const tabs = {
      All: () => true,
      "Inbound Origin": (n) => n === 0,
      "Outbound Origin": (n) => n === 1,
      "Arrive Destination": (n) => n === 2,
      Delivery: (n) => n === 3,
      "To Pay": (n, s) => n === 3 && s.fee?.state === "due" && s.fee.total > 0,
      Completed: (n) => n === 4,
    };
    const list = ships.filter((s) => tabs[t](s.step, s));
    return (
      <>
        <Top title={tr("My Shipments", "ការដឹកជញ្ជូនរបស់ខ្ញុំ")} />
        <div className="px-4 pt-4 space-y-3">
          <div className="flex gap-2 overflow-x-auto pb-1">
            {Object.keys(tabs).map((k) => (
              <button
                key={k}
                onClick={() => setT(k)}
                className={`px-4 h-9 rounded-full text-[13px] font-semibold whitespace-nowrap ${t === k ? "bg-blue-600 text-white" : "bg-white text-slate-600"}`}
              >
                {tr(...TAB_TX[k])}
              </button>
            ))}
          </div>
          {list.map((s) => (
            <Row key={s.tk} s={s} />
          ))}
          {!list.length && (
            <p className="text-center text-sm text-slate-400 py-10">
              {tr(
                "No shipments in this status.",
                "គ្មានការដឹកជញ្ជូនក្នុងស្ថានភាពនេះទេ។",
              )}
            </p>
          )}
        </div>
      </>
    );
  }

  function CustomerAirSkeleton({ detail = false }) {
    return (
      <div
        className="px-4 pt-4 space-y-4 animate-pulse"
        aria-busy="true"
        aria-label="Loading AIR shipment"
      >
        <div className="rounded-2xl bg-white border border-slate-100 p-4 flex items-center gap-3 shadow-sm">
          <Skeleton className="w-11 h-11 rounded-xl" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-4 w-36" />
            <Skeleton className="h-3 w-48" />
          </div>
          <Skeleton className="h-7 w-24 rounded-full" />
        </div>
        {detail ? (
          <div className="rounded-2xl bg-white p-5 space-y-5 shadow-sm">
            <Skeleton className="h-5 w-44" />
            {Array.from({ length: 5 }).map((_, i) => (
              <div key={i} className="flex gap-3">
                <Skeleton className="w-8 h-8 rounded-full shrink-0" />
                <div className="flex-1 space-y-2">
                  <Skeleton className="h-4 w-48" />
                  <Skeleton className="h-3 w-28" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <>
            {Array.from({ length: 3 }).map((_, i) => (
              <div
                key={i}
                className="rounded-2xl bg-white p-4 flex items-center gap-3 shadow-sm"
              >
                <Skeleton className="w-11 h-11 rounded-xl" />
                <div className="flex-1 space-y-2">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-3 w-52" />
                  <Skeleton className="h-3 w-28" />
                </div>
                <Skeleton className="h-7 w-24 rounded-full" />
              </div>
            ))}
          </>
        )}
      </div>
    );
  }

  // ---------- AIR Shipments (customer: separate menu) ----------
