  // ---------- Wallet ----------
  function WalletPage() {
    const { wallet, refreshMoney, tr } = useApp();
    useEffect(() => {
      refreshMoney();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    // Running balance is rebuilt from the CURRENT balance, walking back through
    // only the rows the customer can see — so it always adds up on screen,
    // even when admin-only reversals are hidden.
    const rows = useMemo(() => {
      let run = wallet.balance;
      return wallet.tx.map((t) => {
        const after = Math.round(run * 100) / 100;
        run -= Number(t.amount) || 0;
        return { ...t, _after: after };
      });
    }, [wallet]);
    const label = {
      top_up: tr("Top up", "បញ្ចូលទឹកប្រាក់"),
      shipping_payment: tr("Shipping payment", "ការបង់ថ្លៃដឹក"),
      shipping_payment_cash: tr(
        "Shipping paid (cash)",
        "បានបង់ថ្លៃដឹក (សាច់ប្រាក់)",
      ),
      shipping_payment_wallet: tr("Shipping payment", "ការបង់ថ្លៃដឹក"),
      cn_order_payment: tr("CN order payment", "ការបង់ប្រាក់ CN Order"),
      cn_order_payment_wallet: tr(
        "CN order payment from Wallet",
        "បានបង់ CN Order ពី Wallet",
      ),
      cn_order_refund: tr("CN order refund", "សងប្រាក់ CN Order វិញ"),
      cn_order_payment_cash: tr(
        "CN order paid (cash)",
        "បានបង់ CN Order (សាច់ប្រាក់)",
      ),
    };
    return (
      <>
        <Top title={tr("My Wallet", "កាបូបរបស់ខ្ញុំ")} back />
        <div className="px-4 pt-4 space-y-4">
          <Card className="p-5 bg-gradient-to-br from-blue-600 to-blue-700 text-white">
            <p className="text-sm text-blue-100">
              {tr("Available balance", "សមតុល្យដែលមាន")}
            </p>
            <p className="text-3xl font-extrabold mt-1">
              {moneyS(wallet.balance)}
            </p>
          </Card>
          {wallet.balance < 0 && (
            <p className="rounded-xl bg-red-50 text-red-700 text-xs font-semibold px-3 py-2.5">
              {tr(
                `Your balance is negative. Please top up ${moneyS(Math.abs(wallet.balance))} or more with our staff to cover it before your next payment.`,
                `សមតុល្យរបស់អ្នកអវិជ្ជមាន។ សូមបញ្ចូលទឹកប្រាក់ ${moneyS(Math.abs(wallet.balance))} ឬច្រើនជាងនេះជាមួយបុគ្គលិករបស់យើង មុនការបង់ប្រាក់លើកក្រោយ។`,
              )}
            </p>
          )}
          <h2 className="font-bold">
            {tr("Transaction History", "ប្រវត្តិប្រតិបត្តិការ")}
          </h2>
          <Card className="divide-y divide-slate-100">
            {rows.map((t) => {
              const n = Number(t.amount) || 0;
              return (
                <div key={t.id} className="flex items-center gap-3 px-4 py-3">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold">
                      {label[t.type] || t.type}
                    </p>
                    <p className="text-xs text-slate-400 truncate">
                      {fmtDate(t.created_at)}
                      {t.tk ? ` · ${t.tk}` : ""}
                    </p>
                  </div>
                  <div className="text-right">
                    <p
                      className={`text-sm font-bold ${n > 0 ? "text-emerald-600" : n < 0 ? "text-red-600" : "text-slate-400"}`}
                    >
                      {n > 0 ? "+" : n < 0 ? "−" : ""}
                      {money(Math.abs(n))}
                    </p>
                    <p className="text-[11px] text-slate-400">
                      {tr("Bal", "សមតុល្យ")} {moneyS(t._after)}
                    </p>
                  </div>
                </div>
              );
            })}
            {!wallet.tx.length && (
              <p className="text-center text-sm text-slate-400 py-8">
                {tr("No transactions yet", "មិនទាន់មានប្រតិបត្តិការទេ")}
              </p>
            )}
          </Card>
        </div>
      </>
    );
  }

