// ------------------------------------------------------------
// Global Toast Notifications — shared by TK / Package operations
// ------------------------------------------------------------
function emitCBToast(type, title, text) {
  if (typeof window === "undefined") return;
  window.dispatchEvent(
    new CustomEvent("cb-global-toast", {
      detail: { type, title, text },
    }),
  );
}

// ------------------------------------------------------------
// Global Confirm Dialog — replaces the default browser confirm()
// Usage: if (!(await confirmDialog({ title, message }))) return;
// ------------------------------------------------------------
function confirmDialog(opts = {}) {
  if (typeof window === "undefined") return Promise.resolve(false);
  return new Promise((resolve) => {
    window.dispatchEvent(
      new CustomEvent("cb-global-confirm", { detail: { ...opts, resolve } }),
    );
  });
}

function GlobalConfirmHost() {
  const [req, setReq] = useState(null);
  const reqRef = useRef(null);
  reqRef.current = req;

  useEffect(() => {
    const onOpen = (event) => {
      // If another dialog is somehow open, cancel it first.
      reqRef.current?.resolve?.(false);
      setReq(event.detail);
    };
    window.addEventListener("cb-global-confirm", onOpen);
    return () => window.removeEventListener("cb-global-confirm", onOpen);
  }, []);

  const close = (value) => {
    reqRef.current?.resolve?.(value);
    setReq(null);
  };

  useEffect(() => {
    if (!req) return undefined;
    const onKey = (e) => {
      if (e.key === "Escape") close(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [req]);

  if (!req) return null;
  const danger = req.tone !== "primary";
  if (req.variant === "signout") {
    return (
      <div
        className="fixed inset-0 z-[200] bg-slate-900/45 backdrop-blur-[3px] flex items-center justify-center p-4"
        onClick={() => close(false)}
        role="presentation"
      >
        <div
          role="alertdialog"
          aria-modal="true"
          aria-labelledby="cb-confirm-title"
          onClick={(e) => e.stopPropagation()}
          className="cb-confirm-card cb-fade-in relative w-full max-w-[460px] rounded-2xl bg-white p-6 shadow-[0_30px_70px_-20px_rgba(15,23,42,.45)]"
        >
          <button
            type="button"
            onClick={() => close(false)}
            aria-label="Close"
            className="cb-confirm-x absolute right-4 top-4 grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-colors"
          >
            <Icons.X size={20} />
          </button>
          <div className="flex items-start gap-4 pr-6">
            <div className="cb-confirm-icon-danger grid h-12 w-12 shrink-0 place-items-center rounded-full bg-red-100 text-red-600">
              <Icons.LogOut size={22} />
            </div>
            <div className="min-w-0 pt-0.5">
              <h3
                id="cb-confirm-title"
                className="text-lg font-bold text-slate-900 leading-tight"
              >
                {req.title}
              </h3>
              {req.message && (
                <p className="mt-1.5 text-[15px] text-slate-500">
                  {req.message}
                </p>
              )}
            </div>
          </div>
          <div className="mt-6 flex justify-end gap-3">
            <button
              type="button"
              autoFocus
              onClick={() => close(false)}
              className="cb-confirm-cancel h-11 min-w-[96px] rounded-lg border border-slate-200 bg-white px-5 text-[15px] font-semibold text-slate-800 shadow-sm hover:bg-slate-50 transition-colors"
            >
              {req.cancelText || "Cancel"}
            </button>
            <button
              type="button"
              onClick={() => close(true)}
              className="h-11 min-w-[104px] rounded-lg bg-red-600 px-5 text-[15px] font-bold text-white shadow-[0_8px_18px_-8px_rgba(220,38,38,.8)] hover:bg-red-700 active:scale-[.98] transition"
            >
              {req.confirmText || "Confirm"}
            </button>
          </div>
        </div>
      </div>
    );
  }
  return (
    <div
      className="fixed inset-0 z-[200] bg-slate-950/45 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={() => close(false)}
      role="presentation"
    >
      <div
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="cb-confirm-title"
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-sm rounded-2xl bg-white shadow-2xl overflow-hidden"
      >
        <div className="p-5 flex gap-3.5">
          <div
            className={`w-11 h-11 rounded-xl grid place-items-center shrink-0 ${danger ? "bg-red-50 text-red-600" : "bg-blue-50 text-blue-600"}`}
          >
            {danger ? (
              <Icons.Trash2 size={20} />
            ) : (
              <Icons.AlertTriangle size={20} />
            )}
          </div>
          <div className="min-w-0">
            <h3
              id="cb-confirm-title"
              className="font-bold text-base text-slate-900"
            >
              {req.title || "Are you sure?"}
            </h3>
            {req.message && (
              <p className="text-sm text-slate-500 mt-1 break-words">
                {req.message}
              </p>
            )}
          </div>
        </div>
        <div className="px-5 py-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-2">
          <button
            type="button"
            autoFocus
            onClick={() => close(false)}
            className="h-10 px-4 rounded-xl border border-slate-200 bg-white text-sm font-semibold text-slate-700"
          >
            {req.cancelText || "Cancel"}
          </button>
          <button
            type="button"
            onClick={() => close(true)}
            className={`h-10 px-5 rounded-xl text-white text-sm font-bold ${danger ? "bg-red-600 hover:bg-red-700" : "bg-blue-600 hover:bg-blue-700"}`}
          >
            {req.confirmText || "Delete"}
          </button>
        </div>
      </div>
    </div>
  );
}

function GlobalToastHost() {
  const [toast, setToast] = useState(null);

  useEffect(() => {
    const onToast = (event) => {
      const detail = event?.detail || {};
      setToast({
        type: detail.type || "ok",
        title: detail.title || "Action completed",
        text: detail.text || "",
        id: Date.now(),
      });
    };
    window.addEventListener("cb-global-toast", onToast);
    return () => window.removeEventListener("cb-global-toast", onToast);
  }, []);

  useEffect(() => {
    if (!toast) return undefined;
    const ms =
      toast.type === "err" ? 6500 : toast.type === "warn" ? 5600 : 4200;
    const timer = window.setTimeout(() => setToast(null), ms);
    return () => window.clearTimeout(timer);
  }, [toast]);

  if (!toast) return null;

  const palette =
    toast.type === "err"
      ? {
          border: "border-rose-200",
          icon: "bg-rose-50 text-rose-600",
          title: "text-rose-800",
          bar: "bg-rose-500",
          iconNode: <Icons.XCircle size={21} />,
        }
      : toast.type === "warn"
        ? {
            border: "border-amber-200",
            icon: "bg-amber-50 text-amber-600",
            title: "text-amber-800",
            bar: "bg-amber-500",
            iconNode: <Icons.AlertTriangle size={21} />,
          }
        : {
            border: "border-emerald-200",
            icon: "bg-emerald-50 text-emerald-600",
            title: "text-emerald-800",
            bar: "bg-emerald-500",
            iconNode: <Icons.CheckCircle2 size={21} />,
          };

  return (
    <div
      className="fixed top-5 right-5 z-[999] w-[min(430px,calc(100vw-2rem))]"
      aria-live={toast.type === "err" ? "assertive" : "polite"}
      aria-atomic="true"
    >
      <div
        role={toast.type === "err" ? "alert" : "status"}
        className={`relative overflow-hidden rounded-2xl border bg-white shadow-[0_18px_55px_rgba(15,23,42,0.18)] ${palette.border}`}
        style={{
          animation: "cb-global-toast-in 260ms cubic-bezier(.2,.8,.2,1) both",
        }}
      >
        <div className="flex items-start gap-3 p-4">
          <div
            className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${palette.icon}`}
          >
            {palette.iconNode}
          </div>
          <div className="min-w-0 flex-1 pt-0.5">
            <div className={`text-sm font-bold ${palette.title}`}>
              {toast.title}
            </div>
            {toast.text && (
              <p className="mt-1 break-words text-sm leading-5 text-slate-600">
                {toast.text}
              </p>
            )}
          </div>
          <button
            type="button"
            aria-label="Dismiss notification"
            onClick={() => setToast(null)}
            className="grid h-8 w-8 shrink-0 place-items-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700"
          >
            <Icons.X size={16} />
          </button>
        </div>
        <div className="h-1 w-full bg-slate-100">
          <div
            className={`h-full ${palette.bar}`}
            style={{
              animation: `cb-global-toast-progress ${toast.type === "err" ? "6.5s" : toast.type === "warn" ? "5.6s" : "4.2s"} linear both`,
            }}
          />
        </div>
      </div>
      <style>{`@keyframes cb-global-toast-in { from { opacity: 0; transform: translate3d(18px,-8px,0) scale(.98); } to { opacity: 1; transform: translate3d(0,0,0) scale(1); } } @keyframes cb-global-toast-progress { from { width: 100%; } to { width: 0%; } } @media (prefers-reduced-motion: reduce) { [role="status"], [role="alert"] { animation: none !important; } }`}</style>
    </div>
  );
}

// ============================================================
// AIR SHIPMENT MODULE
// Separate lifecycle from the China / Sea / Land workflow.
// ============================================================
const AIR_ORDER_STATUS_FLOW = [
  "Order Processing",
  "In Transit",
  "Received at Indonesia Warehouse",
  "Departed Indonesia Warehouse",
  "Received at Cambodia Warehouse",
  "Complete Order",
];
const AIR_ORDER_TERMINAL = "Refund Order";
const AIR_ORDER_TERMINAL_STATUSES = new Set([
  "Complete Order",
  AIR_ORDER_TERMINAL,
]);
const AIR_ORDER_LS_KEY = "cargo_bridge_air_orders_v1";

// Backward compatibility for AIR rows created before the status labels were
// standardized. The UI always displays the canonical English labels.
const AIR_STATUS_ALIASES = {
  "Inbound WH Indo": "Received at Indonesia Warehouse",
  "Outbound WH Indo": "Departed Indonesia Warehouse",
  "Inbound WH KH": "Received at Cambodia Warehouse",
};
function canonicalAirStatus(status) {
  return AIR_STATUS_ALIASES[status] || status;
}
function normalizeAirRow(row) {
  return row ? { ...row, status: canonicalAirStatus(row.status) } : row;
}
function airStatusIndex(status) {
  return AIR_ORDER_STATUS_FLOW.indexOf(canonicalAirStatus(status));
}
function airStatusTone(status) {
  status = canonicalAirStatus(status);
  if (status === "Order Processing") return "bg-slate-100 text-slate-700";
  if (status === "In Transit") return "bg-blue-50 text-blue-700";
  if (status === "Received at Indonesia Warehouse")
    return "bg-violet-50 text-violet-700";
  if (status === "Departed Indonesia Warehouse")
    return "bg-amber-50 text-amber-700";
  if (status === "Received at Cambodia Warehouse")
    return "bg-emerald-50 text-emerald-700";
  if (status === "Complete Order") return "bg-emerald-50 text-emerald-700";
  if (status === AIR_ORDER_TERMINAL) return "bg-red-50 text-red-700";
  return "bg-slate-100 text-slate-600";
}
function airStatusCanAdvance(status) {
  const label = canonicalAirStatus(status);
  if (AIR_ORDER_TERMINAL_STATUSES.has(label)) return false;
  const i = airStatusIndex(label);
  return i >= 0 && i < AIR_ORDER_STATUS_FLOW.length - 1;
}
function airNextStatus(status) {
  const label = canonicalAirStatus(status);
  if (AIR_ORDER_TERMINAL_STATUSES.has(label)) return null;
  const i = airStatusIndex(label);
  return i >= 0 ? AIR_ORDER_STATUS_FLOW[i + 1] || null : null;
}
function airOrderLocalRows() {
  return lsRead(AIR_ORDER_LS_KEY, []);
}
function airOrderLocalWrite(rows) {
  lsWrite(AIR_ORDER_LS_KEY, rows);
}
function airOrderCustomerLabel(c) {
  return c ? `${c.customer_code || c.id} · ${c.name || ""}` : "";
}
function AirStatusBadge({ status }) {
  const label = canonicalAirStatus(status);
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold whitespace-nowrap ${airStatusTone(label)}`}
    >
      {label}
    </span>
  );
}
function AirStatusTimeline({
  status,
  history = [],
  refundReason = "",
  // Optional: the customer portal passes these to render one language.
  tr = (en) => en,
  lab = (x) => x,
  fmt = formatDbTimestamp,
}) {
  const normalizedStatus = canonicalAirStatus(status);
  const refundEntry = [...history]
    .reverse()
    .find((x) => canonicalAirStatus(x.status) === AIR_ORDER_TERMINAL);
  const refundNote = (refundEntry?.note || refundReason || "").trim();
  const isRefunded = normalizedStatus === AIR_ORDER_TERMINAL;
  const isComplete = normalizedStatus === "Complete Order";
  const current = isRefunded
    ? -1
    : isComplete
      ? AIR_ORDER_STATUS_FLOW.length
      : airStatusIndex(normalizedStatus);
  return (
    <div
      className="space-y-1"
      role="list"
      aria-label={tr("AIR shipment tracking", "ការតាមដានផ្លូវអាកាស")}
    >
      {AIR_ORDER_STATUS_FLOW.map((label, i) => {
        const done = current > i;
        const active = current === i;
        const h = [...history]
          .reverse()
          .find((x) => canonicalAirStatus(x.status) === label);
        return (
          <div key={label} className="flex gap-3.5" role="listitem">
            <div className="flex flex-col items-center">
              <span
                className={`relative w-8 h-8 rounded-full grid place-items-center shrink-0 transition-all duration-500 ${done ? "bg-emerald-500 text-white" : active ? "bg-blue-600 text-white shadow-[0_0_0_6px_rgba(37,99,235,.10)] animate-pulse" : "bg-slate-100 border border-slate-200 text-slate-300"}`}
              >
                {done ? (
                  <Icons.Check size={15} strokeWidth={3} />
                ) : active ? (
                  <Icons.Plane size={15} strokeWidth={2.5} />
                ) : (
                  <span className="w-2 h-2 rounded-full bg-slate-300" />
                )}
              </span>
              {i < AIR_ORDER_STATUS_FLOW.length - 1 && (
                <span
                  className={`w-0.5 flex-1 min-h-[42px] transition-colors duration-500 ${done ? "bg-emerald-400" : "bg-slate-200"}`}
                />
              )}
            </div>
            <div className="pb-5 pt-0.5 min-w-0">
              <p
                className={`font-semibold text-[15px] leading-6 ${active ? "text-blue-700" : done ? "text-slate-900" : "text-slate-400"}`}
              >
                {lab(label)}
              </p>
              <p className="text-xs text-slate-500 mt-0.5">
                {h?.created_at
                  ? fmt(h.created_at)
                  : done
                    ? tr("Completed", "បានបញ្ចប់")
                    : active
                      ? tr("Current status", "ស្ថានភាពបច្ចុប្បន្ន")
                      : tr("Pending", "កំពុងរង់ចាំ")}
              </p>
            </div>
          </div>
        );
      })}
      {normalizedStatus === AIR_ORDER_TERMINAL && (
        <div className="flex gap-3.5" role="listitem">
          <div className="w-8 h-8 rounded-full bg-red-500 text-white grid place-items-center shrink-0">
            <Icons.RotateCcw size={14} />
          </div>
          <div className="min-w-0">
            <p className="font-semibold text-sm text-red-700">
              {lab("Refund Order")}
            </p>
            <p className="text-xs text-slate-500 mt-0.5">
              {refundEntry?.created_at
                ? fmt(refundEntry.created_at)
                : tr("Refunded", "បានសងប្រាក់វិញ")}
            </p>
            {refundNote && (
              <div className="mt-2 rounded-xl bg-red-50 border border-red-100 px-3 py-2">
                <p className="text-[10px] font-bold uppercase tracking-wide text-red-400">
                  {tr("Refund Reason", "មូលហេតុសងប្រាក់")}
                </p>
                <p className="text-sm text-red-800 mt-0.5 whitespace-pre-wrap break-words">
                  {refundNote}
                </p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================================
// AIR product / package images + product info
// Files live in the private "air-shipment-images" bucket under
// <air_order_id>/<file>.jpg ; rows live in public.air_order_images.
// Customers are read-only (enforced by RLS in supabase/air_order_images.sql).
// ============================================================
const AIR_IMG_BUCKET = "air-shipment-images";
const AIR_IMG_TYPES = ["image/jpeg", "image/png", "image/webp"];
const AIR_IMG_MAX_BYTES = 8 * 1024 * 1024;
const AIR_IMG_MAX_COUNT = 5;

function validateAirImage(file) {
  if (!file) return "No file selected.";
  if (!AIR_IMG_TYPES.includes(file.type))
    return "Only JPG, PNG or WEBP images are allowed.";
  if (file.size > AIR_IMG_MAX_BYTES) return "Image is larger than 8 MB.";
  return "";
}

// Signed URLs are reused for 50 min (they last 60). The SAME url lets the
// browser serve the picture from its own cache instead of downloading it
// again; the cache survives page reloads for this tab (sessionStorage).
const AIR_CACHE_TTL = 23 * 60 * 60 * 1000;
const AIR_SIGN_SECONDS = 24 * 60 * 60;
function airCacheLoad(key) {
  try {
    return new Map(JSON.parse(localStorage.getItem(key) || "[]"));
  } catch {
    return new Map();
  }
}
function airCacheSave(key, map) {
  try {
    localStorage.setItem(key, JSON.stringify([...map]));
  } catch {
    /* storage full / blocked — cache is optional */
  }
}
const AIR_URL_CACHE = airCacheLoad("cb_air_urls");
const AIR_IMG_LOADED = new Set(); // urls already painted once this session
const AIR_IMAGES_CACHE = airCacheLoad("cb_air_imgs"); // shipment id -> images
function cachedAirImages(id) {
  const c = id ? AIR_IMAGES_CACHE.get(id) : null;
  return c && Date.now() - c.at < AIR_CACHE_TTL ? c.images : null;
}
// Never leave one customer's picture links on a shared device.
if (typeof window !== "undefined" && supabase) {
  supabase.auth.onAuthStateChange((evt) => {
    if (evt !== "SIGNED_OUT") return;
    ["cb_air_urls", "cb_air_covers", "cb_air_imgs"].forEach((k) => {
      try {
        localStorage.removeItem(k);
      } catch {
        /* ignore */
      }
    });
    AIR_URL_CACHE.clear();
    AIR_COVER_CACHE.clear();
    AIR_IMAGES_CACHE.clear();
  });
}

async function signAirImagePaths(paths) {
  const out = {};
  if (!supabase || !paths.length) return out;
  const now = Date.now();
  const missing = [];
  paths.forEach((p) => {
    const c = AIR_URL_CACHE.get(p);
    if (c && now - c.at < AIR_CACHE_TTL) out[p] = c.url;
    else missing.push(p);
  });
  if (!missing.length) return out;
  try {
    const { data } = await supabase.storage
      .from(AIR_IMG_BUCKET)
      .createSignedUrls(missing, AIR_SIGN_SECONDS);
    (data || []).forEach((r) => {
      if (r.signedUrl && r.path) {
        out[r.path] = r.signedUrl;
        AIR_URL_CACHE.set(r.path, { url: r.signedUrl, at: now });
      }
    });
    airCacheSave("cb_air_urls", AIR_URL_CACHE);
  } catch {
    /* images are optional — never break the page */
  }
  return out;
}

// All images of one shipment (sorted). Never throws.
async function loadAirImages(airOrderId) {
  if (!supabase || !airOrderId || String(airOrderId).startsWith("air-local-"))
    return [];
  try {
    const { data, error } = await supabase
      .from("air_order_images")
      .select("id,air_order_id,storage_path,sort_order,created_at")
      .eq("air_order_id", airOrderId)
      .order("sort_order", { ascending: true })
      .order("created_at", { ascending: true });
    if (error) return [];
    if (!data?.length) {
      AIR_IMAGES_CACHE.delete(airOrderId);
      airCacheSave("cb_air_imgs", AIR_IMAGES_CACHE);
      return [];
    }
    const urls = await signAirImagePaths(data.map((r) => r.storage_path));
    const images = data.map((r) => ({ ...r, url: urls[r.storage_path] || "" }));
    AIR_IMAGES_CACHE.set(airOrderId, { images, at: Date.now() });
    airCacheSave("cb_air_imgs", AIR_IMAGES_CACHE);
    return images;
  } catch {
    return [];
  }
}

// Short-lived cache so thumbnails don't re-flash when the list reloads.
// (Signed URLs last 1h; entries are reused for 50 min.)
const AIR_COVER_CACHE = airCacheLoad("cb_air_covers");
function applyCachedCovers(rows) {
  const now = Date.now();
  return rows.map((r) => {
    const c = AIR_COVER_CACHE.get(r.id);
    if (c && now - c.at < 50 * 60 * 1000)
      return {
        ...r,
        cover_url: c.url,
        image_count: c.count,
        cover_loading: false,
      };
    return { ...r, cover_loading: false };
  });
}

// Customer list: ONE query + ONE signing call for every cover image.
async function attachAirCovers(rows) {
  if (!supabase || !rows?.length) return rows;
  try {
    const { data, error } = await supabase
      .from("air_order_images")
      .select("air_order_id,storage_path,sort_order,created_at")
      .in(
        "air_order_id",
        rows.map((r) => r.id),
      )
      .order("sort_order", { ascending: true })
      .order("created_at", { ascending: true });
    if (error) return rows;
    if (!data?.length) {
      // No images anymore (e.g. staff deleted them): drop any stale cover.
      rows.forEach((r) => AIR_COVER_CACHE.delete(r.id));
      airCacheSave("cb_air_covers", AIR_COVER_CACHE);
      return rows.map((r) => ({ ...r, cover_url: "", image_count: 0 }));
    }
    const cover = {},
      count = {};
    data.forEach((r) => {
      count[r.air_order_id] = (count[r.air_order_id] || 0) + 1;
      if (!cover[r.air_order_id]) cover[r.air_order_id] = r.storage_path;
    });
    const urls = await signAirImagePaths(Object.values(cover));
    const updated = rows.map((r) => {
      const url = urls[cover[r.id]] || "";
      if (url)
        AIR_COVER_CACHE.set(r.id, {
          url,
          count: count[r.id] || 0,
          at: Date.now(),
        });
      else AIR_COVER_CACHE.delete(r.id);
      return { ...r, cover_url: url, image_count: count[r.id] || 0 };
    });
    airCacheSave("cb_air_covers", AIR_COVER_CACHE);
    return updated;
  } catch {
    return rows;
  }
}

// Staff only (RLS enforces it too). Returns { ok, failed:[messages] }.
async function uploadAirImages(airOrderId, files, user) {
  requirePermission(user, "air_order.edit");
  const { data: existing } = await supabase
    .from("air_order_images")
    .select("sort_order")
    .eq("air_order_id", airOrderId)
    .order("sort_order", { ascending: false })
    .limit(1);
  let order = existing?.length ? Number(existing[0].sort_order) + 1 : 0;
  const by = user?.name || user?.email || "Admin";
  let ok = 0;
  const failed = [];
  for (const file of files) {
    const bad = validateAirImage(file);
    if (bad) {
      failed.push(`${file.name}: ${bad}`);
      continue;
    }
    let path = "";
    try {
      const dataUrl = await compressImage(file, 1280, 0.78);
      const blob = await (await fetch(dataUrl)).blob();
      path = `${airOrderId}/${makeId()}.jpg`;
      const { error: upErr } = await supabase.storage
        .from(AIR_IMG_BUCKET)
        .upload(path, blob, { contentType: "image/jpeg" });
      if (upErr) throw upErr;
      const { error } = await supabase.from("air_order_images").insert({
        air_order_id: airOrderId,
        storage_path: path,
        sort_order: order++,
        created_by: by,
      });
      if (error) {
        await supabase.storage.from(AIR_IMG_BUCKET).remove([path]);
        throw error;
      }
      ok++;
    } catch (err) {
      failed.push(`${file.name}: ${err.message || "upload failed"}`);
    }
  }
  return { ok, failed };
}

async function deleteAirImage(img, user) {
  requirePermission(user, "air_order.edit");
  const { error } = await supabase
    .from("air_order_images")
    .delete()
    .eq("id", img.id);
  if (error) throw error;
  // The row is gone; a failed file clean-up is harmless (best effort).
  await supabase.storage
    .from(AIR_IMG_BUCKET)
    .remove([img.storage_path])
    .catch(() => {});
}

// Make `img` the primary (first) image.
async function makeAirImagePrimary(images, img, user) {
  requirePermission(user, "air_order.edit");
  const ordered = [img, ...images.filter((x) => x.id !== img.id)];
  for (let i = 0; i < ordered.length; i++) {
    if (ordered[i].sort_order === i) continue;
    const { error } = await supabase
      .from("air_order_images")
      .update({ sort_order: i, updated_at: new Date().toISOString() })
      .eq("id", ordered[i].id);
    if (error) throw error;
  }
}

// Image with skeleton while loading and a graceful fallback (no broken icon).
function AirImg({
  src,
  alt = "",
  className = "",
  onClick,
  fallbackSize = 22,
  FallbackIcon = null,
}) {
  const initial = (u) =>
    !u ? "empty" : AIR_IMG_LOADED.has(u) ? "ok" : "loading";
  const [state, setState] = useState(initial(src));
  useEffect(() => {
    setState(initial(src));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [src]);
  const showFallback = state === "empty" || state === "error";
  return (
    <div
      onClick={showFallback ? undefined : onClick}
      className={`relative overflow-hidden bg-slate-100 shrink-0 ${onClick && !showFallback ? "cursor-pointer" : ""} ${className}`}
    >
      {state === "loading" && (
        <div className="absolute inset-0 animate-pulse bg-slate-200/70" />
      )}
      {showFallback ? (
        <div className="absolute inset-0 grid place-items-center text-blue-400 bg-blue-50">
          {FallbackIcon ? (
            <FallbackIcon size={fallbackSize} />
          ) : (
            <Icons.Plane size={fallbackSize} />
          )}
        </div>
      ) : (
        <img
          src={src}
          alt={alt}
          loading="lazy"
          draggable={false}
          onLoad={() => {
            AIR_IMG_LOADED.add(src);
            setState("ok");
          }}
          onError={() => setState("error")}
          className={`w-full h-full object-cover transition-opacity duration-200 ${state === "ok" ? "opacity-100" : "opacity-0"}`}
        />
      )}
    </div>
  );
}

// Centered, view-only gallery popup (smooth open, zoom / rotate toolbar).
function AirImageViewer({ images, start = 0, onClose }) {
  const [i, setI] = useState(Math.min(start, Math.max(images.length - 1, 0)));
  const [failed, setFailed] = useState(false);
  const [shown, setShown] = useState(false); // drives the open animation
  const [scale, setScale] = useState(1);
  const [rot, setRot] = useState(0);
  const touchX = useRef(null);
  const n = images.length;
  const resetView = () => {
    setScale(1);
    setRot(0);
  };
  const go = (d) => {
    setFailed(false);
    resetView();
    setI((v) => (v + d + n) % n);
  };
  const zoom = (d) =>
    setScale((v) => Math.min(4, Math.max(0.5, +(v + d).toFixed(2))));
  useEffect(() => {
    const t = requestAnimationFrame(() => setShown(true));
    return () => cancelAnimationFrame(t);
  }, []);
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") onClose();
      if (n > 1 && e.key === "ArrowLeft") go(-1);
      if (n > 1 && e.key === "ArrowRight") go(1);
      if (e.key === "+" || e.key === "=") zoom(0.25);
      if (e.key === "-") zoom(-0.25);
    };
    window.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [n]);
  if (!n) return null;
  const circle =
    "absolute w-10 h-10 rounded-full bg-slate-900/50 hover:bg-slate-900/70 text-white grid place-items-center transition-colors";
  const tool =
    "w-9 h-9 rounded-full text-white grid place-items-center hover:bg-white/15 transition-colors";
  return createPortal(
    <div
      className={`fixed inset-0 z-[80] flex items-center justify-center p-4 sm:p-10 bg-slate-950/55 backdrop-blur-sm transition-opacity duration-200 ${
        shown ? "opacity-100" : "opacity-0"
      }`}
      onClick={onClose}
      onTouchStart={(e) => (touchX.current = e.touches[0].clientX)}
      onTouchEnd={(e) => {
        if (touchX.current == null || n < 2 || scale !== 1) return;
        const dx = e.changedTouches[0].clientX - touchX.current;
        touchX.current = null;
        if (Math.abs(dx) > 50) go(dx < 0 ? 1 : -1);
      }}
    >
      <button
        type="button"
        aria-label="Close"
        onClick={onClose}
        className={`${circle} right-4`}
        style={{ top: "calc(env(safe-area-inset-top, 0px) + 16px)" }}
      >
        <Icons.X size={20} />
      </button>
      {/* Centered stage — image stays inside, never edge-to-edge */}
      <div
        onClick={(e) => e.stopPropagation()}
        onWheel={(e) => zoom(e.deltaY < 0 ? 0.15 : -0.15)}
        className={`relative flex items-center justify-center overflow-hidden rounded-2xl bg-slate-900/40 shadow-2xl ring-1 ring-white/10 transition-all duration-200 ease-out ${
          shown ? "scale-100 opacity-100" : "scale-95 opacity-0"
        }`}
        style={{ width: "min(92vw, 860px)", height: "min(74vh, 680px)" }}
      >
        {failed || !images[i].url ? (
          <div className="text-center text-white/70 text-sm">
            <Icons.ImageOff className="mx-auto mb-2" size={32} />
            Image unavailable
          </div>
        ) : (
          <img
            src={images[i].url}
            alt=""
            onError={() => setFailed(true)}
            className="max-w-full max-h-full object-contain select-none transition-transform duration-200 ease-out"
            style={{ transform: `rotate(${rot}deg) scale(${scale})` }}
            draggable={false}
          />
        )}
      </div>
      {n > 1 && (
        <>
          <button
            type="button"
            aria-label="Previous"
            onClick={(e) => {
              e.stopPropagation();
              go(-1);
            }}
            className={`${circle} left-3 sm:left-6`}
          >
            <Icons.ChevronLeft size={22} />
          </button>
          <button
            type="button"
            aria-label="Next"
            onClick={(e) => {
              e.stopPropagation();
              go(1);
            }}
            className={`${circle} right-3 sm:right-6`}
          >
            <Icons.ChevronRight size={22} />
          </button>
        </>
      )}
      {/* Toolbar: zoom out / zoom in / fit / rotate left / rotate right */}
      <div
        onClick={(e) => e.stopPropagation()}
        className="absolute left-1/2 -translate-x-1/2 flex items-center gap-1 px-3 py-1.5 rounded-full bg-slate-900/60 backdrop-blur"
        style={{ bottom: "calc(env(safe-area-inset-bottom, 0px) + 16px)" }}
      >
        <button
          type="button"
          aria-label="Zoom out"
          className={tool}
          onClick={() => zoom(-0.25)}
        >
          <Icons.ZoomOut size={18} />
        </button>
        <button
          type="button"
          aria-label="Zoom in"
          className={tool}
          onClick={() => zoom(0.25)}
        >
          <Icons.ZoomIn size={18} />
        </button>
        <button
          type="button"
          aria-label="Fit"
          className={tool}
          onClick={resetView}
        >
          <Icons.Maximize size={18} />
        </button>
        <button
          type="button"
          aria-label="Rotate left"
          className={tool}
          onClick={() => setRot((r) => r - 90)}
        >
          <Icons.RotateCcw size={18} />
        </button>
        <button
          type="button"
          aria-label="Rotate right"
          className={tool}
          onClick={() => setRot((r) => r + 90)}
        >
          <Icons.RotateCw size={18} />
        </button>
        {n > 1 && (
          <span className="ml-1 pl-3 border-l border-white/20 text-white text-xs font-semibold">
            {i + 1} / {n}
          </span>
        )}
      </div>
    </div>,
    document.body,
  );
}

