// ------------------------------------------------------------
// Record payment (supports partial payments)
// ------------------------------------------------------------
const cnPayErr = (e) =>
  /function .* does not exist|schema cache|pay_cn_order/i.test(e?.message || "")
    ? "Run supabase_cn_wallet_payment.sql in Supabase first."
    : e?.message || "Unable to record payment.";

function CnPaymentModal({ open, row, onClose, onSaved }) {
  const { user } = useAuth();
  const [amount, setAmount] = useState("");
  // "wallet" = deduct from the customer's app wallet
  // "manual" = Mark as Paid (money received outside the app, wallet untouched)
  const [payWith, setPayWith] = useState("wallet");
  const [method, setMethod] = useState(CN_PAYMENT_METHODS[0]);
  const [ref, setRef] = useState("");
  const [cust, setCust] = useState(null); // { id, name, customer_code, balance }
  const [topUpOpen, setTopUpOpen] = useState(false);
  const [tick, setTick] = useState(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const remaining = row
    ? Math.max(
        0,
        Number(row.total_due_usd || 0) - Number(row.amount_paid_usd || 0),
      )
    : 0;
  useEffect(() => {
    if (open && row) {
      setAmount(remaining ? remaining.toFixed(2) : "");
      setPayWith("wallet");
      setMethod(CN_PAYMENT_METHODS[0]);
      setRef("");
      setBusy(false);
      setError("");
      setTopUpOpen(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, row]);

  // live customer wallet balance (re-read after a top up)
  useEffect(() => {
    if (!open || !supabase || !row?.customer_id) return;
    let alive = true;
    supabase
      .from("customers")
      .select("id, name, customer_code, balance")
      .eq("id", row.customer_id)
      .maybeSingle()
      .then(({ data }) => alive && setCust(data || null));
    return () => {
      alive = false;
    };
  }, [open, row?.customer_id, tick]);

  if (!open || !row) return null;

  const amtNum = Number(amount);
  const bal = cust ? Number(cust.balance) || 0 : null;
  const walletShort =
    payWith === "wallet" &&
    bal !== null &&
    Number.isFinite(amtNum) &&
    amtNum > 0 &&
    bal + 0.005 < amtNum;
  const useWallet = payWith === "wallet";

  async function submit(e) {
    e.preventDefault();
    const amt = amtNum;
    if (!Number.isFinite(amt) || amt <= 0)
      return setError("Amount must be above 0.");
    if (amt > remaining + 0.005)
      return setError(`Amount is more than the remaining ${money(remaining)}.`);
    if (useWallet && bal === null)
      return setError("Customer wallet could not be loaded.");
    if (walletShort)
      return setError(
        `Wallet balance is ${moneyS(bal)} — top up the customer first, or choose "Mark as Paid".`,
      );
    setBusy(true);
    setError("");
    try {
      const by = cnBy(user);
      // One atomic RPC: locks the order + customer, deducts the wallet (or just
      // marks paid), writes wallet_transactions and cn_order_history.
      const { data, error } = await supabase.rpc("pay_cn_order", {
        p_order_id: String(row.id),
        p_amount: Math.round(amt * 100) / 100,
        p_use_wallet: useWallet,
        p_method: useWallet ? "Wallet" : method,
        p_ref: useWallet ? null : cnNz(ref),
        p_by: by,
        // guards against two cashiers recording at the same moment
        p_expected_paid: Number(row.amount_paid_usd || 0),
      });
      if (error) throw new Error(cnPayErr(error));
      const pstatus = data?.payment_status || "Paid";
      emitCBToast(
        "ok",
        useWallet ? "Paid from wallet" : "Marked as paid",
        `${row.order_id} · ${pstatus}`,
      );
      onSaved(data);
      onClose();
    } catch (err) {
      setError(err.message || "Unable to record payment.");
    } finally {
      setBusy(false);
    }
  }

  const choiceCls = (on) =>
    `flex-1 rounded-xl border px-3 py-2.5 text-left text-sm transition ${
      on
        ? "border-emerald-500 bg-emerald-50 ring-2 ring-emerald-500/20"
        : "border-slate-200 hover:bg-slate-50"
    }`;

  return (
    <>
      <CnModalShell
        title="Record Payment"
        subtitle={row.order_id}
        onClose={onClose}
        onSubmit={submit}
        error={error}
        busy={busy}
        submitLabel={useWallet ? "Pay from Wallet" : "Mark as Paid"}
        busyLabel="Saving…"
        submitCls="bg-emerald-600"
        submitDisabled={walletShort || (useWallet && bal === null)}
      >
        <div className="rounded-xl bg-slate-50 border border-slate-200 px-3.5 py-3 text-sm space-y-1">
          <div className="flex justify-between text-slate-600">
            <span>Total due</span>
            <b>{money(row.total_due_usd)}</b>
          </div>
          <div className="flex justify-between text-slate-600">
            <span>Already paid</span>
            <b>{money(row.amount_paid_usd)}</b>
          </div>
          <div className="flex justify-between text-slate-900 pt-1 border-t border-slate-200">
            <span className="font-bold">Remaining</span>
            <b>{money(remaining)}</b>
          </div>
        </div>
        <div>
          <label className={LABEL_CLS}>Amount (USD)</label>
          <input
            autoFocus
            type="number"
            min="0"
            step="0.01"
            className={INPUT_CLS}
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        </div>

        <div>
          <label className={LABEL_CLS}>Pay with</label>
          <div className="flex gap-2">
            <button
              type="button"
              className={choiceCls(useWallet)}
              onClick={() => setPayWith("wallet")}
            >
              <b className="block">Customer Wallet</b>
              <span className="text-xs text-slate-500">
                Deduct from the app wallet
              </span>
            </button>
            <button
              type="button"
              className={choiceCls(!useWallet)}
              onClick={() => setPayWith("manual")}
            >
              <b className="block">Mark as Paid</b>
              <span className="text-xs text-slate-500">
                Cash / transfer, no deduction
              </span>
            </button>
          </div>
        </div>

        {useWallet ? (
          <div
            className={`rounded-xl border px-3.5 py-3 text-sm ${
              walletShort
                ? "border-red-200 bg-red-50"
                : "border-slate-200 bg-white"
            }`}
          >
            <div className="flex justify-between">
              <span className="text-slate-600">
                Customer wallet{cust?.name ? ` · ${cust.name}` : ""}
              </span>
              <b className={walletShort || bal < 0 ? "text-red-600" : ""}>
                {bal === null ? "…" : moneyS(bal)}
              </b>
            </div>
            {bal !== null && !walletShort && amtNum > 0 && (
              <div className="flex justify-between mt-1 text-slate-500">
                <span>Balance after payment</span>
                <b>{moneyS(Math.round((bal - amtNum) * 100) / 100)}</b>
              </div>
            )}
            {walletShort && (
              <div className="mt-2 space-y-2">
                <p className="text-xs font-semibold text-red-700">
                  Not enough balance — short by {money(amtNum - bal)}. Top up
                  the customer, or choose “Mark as Paid”.
                </p>
                <button
                  type="button"
                  onClick={() => setTopUpOpen(true)}
                  className="h-9 rounded-lg bg-blue-600 px-3 text-xs font-bold text-white hover:bg-blue-700"
                >
                  Top up wallet
                </button>
              </div>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className={LABEL_CLS}>Method</label>
              <select
                className={INPUT_CLS}
                value={method}
                onChange={(e) => setMethod(e.target.value)}
              >
                {CN_PAYMENT_METHODS.map((m) => (
                  <option key={m}>{m}</option>
                ))}
              </select>
            </div>
            <div>
              <label className={LABEL_CLS}>Reference</label>
              <input
                className={INPUT_CLS}
                value={ref}
                onChange={(e) => setRef(e.target.value)}
                placeholder="Txn / receipt no."
              />
            </div>
          </div>
        )}
      </CnModalShell>
      {topUpOpen && cust && (
        <TopUpModal
          customer={cust}
          onClose={() => setTopUpOpen(false)}
          onDone={() => {
            setTopUpOpen(false);
            setTick((t) => t + 1);
          }}
        />
      )}
    </>
  );
}

// ------------------------------------------------------------
// Advance status (manual steps only: → Purchased, → Shipping to China WH)
// ------------------------------------------------------------
function CnStatusUpdateModal({ open, row, parcels = [], onClose, onSaved }) {
  const { user } = useAuth();
  const [supplierNo, setSupplierNo] = useState("");
  const [actualCost, setActualCost] = useState("");
  const [tracks, setTracks] = useState("");
  const [courier, setCourier] = useState("");
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    if (open && row) {
      setSupplierNo(row.supplier_order_no || "");
      setActualCost(
        row.actual_cost_cny != null ? String(row.actual_cost_cny) : "",
      );
      setTracks("");
      setCourier("");
      setNote("");
      setBusy(false);
      setError("");
    }
  }, [open, row]);
  if (!open || !row) return null;

  const next = cnNextStatus(row.status);
  const existing = new Set(parcels.map((p) => cnLinkKey(p.domestic_tracking)));
  const newTracks = [
    ...new Set(
      tracks
        .split(/[\n,;]+/)
        .map((t) => t.trim())
        .filter(Boolean),
    ),
  ].filter((t) => !existing.has(cnLinkKey(t)));
  const blocker = cnAdvanceBlocker({ ...row, supplier_order_no: supplierNo }, [
    ...parcels,
    ...newTracks,
  ]);

  async function submit(e) {
    e.preventDefault();
    if (blocker) return setError(blocker);
    setBusy(true);
    setError("");
    try {
      const by = cnBy(user),
        now = new Date().toISOString();
      const patch = { status: next, updated_at: now, updated_by: by };
      if (next === "Purchased") {
        const ac = actualCost === "" ? null : Number(actualCost);
        if (ac != null && (!Number.isFinite(ac) || ac < 0))
          throw new Error("Actual cost must be 0 or more.");
        patch.supplier_order_no = supplierNo.trim();
        patch.actual_cost_cny = ac;
        patch.actual_cost_method = "total";
        patch.purchase_exchange_rate =
          Number(row.purchase_exchange_rate || row.cny_per_usd) > 0
            ? Number(row.purchase_exchange_rate || row.cny_per_usd)
            : null;
        patch.purchased_by = by;
        patch.purchased_at = now;
      }
      let data = null;
      if (next === "Complete Order") {
        // Complete the CN Order and its linked physical TKs together. In
        // Packages / TK the final stage is named "Completed" (not
        // "Complete Order"), so keep that canonical package status.
        const { data: linkedTks, error: linkedTksError } = await supabase
          .from("packages")
          .select("id,tk,status")
          .eq("cn_order_id", row.id);
        if (linkedTksError) throw linkedTksError;
        if (!linkedTks?.length) {
          throw new Error(
            "No TK is linked to this CN Order. Link its China tracking number to a TK before completing the order.",
          );
        }
        const alreadyCompleted = (linkedTks || []).filter(
          (p) => String(p.status || "").trim() === "Completed",
        );
        const needsCompletion = (linkedTks || []).filter(
          (p) => String(p.status || "").trim() !== "Completed",
        );
        const notReady = needsCompletion.filter(
          (p) => String(p.status || "").trim() !== "Inbound Warehouse",
        );
        if (notReady.length) {
          throw new Error(
            `All linked TKs must reach Inbound Warehouse first. Not ready: ${notReady
              .map((p) => `${p.tk} (${p.status || "No status"})`)
              .join(", ")}`,
          );
        }

        // Record the TKs changed by this action so we can roll them back if
        // the CN Order status cannot be committed afterwards.
        let changedTks = [];
        let orderWasCompletedHere = false;
        try {
          if (needsCompletion.length) {
            const { data: completedTks, error: completeTksError } =
              await supabase
                .from("packages")
                .update({
                  status: "Completed",
                  updated_by: by,
                  updated_at: now,
                })
                .in(
                  "id",
                  needsCompletion.map((p) => p.id),
                )
                .select("id,tk,status");
            if (completeTksError) throw completeTksError;
            if (
              !completedTks ||
              completedTks.length !== needsCompletion.length
            ) {
              throw new Error(
                "Some linked TKs could not be updated. Check TK permissions/RLS and try again.",
              );
            }
            changedTks = completedTks;
          }

          // A database trigger may already have synced the CN Order to
          // Complete Order after its linked TKs changed. Re-read before doing
          // a guarded fallback update to avoid a conflicting second write.
          const { data: latestOrder, error: latestOrderError } = await supabase
            .from("cn_orders")
            .select("*")
            .eq("id", row.id)
            .maybeSingle();
          if (latestOrderError) throw latestOrderError;
          if (!latestOrder)
            throw new Error("CN Order not found. Reload and try again.");

          if (cnNormalizeStatus(latestOrder.status) === "Complete Order") {
            data = latestOrder;
          } else {
            if (cnNormalizeStatus(latestOrder.status) !== "Inbound Warehouse") {
              throw new Error(
                `CN Order status changed to ${latestOrder.status || "unknown"}. Reload and try again.`,
              );
            }
            const { data: updatedOrder, error: completeOrderError } =
              await supabase
                .from("cn_orders")
                .update(patch)
                .eq("id", row.id)
                .eq("status", latestOrder.status)
                .select("*")
                .maybeSingle();
            if (completeOrderError) throw completeOrderError;
            if (!updatedOrder) {
              throw new Error(
                "CN Order was updated by another user. Please reload and check the order status.",
              );
            }
            data = updatedOrder;
            orderWasCompletedHere = true;
          }

          // Shared TK timeline/history must agree with Packages / TK.
          if (changedTks.length) {
            const { error: tkHistoryError } = await supabase
              .from("status_history")
              .insert(
                changedTks.map((p) => ({
                  tk: p.tk,
                  status: "Completed",
                  remark: `Completed with CN Order ${row.order_id}`,
                  created_by: by,
                  created_at: now,
                })),
              );
            if (tkHistoryError) {
              console.error(
                "[CN Complete Order] TK history insert failed",
                tkHistoryError,
              );
            }
          }
        } catch (completeError) {
          // Avoid leaving a CN Order and its TKs at different final statuses
          // if the second half of the operation fails.
          if (changedTks.length) {
            const { error: rollbackTksError } = await supabase
              .from("packages")
              .update({
                status: "Inbound Warehouse",
                updated_by: by,
                updated_at: new Date().toISOString(),
              })
              .in(
                "id",
                changedTks.map((p) => p.id),
              )
              .eq("status", "Completed");
            if (rollbackTksError) {
              console.error(
                "[CN Complete Order] TK rollback failed",
                rollbackTksError,
              );
            }
          }
          if (orderWasCompletedHere) {
            const { error: rollbackOrderError } = await supabase
              .from("cn_orders")
              .update({
                status: "Inbound Warehouse",
                updated_by: by,
                updated_at: new Date().toISOString(),
              })
              .eq("id", row.id)
              .eq("status", "Complete Order");
            if (rollbackOrderError) {
              console.error(
                "[CN Complete Order] order rollback failed",
                rollbackOrderError,
              );
            }
          }
          throw completeError;
        }
      } else {
        const { data: updatedRow, error } = await supabase
          .from("cn_orders")
          .update(patch)
          .eq("id", row.id)
          .eq("status", row.status) // someone else may have moved it already
          .select("*")
          .single();
        if (error)
          throw new Error(
            error.code === "PGRST116"
              ? "This order was just updated by someone else. Reload and try again."
              : error.message,
          );
        data = updatedRow;
      }
      if (next === "Shipping to China WH" && newTracks.length) {
        // inserted AFTER the status change: the DB trigger may then pick up
        // a TK that was already scanned and advance the order further.
        const { error: pe } = await supabase.from("cn_order_parcels").insert(
          newTracks.map((t) => ({
            cn_order_id: row.id,
            domestic_tracking: t,
            courier: cnNz(courier),
            created_by: by,
          })),
        );
        if (pe) {
          // Do not leave the order in "Shipping to China WH" with 0 TKs:
          // put the status back so the move can simply be retried.
          if (next !== row.status) {
            await supabase
              .from("cn_orders")
              .update({
                status: row.status,
                updated_by: by,
                updated_at: new Date().toISOString(),
              })
              .eq("id", row.id)
              .eq("status", next);
          }
          throw new Error(
            /row-level security/i.test(pe.message || "")
              ? "Your role is not allowed to save China tracking numbers (cn_order_parcels). The status was not changed. Ask an admin to run the cn_order_parcels_staff SQL."
              : pe.message,
          );
        }
      }
      await supabase.from("cn_order_history").insert({
        cn_order_id: row.id,
        event: "status",
        status: next,
        created_by: by,
        note:
          cnNz(note) ||
          (next === "Purchased"
            ? `Supplier order ${supplierNo.trim()}`
            : next === "Complete Order"
              ? "Order marked complete by staff."
              : null),
      });
      emitCBToast("ok", "Order updated", `${row.order_id} → ${next}`);
      onSaved(data);
      onClose();
    } catch (err) {
      setError(err.message || "Unable to update order.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <CnModalShell
      title={`Move to ${next || "—"}`}
      subtitle={`${row.order_id} · ${row.status} → ${next || "—"}`}
      onClose={onClose}
      onSubmit={submit}
      error={error}
      busy={busy}
      submitLabel="Confirm"
      busyLabel="Saving…"
      submitDisabled={!next || !!blocker}
    >
      {blocker && !error && (
        <div className="rounded-xl bg-amber-50 text-amber-800 px-3 py-2 text-sm">
          {blocker}
        </div>
      )}
      {next === "Purchased" && (
        <>
          <div>
            <label className={LABEL_CLS}>Supplier Order No. *</label>
            <input
              autoFocus
              className={INPUT_CLS}
              value={supplierNo}
              onChange={(e) => setSupplierNo(e.target.value)}
              placeholder="Order no. on Taobao / 1688 …"
            />
          </div>
          <div>
            <label className={LABEL_CLS}>
              Actual cost paid to supplier (CNY, incl. China shipping)
            </label>
            <input
              type="number"
              min="0"
              step="0.01"
              className={INPUT_CLS}
              value={actualCost}
              onChange={(e) => setActualCost(e.target.value)}
            />
          </div>
        </>
      )}
      {next === "Shipping to China WH" && (
        <>
          <div>
            <label className={LABEL_CLS}>
              China tracking number(s) * — one per line
            </label>
            <textarea
              autoFocus
              className={`${INPUT_CLS} min-h-24 py-2 font-mono`}
              value={tracks}
              onChange={(e) => setTracks(e.target.value)}
              placeholder={"SF1234567890\nYT9876543210"}
            />
            <p className="text-[11px] text-slate-400 mt-1">
              {parcels.length} existing · {newTracks.length} new. The TK scanned
              at Inbound must match this number.
            </p>
          </div>
          <div>
            <label className={LABEL_CLS}>Courier</label>
            <input
              className={INPUT_CLS}
              value={courier}
              onChange={(e) => setCourier(e.target.value)}
              placeholder="SF / ZTO / YTO / JD …"
            />
          </div>
        </>
      )}
      <div>
        <label className={LABEL_CLS}>Note</label>
        <textarea
          className={`${INPUT_CLS} min-h-16 py-2`}
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Optional note"
        />
      </div>
    </CnModalShell>
  );
}

// ------------------------------------------------------------
// Refund / cancel (only BEFORE Outbound Origin)
// ------------------------------------------------------------
// Fix a wrongly typed CN order. Text fields can always be corrected. Money
// fields (qty, prices, rate, fee, shipping) are editable only while the
// order is still Order Processing AND unpaid; after payment they are locked
// because changing them would break what the customer already paid.
function CnEditModal({ open, row, onClose, onSaved }) {
  const { user } = useAuth();
  const [platform, setPlatform] = useState(CN_PLATFORMS[0]);
  const [shop, setShop] = useState("");
  const [note, setNote] = useState("");
  const [items, setItems] = useState([]);
  const [rate, setRate] = useState("");
  const [feePct, setFeePct] = useState("0");
  const [domShip, setDomShip] = useState("");
  const [domShipUsd, setDomShipUsd] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const isDirect = row?.order_type === "direct";
  const pricingMode = row?.pricing_mode === "usd" ? "usd" : "cny";
  const moneyLocked =
    !row ||
    isDirect ||
    Number(row.amount_paid_usd || 0) > 0 ||
    cnNormalizeStatus(row.status) !== "Order Processing";

  useEffect(() => {
    if (!open || !row) return;
    const stored =
      Array.isArray(row.cn_order_items) && row.cn_order_items.length
        ? row.cn_order_items
        : [
            {
              product_name: row.product_name,
              product_url: row.product_url,
              variant: row.variant,
              quantity: row.quantity,
              unit_price_cny: row.unit_price_cny,
              unit_price_usd: row.unit_price_usd,
            },
          ];
    setPlatform(row.platform || CN_PLATFORMS[0]);
    setShop(row.shop_name || "");
    setNote(row.note || "");
    setItems(
      stored.map((x) => ({
        product_name: x.product_name || "",
        product_url: x.product_url || "",
        variant: x.variant || "",
        quantity: String(x.quantity ?? 1),
        unit_price_cny: String(x.unit_price_cny ?? ""),
        unit_price_usd: String(x.unit_price_usd ?? ""),
      })),
    );
    setRate(String(row.cny_per_usd ?? ""));
    setFeePct(String(row.service_fee_pct ?? "0"));
    setDomShip(String(row.domestic_shipping_cny ?? ""));
    setDomShipUsd(String(row.domestic_shipping_usd ?? ""));
    setBusy(false);
    setError("");
  }, [open, row?.id]);
  if (!open || !row) return null;

  const round = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const extrasUsd = Number(row.additional_services_total_usd) || 0;
  const totals = (() => {
    const r = Number(rate) || 0;
    const lines = items.map((x) => ({
      q: Number(x.quantity) || 0,
      cny: Number(x.unit_price_cny) || 0,
      usd: Number(x.unit_price_usd) || 0,
    }));
    const productTotalCny =
      pricingMode === "cny" ? lines.reduce((t, x) => t + x.q * x.cny, 0) : 0;
    const goodsUsd =
      pricingMode === "usd"
        ? lines.reduce((t, x) => t + x.q * x.usd, 0)
        : r > 0
          ? productTotalCny / r
          : 0;
    const shipUsd =
      pricingMode === "usd"
        ? Number(domShipUsd) || 0
        : r > 0
          ? (Number(domShip) || 0) / r
          : 0;
    const feeUsd = goodsUsd * ((Number(feePct) || 0) / 100);
    return {
      productTotalCny: round(productTotalCny),
      serviceFeeUsd: round(feeUsd),
      totalDueUsd: round(goodsUsd + shipUsd + feeUsd + extrasUsd),
      quantity: lines.reduce((t, x) => t + x.q, 0),
    };
  })();

  const setItem = (i, key, value) =>
    setItems((list) =>
      list.map((x, idx) => (idx === i ? { ...x, [key]: value } : x)),
    );

  async function submit(e) {
    e.preventDefault();
    if (!supabase) return setError("Supabase is not connected.");
    if (!items.length) return setError("Keep at least one product item.");
    for (let i = 0; i < items.length; i++) {
      const x = items[i];
      if (!isDirect && !cnNz(x.product_name) && !cnNz(x.product_url))
        return setError(`Enter a product name or link for Item ${i + 1}.`);
      if (!moneyLocked) {
        if (!Number.isInteger(Number(x.quantity)) || Number(x.quantity) <= 0)
          return setError(
            `Quantity for Item ${i + 1} must be a whole number above 0.`,
          );
        const price =
          pricingMode === "usd"
            ? Number(x.unit_price_usd)
            : Number(x.unit_price_cny);
        if (!Number.isFinite(price) || price <= 0)
          return setError(`Unit price for Item ${i + 1} must be above 0.`);
      }
    }
    if (!moneyLocked) {
      if (pricingMode === "cny" && !(Number(rate) > 0))
        return setError("Exchange rate (CNY per 1 USD) is required.");
      const fee = Number(feePct);
      if (!Number.isFinite(fee) || fee < 0 || fee > 100)
        return setError("Service fee % must be between 0 and 100.");
    }
    setBusy(true);
    setError("");
    try {
      const by = cnBy(user);
      const now = new Date().toISOString();
      const rn = Number(rate) || 0;
      const storedItems = items.map((x) => {
        const q = Number(x.quantity) || 1;
        const cny = pricingMode === "cny" ? Number(x.unit_price_cny) || 0 : 0;
        const usd = pricingMode === "usd" ? Number(x.unit_price_usd) || 0 : 0;
        return {
          product_name: cnNz(x.product_name),
          product_url: cnNz(x.product_url),
          variant: cnNz(x.variant),
          quantity: q,
          pricing_mode: pricingMode,
          unit_price_cny: cny,
          unit_price_usd: usd,
          line_total_cny: round(q * cny),
          line_total_usd: round(
            pricingMode === "usd" ? q * usd : rn > 0 ? (q * cny) / rn : 0,
          ),
        };
      });
      const first = storedItems[0] || {};
      const patch = {
        platform,
        shop_name: cnNz(shop),
        note: cnNz(note),
        product_name: first.product_name,
        product_url: first.product_url,
        variant: first.variant,
        cn_order_items: storedItems,
        updated_by: by,
        updated_at: now,
      };
      if (!moneyLocked) {
        Object.assign(patch, {
          quantity: totals.quantity,
          unit_price_cny: pricingMode === "cny" ? first.unit_price_cny : 0,
          unit_price_usd: pricingMode === "usd" ? first.unit_price_usd : 0,
          cny_per_usd: rn,
          product_total_cny: totals.productTotalCny,
          domestic_shipping_cny:
            pricingMode === "cny" ? Number(domShip) || 0 : 0,
          domestic_shipping_usd:
            pricingMode === "usd" ? Number(domShipUsd) || 0 : 0,
          service_fee_pct: Number(feePct) || 0,
          service_fee_usd: totals.serviceFeeUsd,
          total_due_usd: totals.totalDueUsd,
        });
      }
      const { data, error: upErr } = await supabase
        .from("cn_orders")
        .update(patch)
        .eq("id", row.id)
        .select()
        .maybeSingle();
      if (upErr) throw upErr;
      if (!data)
        throw new Error("Order was not updated. Check your permission.");
      // Best-effort audit trail (never blocks the edit).
      const changed =
        !moneyLocked &&
        Math.abs(totals.totalDueUsd - Number(row.total_due_usd || 0)) > 0.004
          ? ` · total ${money(row.total_due_usd)} → ${money(totals.totalDueUsd)}`
          : "";
      await supabase.from("cn_order_history").insert({
        cn_order_id: row.id,
        event: "edit",
        note: `Order details edited${changed}`,
        created_by: by,
      });
      emitCBToast("ok", "Order updated", row.order_id);
      onSaved(data);
      onClose();
    } catch (err) {
      setError(err.message || "Unable to update order.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <CnModalShell
      title="Edit CN Order"
      subtitle={`${row.order_id} · ${
        moneyLocked
          ? "Prices are locked (paid or already purchased). You can correct names, links, shop and note."
          : "Unpaid: you can correct items, prices, rate and fee. The total is recalculated."
      }`}
      maxW="max-w-2xl"
      onClose={onClose}
      onSubmit={submit}
      error={error}
      busy={busy}
      submitLabel="Save Changes"
      busyLabel="Saving…"
    >
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <label className={LABEL_CLS}>Platform</label>
          <select
            className={INPUT_CLS}
            value={platform}
            onChange={(e) => setPlatform(e.target.value)}
          >
            {[...new Set([platform, ...CN_PLATFORMS])].map((x) => (
              <option key={x} value={x}>
                {x}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className={LABEL_CLS}>Shop</label>
          <input
            className={INPUT_CLS}
            value={shop}
            onChange={(e) => setShop(e.target.value)}
          />
        </div>
      </div>

      {items.map((x, i) => (
        <div
          key={i}
          className="rounded-xl border border-slate-200 p-3 space-y-2"
        >
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-slate-500">Item {i + 1}</p>
            {!moneyLocked && items.length > 1 && (
              <button
                type="button"
                onClick={() => setItems((l) => l.filter((_, idx) => idx !== i))}
                className="text-xs font-semibold text-red-600"
              >
                Remove
              </button>
            )}
          </div>
          <input
            className={INPUT_CLS}
            placeholder="Product name"
            value={x.product_name}
            onChange={(e) => setItem(i, "product_name", e.target.value)}
          />
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <input
              className={INPUT_CLS}
              placeholder="Variant"
              value={x.variant}
              onChange={(e) => setItem(i, "variant", e.target.value)}
            />
            <input
              className={INPUT_CLS}
              placeholder="Product link"
              value={x.product_url}
              onChange={(e) => setItem(i, "product_url", e.target.value)}
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <label className="text-xs font-semibold text-slate-500">
              Quantity
              <input
                type="number"
                min="1"
                step="1"
                disabled={moneyLocked}
                className={`${INPUT_CLS} mt-1 disabled:bg-slate-50`}
                value={x.quantity}
                onChange={(e) => setItem(i, "quantity", e.target.value)}
              />
            </label>
            <label className="text-xs font-semibold text-slate-500">
              Unit price ({pricingMode === "usd" ? "USD" : "CNY"})
              <input
                type="number"
                min="0"
                step="0.01"
                disabled={moneyLocked}
                className={`${INPUT_CLS} mt-1 disabled:bg-slate-50`}
                value={
                  pricingMode === "usd" ? x.unit_price_usd : x.unit_price_cny
                }
                onChange={(e) =>
                  setItem(
                    i,
                    pricingMode === "usd" ? "unit_price_usd" : "unit_price_cny",
                    e.target.value,
                  )
                }
              />
            </label>
          </div>
        </div>
      ))}
      {!moneyLocked && (
        <button
          type="button"
          onClick={() =>
            setItems((l) => [
              ...l,
              {
                product_name: "",
                product_url: "",
                variant: "",
                quantity: "1",
                unit_price_cny: "",
                unit_price_usd: "",
              },
            ])
          }
          className="text-sm font-semibold text-signal-blue"
        >
          + Add item
        </button>
      )}

      {!isDirect && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {pricingMode === "cny" && (
            <label className="text-xs font-semibold text-slate-500">
              Rate (CNY per USD)
              <input
                type="number"
                step="0.01"
                disabled={moneyLocked}
                className={`${INPUT_CLS} mt-1 disabled:bg-slate-50`}
                value={rate}
                onChange={(e) => setRate(e.target.value)}
              />
            </label>
          )}
          <label className="text-xs font-semibold text-slate-500">
            China shipping ({pricingMode === "usd" ? "USD" : "CNY"})
            <input
              type="number"
              min="0"
              step="0.01"
              disabled={moneyLocked}
              className={`${INPUT_CLS} mt-1 disabled:bg-slate-50`}
              value={pricingMode === "usd" ? domShipUsd : domShip}
              onChange={(e) =>
                pricingMode === "usd"
                  ? setDomShipUsd(e.target.value)
                  : setDomShip(e.target.value)
              }
            />
          </label>
          <label className="text-xs font-semibold text-slate-500">
            Service fee %
            <input
              type="number"
              min="0"
              max="100"
              step="0.01"
              disabled={moneyLocked}
              className={`${INPUT_CLS} mt-1 disabled:bg-slate-50`}
              value={feePct}
              onChange={(e) => setFeePct(e.target.value)}
            />
          </label>
        </div>
      )}
      {!isDirect && !moneyLocked && (
        <p className="text-sm font-semibold text-slate-700">
          New total due: {money(totals.totalDueUsd)}{" "}
          <span className="font-normal text-slate-400">
            (was {money(row.total_due_usd)})
          </span>
        </p>
      )}
      <div>
        <label className={LABEL_CLS}>Note</label>
        <textarea
          className={`${INPUT_CLS} min-h-16 py-2`}
          value={note}
          onChange={(e) => setNote(e.target.value)}
        />
      </div>
    </CnModalShell>
  );
}

// Cancel an order the customer has not paid for. No money moves, so there is
// no wallet refund; the order just closes with a recorded reason.
function CnCancelModal({ open, row, onClose, onSaved }) {
  const { user } = useAuth();
  const [reason, setReason] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    if (open) {
      setReason("");
      setBusy(false);
      setError("");
    }
  }, [open, row?.id]);
  if (!open || !row) return null;

  async function submit(e) {
    e.preventDefault();
    if (!reason.trim()) return setError("Cancel reason is required.");
    if (Number(row.amount_paid_usd || 0) > 0)
      return setError("This order already has a payment. Use Refund Order.");
    if (!cnCanRefund(row.status))
      return setError(
        "Goods already left China — this order can not be cancelled.",
      );
    setBusy(true);
    setError("");
    try {
      const by = cnBy(user);
      const now = new Date().toISOString();
      const { data, error: upErr } = await supabase
        .from("cn_orders")
        .update({ status: CN_ORDER_TERMINAL, updated_by: by, updated_at: now })
        .eq("id", row.id)
        .eq("status", row.status)
        .select()
        .maybeSingle();
      if (upErr) throw upErr;
      if (!data)
        throw new Error("The order changed meanwhile. Reload and try again.");
      await supabase.from("cn_order_history").insert({
        cn_order_id: row.id,
        event: "status",
        status: CN_ORDER_TERMINAL,
        note: `Cancelled (unpaid): ${reason.trim()}`,
        created_by: by,
      });
      emitCBToast("ok", "Order cancelled", row.order_id);
      onSaved(data);
      onClose();
    } catch (err) {
      setError(err.message || "Unable to cancel order.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <CnModalShell
      title="Cancel CN Order"
      titleCls="text-red-700"
      subtitle={`${row.order_id} · not paid yet, so nothing is refunded.`}
      onClose={onClose}
      onSubmit={submit}
      error={error}
      busy={busy}
      submitLabel="Confirm Cancel"
      busyLabel="Cancelling…"
      submitCls="bg-red-600"
    >
      <textarea
        className={`${INPUT_CLS} min-h-24 py-2`}
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        placeholder="Why is this order cancelled?"
      />
    </CnModalShell>
  );
}

function CnRefundModal({ open, row, onClose, onSaved }) {
  const { user } = useAuth();
  const [amount, setAmount] = useState("");
  const [reason, setReason] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    if (open && row) {
      setAmount(String(Number(row.amount_paid_usd || 0).toFixed(2)));
      setReason("");
      setBusy(false);
      setError("");
    }
  }, [open, row]);
  if (!open || !row) return null;
  const paid = Number(row.amount_paid_usd || 0);
  const bought = cnStatusIndex(row.status) >= cnStatusIndex("Purchased");

  async function submit(e) {
    e.preventDefault();
    const amt = Number(amount);
    if (!reason.trim()) return setError("Refund reason is required.");
    if (!cnCanRefund(row.status))
      return setError(
        "Goods already left China — this is a claim, not a refund.",
      );
    if (!Number.isFinite(amt) || amt < 0 || amt > paid + 0.005)
      return setError(`Refund amount must be between 0 and ${money(paid)}.`);
    setBusy(true);
    setError("");
    try {
      const by = cnBy(user);
      // One atomic RPC: credits the customer's wallet + updates order + history
      // (see supabase_cn_refund.sql)
      const { data, error } = await supabase.rpc("refund_cn_order", {
        p_order_id: String(row.id),
        p_amount: Math.round(amt * 100) / 100,
        p_reason: reason.trim(),
        p_by: by,
      });
      if (error)
        throw new Error(
          /function .* does not exist|schema cache/i.test(error.message || "")
            ? "Run supabase_cn_refund.sql in Supabase first."
            : error.message,
        );
      emitCBToast("ok", "Order refunded", `${row.order_id} · ${money(amt)}`);
      onSaved(data);
      onClose();
    } catch (err) {
      setError(err.message || "Unable to refund order.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <CnModalShell
      title="Refund CN Order"
      titleCls="text-red-700"
      subtitle="Only available before the goods leave China."
      onClose={onClose}
      onSubmit={submit}
      error={error}
      busy={busy}
      submitLabel="Confirm Refund"
      busyLabel="Refunding…"
      submitCls="bg-red-600"
    >
      {bought && (
        <div className="rounded-xl bg-amber-50 text-amber-800 px-3 py-2 text-sm">
          This order was already purchased from the supplier. Refund the
          customer only if the supplier refunded you, or you accept the loss.
        </div>
      )}
      <div>
        <label className={LABEL_CLS}>Refund to customer (USD)</label>
        <input
          type="number"
          min="0"
          step="0.01"
          className={INPUT_CLS}
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <p className="text-[11px] text-slate-400 mt-1">
          Customer paid {money(paid)}. The refund goes back to their wallet.
          Enter less to keep a cancellation fee.
        </p>
      </div>
      <textarea
        className={`${INPUT_CLS} min-h-24 py-2`}
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        placeholder="Why is this order cancelled / refunded?"
      />
    </CnModalShell>
  );
}

// ------------------------------------------------------------
// History
