// ============================================================
// SHIPPING PAYMENT + WALLET (see supabase_wallet_payment.sql)
// Tracking stage stays "Inbound Warehouse"; the DISPLAYED status is
// "Pending Shipping Payment" until the fee is paid, then "Shipping Paid".
// ============================================================
const PAY_STATUS = {
  PENDING: "Pending Shipping Payment",
  PAID: "Shipping Paid",
};
function pkgDisplayStatus(p) {
  const s = p?.status;
  if (s !== "Inbound Warehouse") return s;
  const f = shippingFeeOf(p);
  if (f.state === "due") return PAY_STATUS.PENDING;
  if (f.state === "paid" && f.total > 0) return PAY_STATUS.PAID;
  return s;
}
const walletErr = (e) =>
  /function .* does not exist|wallet_transactions|balance|paid_at|schema cache/i.test(
    e?.message || "",
  )
    ? "Run supabase_wallet_payment.sql in Supabase first."
    : e?.message || "Request failed.";

function WalletModal({ title, onClose, children }) {
  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center bg-slate-900/40 p-4">
      <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
        <div className="mb-4 flex items-center justify-between">
          <h3 className="text-base font-extrabold text-slate-900">{title}</h3>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-700"
          >
            <Icons.X size={18} />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

function TopUpModal({ customer, onClose, onDone }) {
  const [amount, setAmount] = useState("");
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const amt = Number(amount);
  const valid = Number.isFinite(amt) && amt > 0;
  const field =
    "mt-1 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10";
  async function submit() {
    if (!valid || busy) return;
    setBusy(true);
    setErr("");
    const { error } = await supabase.rpc("wallet_top_up", {
      p_customer_id: String(customer.id),
      p_amount: Math.round(amt * 100) / 100,
      p_note: note.trim() || null,
    });
    setBusy(false);
    if (error) return setErr(walletErr(error));
    emitCBToast(
      "ok",
      "Top up successful",
      `${money(amt)} added to ${customer.name}.`,
    );
    onDone();
  }
  return (
    <WalletModal title={`Top up — ${customer.name}`} onClose={onClose}>
      <div className="mb-3 rounded-xl bg-slate-50 px-4 py-3 text-sm text-slate-600">
        Current balance:{" "}
        <b
          className={
            Number(customer.balance) < 0 ? "text-red-600" : "text-slate-900"
          }
        >
          {moneyS(customer.balance || 0)}
        </b>
      </div>
      <label className="text-xs font-bold uppercase tracking-wide text-slate-500">
        Amount (USD)
        <input
          type="number"
          min="0"
          step="0.01"
          autoFocus
          className={field}
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
      </label>
      <label className="mt-3 block text-xs font-bold uppercase tracking-wide text-slate-500">
        Note (optional)
        <input
          className={field}
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="e.g. ABA transfer, cash"
        />
      </label>
      {err && <p className="mt-3 text-xs font-semibold text-red-600">{err}</p>}
      <div className="mt-5 flex justify-end gap-2">
        <button
          type="button"
          onClick={onClose}
          className="h-10 rounded-xl border border-slate-200 px-4 text-sm font-bold text-slate-600 hover:bg-slate-50"
        >
          Cancel
        </button>
        <button
          type="button"
          disabled={!valid || busy}
          onClick={submit}
          className="h-10 rounded-xl bg-blue-600 px-5 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-40"
        >
          {busy ? "Saving…" : "Top up"}
        </button>
      </div>
    </WalletModal>
  );
}

// ------------------------------------------------------------
// Print Invoice (customer shipping-fee invoice, A4)
// ------------------------------------------------------------
function invoiceStamp(d = new Date()) {
  const p = (n) => String(n).padStart(2, "0");
  const h = d.getHours();
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(h % 12 || 12)}:${p(d.getMinutes())} ${h >= 12 ? "PM" : "AM"}`;
}

function invoiceHtml({ company, customer, rows, issuedBy, when }) {
  const e = htmlEsc;
  const logo = company?.logoUrl || company?.logoDataUrl || "";
  const total = rows.reduce((a, r) => a + (Number(r.total) || 0), 0);
  const $ = (n) => `$${(Number(n) || 0).toFixed(2)}`;
  return `<!doctype html><html><head><meta charset="utf-8"><title>Invoice ${e(customer.code)}</title>
<style>
  @page{size:A4;margin:16mm 14mm}
  *{box-sizing:border-box}
  body{font-family:'Inter','Noto Sans Khmer',Arial,sans-serif;font-size:14px;color:#111;margin:0}
  .top{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;margin-bottom:22px}
  .top .logo img{max-height:56px;max-width:190px;object-fit:contain}
  .top .logo b{font-size:20px}
  .top h1{font-size:20px;font-weight:500;margin:0;text-align:center}
  .top .meta{text-align:right;line-height:1.55}
  .cust{line-height:1.6;margin-bottom:12px;font-size:15px}
  table{border-collapse:collapse;width:100%;font-size:13px}
  th,td{border:1px solid #9aa3b5;padding:6px 10px}
  th{background:#f1f3f6;font-weight:500;text-align:center}
  td.c{text-align:center}
  td.tot{text-align:right;font-weight:600}
  td.sum{font-weight:600}
  .sign{display:grid;grid-template-columns:repeat(3,1fr);text-align:center;margin-top:34px;font-weight:600}
  .sign div{padding-bottom:70px}
  .line{border-top:1px solid #d5d9e0;margin-top:20px}
</style></head><body>
<div class="top">
  <div class="logo">${logo ? `<img src="${e(logo)}" alt="">` : `<b>${e(company?.name || "")}</b>`}</div>
  <h1>Invoice</h1>
  <div class="meta"><div><b>Date:</b> ${e(when)}</div><div><b>Issued By:</b> ${e(issuedBy)}</div></div>
</div>
<div class="cust">
  <div><b>UID:</b> ${e(customer.code)}</div>
  <div><b>Name:</b> ${e(customer.name)}</div>
  <div><b>Phone Number:</b> ${e(customer.phone)}</div>
  <div><b>Total Order:</b> ${rows.length}</div>
</div>
<table>
  <tr><th>#</th><th>Customer</th><th>PO</th><th>Tracking Number</th><th>Parcel</th><th>Credit Repayment</th><th>Shipping Fee</th><th>Total</th></tr>
  ${rows
    .map(
      (r, i) =>
        `<tr><td class="c">${i + 1}</td><td>${e(r.customer)}</td><td>${e(r.po)}</td><td>${e(r.tk)}</td><td class="c">${e(r.parcel)}</td><td>${$(r.credit)}</td><td>${$(r.fee)}</td><td>${$(r.total)}</td></tr>`,
    )
    .join("")}
  <tr><td colspan="6" class="tot">Total</td><td class="sum" colspan="2">${$(total)}</td></tr>
</table>
<div class="sign"><div>Customer Signature</div><div>Employee Signature</div><div>Authorized Signature</div></div>
<div class="line"></div>
</body></html>`;
}

// Prints once images (logo) have finished loading.
function printInvoiceHtml(html) {
  const f = document.createElement("iframe");
  f.style.cssText =
    "position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden";
  document.body.appendChild(f);
  f.onload = async () => {
    const d = f.contentDocument;
    await Promise.all(
      Array.from(d.images).map((im) =>
        im.complete
          ? null
          : new Promise((r) => {
              im.onload = im.onerror = r;
            }),
      ),
    );
    f.contentWindow.focus();
    f.contentWindow.print();
    setTimeout(() => f.remove(), 3000);
  };
  f.srcdoc = html;
}

async function printShippingInvoice({ pkg, fee, user, company }) {
  let cust = null;
  if (supabase && pkg.customer_id) {
    const { data } = await supabase
      .from("customers")
      .select("name, customer_code, phone")
      .eq("id", pkg.customer_id)
      .maybeSingle();
    cust = data;
  }
  const customer = {
    code: cust?.customer_code || pkg.customer_code || "—",
    name: cust?.name || pkg.customer_name || "—",
    phone: cust?.phone || "—",
  };
  printInvoiceHtml(
    invoiceHtml({
      company,
      customer,
      rows: [
        {
          customer: customer.name,
          po: pkg.order_no || pkg.order || "—",
          tk: pkg.tk,
          parcel: Math.max(1, Math.floor(Number(pkg.package_count)) || 1),
          credit: 0,
          fee: fee.total,
          total: fee.total,
        },
      ],
      issuedBy: user?.name || user?.email || "—",
      when: invoiceStamp(),
    }),
  );
}

