function DeliverySalesReport({ rows, onClose }) {
  const data = useMemo(() => {
    const map = new Map();
    rows
      .filter((r) => r.status === "Delivered")
      .forEach((r) => {
        const d = new Date(r.delivered_at || r.requested_at);
        if (Number.isNaN(d.getTime())) return;
        const k = deliveryDayKey(d);
        if (!map.has(k))
          map.set(k, { day: k, n: 0, wallet: 0, cod: 0, cash: 0 });
        const x = map.get(k);
        const fee = Number(r.delivery_fee) || 0;
        x.n += 1;
        if (r.payment_type === "cod") x.cod += fee;
        else x.wallet += fee;
        x.cash += Number(r.cash_to_collect) || 0;
      });
    return [...map.values()].sort((a, b) => b.day.localeCompare(a.day));
  }, [rows]);
  const tot = data.reduce(
    (t, x) => ({
      n: t.n + x.n,
      wallet: t.wallet + x.wallet,
      cod: t.cod + x.cod,
      cash: t.cash + x.cash,
    }),
    { n: 0, wallet: 0, cod: 0, cash: 0 },
  );

  function exportCsv() {
    const lines = data.map((x) =>
      [
        x.day,
        x.n,
        x.wallet.toFixed(2),
        x.cod.toFixed(2),
        (x.wallet + x.cod).toFixed(2),
        x.cash.toFixed(2),
      ].join(","),
    );
    const head = "Date,Delivered,Wallet fee,COD fee,Fee earned,Cash collected";
    const blob = new Blob(["\ufeff" + [head, ...lines].join("\n")], {
      type: "text/csv;charset=utf-8",
    });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "sale-performance.csv";
    a.click();
    URL.revokeObjectURL(a.href);
  }

  const th = "font-medium px-4 py-2.5 text-right";
  return (
    <div className={CT_CARD + " overflow-hidden"}>
      <div className="flex items-center justify-between px-5 py-4">
        <h2 className="text-sm font-semibold text-ink-900">Sale performance</h2>
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={exportCsv}
            disabled={!data.length}
            title="Export CSV"
            className="text-ink-600/55 hover:text-ink-900 disabled:opacity-40"
          >
            <Download size={14} />
          </button>
          <button
            type="button"
            onClick={onClose}
            className="text-ink-600/55 hover:text-ink-900"
            title="Close"
          >
            <X size={15} />
          </button>
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-mist-50 text-[11px] uppercase tracking-wide text-ink-600/55">
              <th className="text-left font-medium px-5 py-2.5">Date</th>
              <th className={th}>Delivered</th>
              <th className={th}>Wallet fee</th>
              <th className={th}>COD fee</th>
              <th className={th}>Fee earned</th>
              <th className={th + " !pr-5"}>Cash collected</th>
            </tr>
          </thead>
          <tbody>
            {data.map((x) => (
              <tr
                key={x.day}
                className="border-t border-mist-200 hover:bg-mist-50/70"
              >
                <td className="px-5 py-2.5 text-ink-900">{x.day}</td>
                <td className="px-4 py-2.5 text-right">{x.n}</td>
                <td className="px-4 py-2.5 text-right">{money(x.wallet)}</td>
                <td className="px-4 py-2.5 text-right">{money(x.cod)}</td>
                <td className="px-4 py-2.5 text-right font-medium text-ink-900">
                  {money(x.wallet + x.cod)}
                </td>
                <td className="px-4 py-2.5 pr-5 text-right">{money(x.cash)}</td>
              </tr>
            ))}
            {data.length > 0 && (
              <tr className="border-t border-mist-200 bg-mist-50 font-semibold text-ink-900">
                <td className="px-5 py-2.5">Total</td>
                <td className="px-4 py-2.5 text-right">{tot.n}</td>
                <td className="px-4 py-2.5 text-right">{money(tot.wallet)}</td>
                <td className="px-4 py-2.5 text-right">{money(tot.cod)}</td>
                <td className="px-4 py-2.5 text-right">
                  {money(tot.wallet + tot.cod)}
                </td>
                <td className="px-4 py-2.5 pr-5 text-right">
                  {money(tot.cash)}
                </td>
              </tr>
            )}
            {!data.length && (
              <tr>
                <td
                  colSpan={6}
                  className="text-center text-sm text-ink-600/55 py-8"
                >
                  No delivered orders in this range
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const DELIVERY_SEARCH_FIELDS = [
  {
    key: "all",
    label: "All fields",
    ph: "Search delivery / customer / phone / TK",
  },
  { key: "delivery", label: "Delivery ID", ph: "Search Delivery ID" },
  { key: "customer", label: "Customer", ph: "Search customer name or ID" },
  { key: "phone", label: "Phone Number", ph: "Search phone number" },
  { key: "tk", label: "TK", ph: "Search TK number" },
  { key: "address", label: "Address", ph: "Search address" },
];

function deliveryMatches(r, field, raw) {
  const q = raw.trim().toLowerCase();
  if (!q) return true;
  const has = (v) =>
    String(v ?? "")
      .toLowerCase()
      .includes(q);
  const phoneHit = () => {
    const qd = q.replace(/\D/g, "");
    if (!qd) return false;
    const pd = String(r.receiver_phone ?? "").replace(/\D/g, "");
    return pd.includes(qd) || (qd.startsWith("0") && pd.includes(qd.slice(1)));
  };
  const tkHit = () => (r.items || []).some((i) => has(i.tk));
  switch (field) {
    case "delivery":
      return has(r.delivery_no);
    case "customer":
      return has(r.customer_name) || has(r.customer_code);
    case "phone":
      return phoneHit();
    case "tk":
      return tkHit();
    case "address":
      return has(r.address_text);
    default:
      return (
        has(r.delivery_no) ||
        has(r.customer_name) ||
        has(r.customer_code) ||
        has(r.address_text) ||
        phoneHit() ||
        tkHit()
      );
  }
}

function DeliverySearchBar({ field, setField, value, setValue }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const h = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, [open]);
  const cur =
    DELIVERY_SEARCH_FIELDS.find((f) => f.key === field) ||
    DELIVERY_SEARCH_FIELDS[0];
  return (
    <div
      ref={ref}
      className="relative flex items-stretch rounded-md border border-mist-200 bg-white focus-within:border-signal-blue focus-within:ring-1 focus-within:ring-signal-blue/30 w-full sm:w-[26rem]"
    >
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex items-center gap-1.5 pl-3 pr-2 text-sm font-medium text-ink-900 border-r border-mist-200 whitespace-nowrap hover:bg-mist-50 rounded-l-md"
      >
        {cur.label}
        <Icons.ChevronDown
          size={14}
          className={`text-ink-600/50 transition-transform ${open ? "rotate-180" : ""}`}
        />
      </button>
      <input
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder={cur.ph}
        className="flex-1 min-w-0 px-3 py-2 text-sm bg-transparent outline-none placeholder:text-ink-600/40"
      />
      {value ? (
        <button
          type="button"
          onClick={() => setValue("")}
          title="Clear"
          className="px-2.5 text-ink-600/50 hover:text-ink-900"
        >
          <X size={14} />
        </button>
      ) : (
        <span className="px-2.5 flex items-center text-ink-600/40">
          <Icons.Search size={14} />
        </span>
      )}
      {open && (
        <div className="absolute left-0 top-full mt-1 z-30 w-52 rounded-md border border-mist-200 bg-white shadow-lg py-1">
          {DELIVERY_SEARCH_FIELDS.map((f) => (
            <button
              key={f.key}
              type="button"
              onClick={() => {
                setField(f.key);
                setOpen(false);
              }}
              className={`w-full flex items-center justify-between px-4 py-2 text-sm text-left hover:bg-mist-50 ${f.key === field ? "text-signal-blue font-medium" : "text-ink-900"}`}
            >
              {f.label}
              {f.key === field && <Icons.Check size={14} />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function DeliveryPage() {
  const { user } = useAuth();
  const { packages, upsertPackage, logStatus } = usePackageTracking();
  const { rows, loading, error, reload, create, patch } = useDeliveries();
  const [tab, setTab] = useState("All");
  const [search, setSearch] = useState("");
  const [drawer, setDrawer] = useState(false);
  const [detail, setDetail] = useState(null);
  const [dispatch, setDispatch] = useState(null);
  const [confirm, setConfirm] = useState(null); // {row, kind}
  const [range, setRange] = useState("30d");
  const [courierF, setCourierF] = useState("");
  const [payF, setPayF] = useState("");
  const [report, setReport] = useState(null); // "couriers" | "sales"
  const [searchBy, setSearchBy] = useState("all");
  const [newestFirst, setNewestFirst] = useState(true);

  const canCreate = hasPermission(user, "delivery.create");
  const canEdit = hasPermission(user, "delivery.edit");
  const operator = user?.name || user?.email || "System";

  // AIR orders sitting at the Cambodia Warehouse (waiting to be delivered).
  const [airReadyAll, setAirReadyAll] = useState([]);
  const loadAirReady = React.useCallback(async () => {
    try {
      if (CHINA_ONLY) {
        setAirReadyAll([]);
        return;
      }
      if (!supabase) {
        setAirReadyAll(
          airOrderLocalRows()
            .map(normalizeAirRow)
            .filter((r) => canonicalAirStatus(r.status) === AIR_READY_STATUS),
        );
        return;
      }
      const { data } = await supabase
        .from("air_orders")
        .select("id, order_id")
        .in("status", AIR_READY_RAW)
        .limit(2000);
      setAirReadyAll(data || []);
    } catch {
      /* AIR table optional — never block the Delivery page */
    }
  }, []);
  useEffect(() => {
    loadAirReady();
  }, [loadAirReady, rows]);

  const activeTks = useMemo(() => {
    const s = new Set();
    rows
      .filter((r) => DELIVERY_ACTIVE.includes(r.status))
      .forEach((r) => (r.items || []).forEach((i) => s.add(tkKey(i.tk))));
    return s;
  }, [rows]);

  // Dashboard filters (date / courier / payment). activeTks above still
  // uses ALL rows so the TK lock never depends on the filter.
  const scoped = useMemo(() => {
    const start = deliveryRangeStart(range);
    return rows.filter((r) => {
      if (start) {
        const t = new Date(r.requested_at);
        if (Number.isNaN(t.getTime()) || t < start) return false;
      }
      if (courierF && (r.driver || "Unassigned") !== courierF) return false;
      if (payF && (r.payment_type || "wallet") !== payF) return false;
      return true;
    });
  }, [rows, range, courierF, payF]);

  const courierOptions = useMemo(
    () => [...new Set(rows.map((r) => r.driver || "Unassigned"))].sort(),
    [rows],
  );
  const stats = useMemo(
    () => computeDeliveryStats(scoped, range),
    [scoped, range],
  );
  const filtered = range !== "30d" || !!courierF || !!payF;

  const counts = useMemo(() => {
    const c = { All: scoped.length };
    DELIVERY_STATUSES.forEach(
      (s) => (c[s] = scoped.filter((r) => r.status === s).length),
    );
    return c;
  }, [scoped]);

  const waiting = useMemo(
    () =>
      packages.filter(
        (p) => p.status === "Inbound Warehouse" && !activeTks.has(tkKey(p.tk)),
      ).length +
      airReadyAll.filter(
        (r) => !activeTks.has(tkKey(airDeliveryKey(r.order_id))),
      ).length,
    [packages, activeTks, airReadyAll],
  );

  const shown = useMemo(() => {
    const list = scoped.filter(
      (r) =>
        (tab === "All" || r.status === tab) &&
        deliveryMatches(r, searchBy, search),
    );
    const t = (r) => new Date(r.requested_at).getTime() || 0;
    return list.sort((x, y) => (newestFirst ? t(y) - t(x) : t(x) - t(y)));
  }, [scoped, tab, search, searchBy, newestFirst]);

  async function submitRequest(d, items) {
    if (!canCreate) throw new Error("អ្នកគ្មានសិទ្ធិ Request Delivery ទេ");
    const created = await create({ ...d, requested_by: operator }, items);
    emitCBToast(
      "ok",
      "Delivery requested",
      `${created.delivery_no} · ${items.length} TK`,
    );
    // a fresh request starts as Pending → jump straight to it
    setTab("Pending");
    setReport("pending");
  }

  async function doDispatch(row, driver) {
    await patch(row.id, {
      status: "In Delivery",
      driver,
      dispatched_at: new Date().toISOString(),
    });
    emitCBToast("ok", "In Delivery", row.delivery_no);
  }

  async function doDelivered(row) {
    await patch(row.id, {
      status: "Delivered",
      delivered_at: new Date().toISOString(),
    });
    for (const i of row.items || []) {
      if (isAirDeliveryItem(i.tk)) {
        // AIR (Indonesia) order → Complete Order
        try {
          await completeAirOrderByDelivery(
            deliveryItemLabel(i.tk),
            operator,
            `Delivered ${row.delivery_no}`,
          );
        } catch {
          /* the delivery itself is already recorded */
        }
        continue;
      }
      const values = { tk: i.tk, status: "Completed" };
      const p = packages.find((x) => tkKey(x.tk) === tkKey(i.tk));
      // Cash collected at the door settles the shipping fee.
      if (p && shippingFeeOf(p).state === "due")
        values.paid_amount = p.freight_fee;
      try {
        await upsertPackage(values);
        logStatus(i.tk, "Completed", operator, `Delivered ${row.delivery_no}`);
      } catch {
        /* the delivery itself is already recorded */
      }
    }
    emitCBToast("ok", "Delivered", row.delivery_no);
  }

  async function doCancel(row, reason) {
    await patch(row.id, { status: "Cancelled", cancel_reason: reason });
  }

  const columns = [
    {
      key: "delivery_no",
      label: "Delivery No",
      render: (r) => (
        <button
          type="button"
          onClick={() => setDetail(r)}
          className="font-medium text-signal-blue hover:underline"
        >
          {r.delivery_no}
        </button>
      ),
    },
    {
      key: "customer",
      label: "Customer",
      render: (r) => (
        <div className="leading-tight">
          <div className="font-medium">{r.customer_name}</div>
          <div className="text-[11px] text-ink-600/55">{r.customer_code}</div>
        </div>
      ),
    },
    {
      key: "address",
      label: "Address",
      render: (r) => (
        <div className="max-w-[240px] truncate" title={r.address_text}>
          {r.address_text || "—"}
        </div>
      ),
    },
    { key: "tks", label: "TKs", render: (r) => (r.items || []).length },
    {
      key: "payment",
      label: "Payment",
      render: (r) => (r.payment_type === "cod" ? "COD" : "Wallet"),
    },
    {
      key: "cash",
      label: "Cash to collect",
      render: (r) => money(r.cash_to_collect),
    },
    {
      key: "status",
      label: "Status",
      render: (r) => <DeliveryStatusBadge status={r.status} />,
    },
    {
      key: "requested_at",
      label: "Requested",
      render: (r) => formatIso(r.requested_at),
    },
  ];

  const actions = canEdit
    ? (r) => (
        <div className="flex gap-1.5 justify-end">
          {r.status === "Pending" && (
            <>
              <button
                type="button"
                className={CT_BTN_PRIMARY + " !px-2.5 !py-1 !text-xs"}
                onClick={() => setDispatch(r)}
              >
                Dispatch
              </button>
              <button
                type="button"
                className={CT_BTN_DANGER + " !px-2.5 !py-1 !text-xs"}
                onClick={() => setConfirm({ row: r, kind: "cancel" })}
              >
                Cancel
              </button>
            </>
          )}
          {r.status === "In Delivery" && (
            <>
              <button
                type="button"
                className={CT_BTN_OK + " !px-2.5 !py-1 !text-xs"}
                onClick={() => setConfirm({ row: r, kind: "done" })}
              >
                Delivered
              </button>
              <button
                type="button"
                className={CT_BTN_DANGER + " !px-2.5 !py-1 !text-xs"}
                onClick={() => setConfirm({ row: r, kind: "cancel" })}
              >
                Cancel
              </button>
            </>
          )}
        </div>
      )
    : undefined;

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <h1 className="font-display font-bold text-xl text-ink-900">
          Delivery Dashboard
        </h1>
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={reload}
            title="Refresh"
            className="p-2 rounded-md text-ink-600/60 hover:bg-mist-100 hover:text-ink-900"
          >
            <Icons.RefreshCw size={15} />
          </button>
          {canCreate && (
            <button
              type="button"
              onClick={() => setDrawer(true)}
              className={CT_BTN_PRIMARY}
            >
              <Plus size={14} /> Request Delivery
            </button>
          )}
        </div>
      </div>

      <div className={CT_CARD + " px-4 py-3 flex items-center gap-2 flex-wrap"}>
        <Icons.CalendarDays size={15} className="text-signal-blue" />
        <select
          value={range}
          onChange={(e) => setRange(e.target.value)}
          className={INPUT_CLS + " !w-auto !py-1.5"}
        >
          {DELIVERY_RANGES.map((r) => (
            <option key={r.key} value={r.key}>
              Requested: {r.label}
            </option>
          ))}
        </select>
        <select
          value={courierF}
          onChange={(e) => setCourierF(e.target.value)}
          className={INPUT_CLS + " !w-auto !py-1.5"}
        >
          <option value="">All couriers</option>
          {courierOptions.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
        <select
          value={payF}
          onChange={(e) => setPayF(e.target.value)}
          className={INPUT_CLS + " !w-auto !py-1.5"}
        >
          <option value="">All payments</option>
          <option value="wallet">Wallet</option>
          <option value="cod">COD</option>
        </select>
        {filtered && (
          <button
            type="button"
            onClick={() => {
              setRange("30d");
              setCourierF("");
              setPayF("");
            }}
            className="inline-flex items-center gap-1 text-sm font-medium text-signal-red bg-signal-red/10 hover:bg-signal-red/15 rounded-md px-3 py-1.5"
          >
            <X size={13} /> Clear
          </button>
        )}
      </div>

      <DeliveryReportCards
        active={report}
        pending={stats.pending}
        onPick={(k) => {
          if (k === "all") setTab("All");
          if (k === "pending") setTab("Pending");
          setReport((cur) => (cur === k ? null : k));
        }}
      />

      {/* Overview (default): summary + fee + per-day chart only */}
      {report === null && (
        <>
          <DeliverySummaryCard s={stats} waiting={waiting} />
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-5 items-start">
            <DeliveryFeeByPayment wallet={stats.wallet} cod={stats.cod} />
            <DeliveryPerDayChart data={stats.perDay} />
          </div>
        </>
      )}

      {/* Separate sections — shown only after clicking the menu card */}
      {report === "couriers" && (
        <DeliveryCourierCard
          couriers={stats.couriers}
          expanded
          onClose={() => setReport(null)}
        />
      )}
      {report === "sales" && (
        <DeliverySalesReport rows={scoped} onClose={() => setReport(null)} />
      )}

      {error && (
        <div className="flex items-center gap-2 text-sm text-signal-red bg-signal-red/10 rounded-md px-3 py-2">
          <TriangleAlert size={14} className="shrink-0" />
          {error}
        </div>
      )}

      {(report === "all" || report === "pending") && (
        <div id="delivery-list" className={CT_CARD}>
          <div className="flex items-center justify-between flex-wrap gap-3 px-4 pt-3 border-b border-mist-200">
            <div className="flex gap-1 overflow-x-auto">
              {["All", ...DELIVERY_STATUSES].map((t) => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTab(t)}
                  className={`px-3 py-2 text-sm whitespace-nowrap border-b-2 -mb-px ${tab === t ? "border-signal-blue text-signal-blue font-medium" : "border-transparent text-ink-600/60 hover:text-ink-900"}`}
                >
                  {t} <span className="text-xs opacity-60">{counts[t]}</span>
                </button>
              ))}
            </div>
            <div className="pb-2 flex items-center gap-2 flex-wrap">
              <DeliverySearchBar
                field={searchBy}
                setField={setSearchBy}
                value={search}
                setValue={setSearch}
              />
              <button
                type="button"
                onClick={() => setNewestFirst((v) => !v)}
                className="inline-flex items-center gap-1.5 text-sm text-ink-600/70 hover:text-ink-900 px-2 py-2 whitespace-nowrap"
              >
                <Icons.ArrowUpDown size={14} />
                {newestFirst ? "Newest first" : "Oldest first"}
              </button>
            </div>
          </div>
          {search.trim() && (
            <div className="px-4 py-2 text-xs text-ink-600/60 border-b border-mist-200">
              {shown.length} result{shown.length === 1 ? "" : "s"} for “
              {search.trim()}”
            </div>
          )}
          <DataTable
            columns={columns}
            rows={shown}
            loading={loading}
            rowActions={actions}
          />
          {!loading && shown.length === 0 && (
            <div className="text-center text-sm text-ink-600/55 py-10">
              មិនមានទិន្នន័យ Delivery ទេ
            </div>
          )}
        </div>
      )}

      <RequestDeliveryDrawer
        open={drawer}
        onClose={() => setDrawer(false)}
        activeTks={activeTks}
        onSubmit={submitRequest}
      />
      <DeliveryDetailModal row={detail} onClose={() => setDetail(null)} />
      <DeliveryDispatchModal
        row={dispatch}
        onClose={() => setDispatch(null)}
        onConfirm={doDispatch}
      />
      <ConfirmModal
        open={!!confirm}
        title={
          confirm?.kind === "done" ? "Mark as Delivered" : "Cancel Delivery"
        }
        message={
          confirm?.kind === "done"
            ? `បញ្ជាក់ថា ${confirm?.row?.delivery_no} បានដឹកដល់ហើយ? TK ទាំងអស់នឹងប្តូរទៅ Completed។`
            : `បោះបង់ ${confirm?.row?.delivery_no}? TK នឹងអាច Request ម្តងទៀតបាន។`
        }
        confirmLabel={
          confirm?.kind === "done" ? "Delivered" : "Cancel Delivery"
        }
        danger={confirm?.kind === "cancel"}
        askReason={confirm?.kind === "cancel"}
        onConfirm={async (reason) => {
          if (confirm.kind === "done") await doDelivered(confirm.row);
          else {
            if (!String(reason || "").trim())
              throw new Error("សូមបញ្ចូលមូលហេតុ");
            await doCancel(confirm.row, reason.trim());
          }
        }}
        onClose={() => setConfirm(null)}
      />
    </div>
  );
}

// ============================================================
// pages/CustomerRecovery.jsx — Archived ("deleted") customers.
// Archiving (archive_customer RPC) keeps the customer identity and every
// order / wallet / address / TK record, and blocks login. Restore and Change
// Phone run through the `customer-recovery` Edge Function (server-side
// permission checks, identity attestation, OTP for new numbers).
// ============================================================
const CUSTOMER_RECOVERY_FUNCTION = "customer-recovery";
// Privileged recovery actions run in the Edge Function (permission re-checked
// server-side); the browser never touches the service-role key.
async function callCustomerRecovery(body) {
  if (!supabase) throw new Error("Supabase is not connected.");
  const { data: session } = await supabase.auth.getSession();
  const { data, error } = await supabase.functions.invoke(
    CUSTOMER_RECOVERY_FUNCTION,
    {
      body,
      headers: { Authorization: `Bearer ${session.session?.access_token}` },
    },
  );
  if (error)
    throw new Error(await edgeFnErrorMessage(error, "Request failed."));
  if (data?.error) throw new Error(data.error);
  return data;
}
const CR_NEW_NUMBER_CHECKS = [
  ["called_new_number", "I called the new number and spoke to the customer"],
  [
    "customer_contacted_from_new_number",
    "The customer contacted us from the new number",
  ],
  ["in_person", "The customer showed the new number in person"],
];
const CR_VERIFY_METHODS = [
  ["id_document", "ID document checked"],
  ["video_call", "Video call"],
  ["known_account_details", "Account details confirmed"],
  ["in_person", "In person"],
];

const CR_PAGE_SIZE = 20;
const CR_FILTERS = [
  ["archived", "Archived"],
  ["restored", "Restored"],
  ["active", "Active"],
  ["purged", "Permanently Deleted"],
];

// Mirrors public.normalize_phone() in the database (Cambodia-first).
function crNormalizePhone(raw) {
  let d = String(raw || "").replace(/\D/g, "");
  if (!d) return "";
  if (d.startsWith("00")) d = d.slice(2);
  if (d.startsWith("8550")) d = "855" + d.slice(4);
  if (d.startsWith("855")) return d;
  if (d.startsWith("0")) return "855" + d.slice(1);
  if (d.length >= 8 && d.length <= 9) return "855" + d;
  return d;
}

function CustomerRecoveryPage() {
  const { user } = useAuth();
  const canView = hasPermission(user, "customer.recovery.view");
  const isSuper = user?.role === SUPER_ADMIN;
  const [filter, setFilter] = useState("archived");
  const [q, setQ] = useState("");
  const [term, setTerm] = useState("");
  const [page, setPage] = useState(0);
  const [state, setState] = useState({
    loading: true,
    rows: [],
    total: 0,
    error: "",
  });
  const [detail, setDetail] = useState(null);
  const [retention, setRetention] = useState({ loaded: false, days: null });
  const [retentionDraft, setRetentionDraft] = useState("");
  const [retentionMsg, setRetentionMsg] = useState("");
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    const t = setTimeout(() => {
      setTerm(q.trim());
      setPage(0);
    }, 300);
    return () => clearTimeout(t);
  }, [q]);
  useEffect(() => {
    setPage(0);
  }, [filter]);

  useEffect(() => {
    if (!supabase || !canView) return;
    supabase
      .from("customer_recovery_settings")
      .select("retention_days")
      .eq("id", 1)
      .maybeSingle()
      .then(({ data }) => {
        setRetention({ loaded: true, days: data?.retention_days ?? null });
        setRetentionDraft(
          data?.retention_days == null ? "" : String(data.retention_days),
        );
      });
  }, [canView]);

  useEffect(() => {
    let alive = true;
    if (!supabase || !canView) {
      setState({ loading: false, rows: [], total: 0, error: "" });
      return;
    }
    setState((s) => ({ ...s, loading: true, error: "" }));
    (async () => {
      let query = supabase
        .from("customers")
        .select(
          "id, customer_code, name, phone, email, status, created_at, archived_at, archived_by_name, archive_reason, status_before_archive, restored_at",
          { count: "exact" },
        );
      if (filter === "archived") query = query.eq("status", "archived");
      else if (filter === "purged") query = query.eq("status", "purged");
      else if (filter === "restored")
        query = query.not("restored_at", "is", null).neq("status", "archived");
      else query = query.eq("status", "active");
      const safe = term.replace(/[,()%*\\]/g, " ").trim();
      if (safe) {
        const parts = [
          `name.ilike.%${safe}%`,
          `customer_code.ilike.%${safe}%`,
          `email.ilike.%${safe}%`,
          `phone.ilike.%${safe}%`,
        ];
        const norm = crNormalizePhone(safe);
        if (safe.replace(/\D/g, "").length >= 6 && norm)
          parts.push(`phone_normalized.eq.${norm}`);
        query = query.or(parts.join(","));
      }
      const from = page * CR_PAGE_SIZE;
      const { data, error, count } = await query
        .order(filter === "archived" ? "archived_at" : "created_at", {
          ascending: false,
        })
        .range(from, from + CR_PAGE_SIZE - 1);
      if (!alive) return;
      setState({
        loading: false,
        rows: data || [],
        total: count || 0,
        error: error ? error.message || "Unable to load customers." : "",
      });
    })();
    return () => {
      alive = false;
    };
  }, [filter, term, page, canView, reloadKey]);

  const saveRetention = async () => {
    setRetentionMsg("");
    const raw = retentionDraft.trim();
    const days = raw === "" ? null : Number(raw);
    if (days !== null && (!Number.isInteger(days) || days < 0)) {
      setRetentionMsg(
        "Enter a whole number of days, or leave empty to keep forever.",
      );
      return;
    }
    const { error } = await supabase
      .from("customer_recovery_settings")
      .update({
        retention_days: days,
        updated_by: user?.id || null,
        updated_at: new Date().toISOString(),
      })
      .eq("id", 1);
    if (error) {
      setRetentionMsg(error.message || "Unable to save.");
      return;
    }
    setRetention({ loaded: true, days });
    setRetentionMsg("Saved.");
  };

  if (!canView)
    return (
      <div className="mx-auto max-w-[900px] p-7 text-sm text-slate-600">
        {NO_PERM_MSG}
      </div>
    );

  const pages = Math.max(1, Math.ceil(state.total / CR_PAGE_SIZE));
  const statusTone = (st) =>
    st === "archived"
      ? "bg-amber-50 text-amber-700 border-amber-200"
      : st === "purged"
        ? "bg-slate-100 text-slate-600 border-slate-200"
        : "bg-emerald-50 text-emerald-700 border-emerald-200";

  return (
    <div className="mx-auto max-w-[1300px] space-y-5 p-5 md:p-7">
      <div>
        <h1 className="cb-page-title flex items-center gap-2 text-2xl font-bold text-slate-900">
          <Icons.ArchiveRestore size={24} className="text-slate-500" /> Customer
          Recovery
        </h1>
        <p className="mt-1 text-sm text-slate-500">
          Archived customers keep their ID, orders, wallet, addresses and
          history. They cannot log in until restored.
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
        <div className="flex flex-wrap gap-1">
          {CR_FILTERS.map(([key, label]) => (
            <button
              key={key}
              type="button"
              onClick={() => setFilter(key)}
              className={`rounded-md px-3 py-1.5 text-xs font-medium border ${
                filter === key
                  ? "bg-slate-900 text-white border-slate-900"
                  : "bg-white text-slate-700 border-slate-200 hover:bg-slate-50"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search name, phone, customer ID or email"
          className="min-w-[220px] flex-1 rounded-md border border-slate-200 px-3 py-2 text-sm"
        />
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs uppercase text-slate-500">
              <tr>
                <th className="px-4 py-3">Customer</th>
                <th className="px-4 py-3">ID</th>
                <th className="px-4 py-3">Phone</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Archived</th>
                <th className="px-4 py-3">Reason</th>
                <th className="px-4 py-3">By</th>
                <th className="px-4 py-3" />
              </tr>
            </thead>
            <tbody>
              {state.loading ? (
                <tr>
                  <td colSpan={8} className="px-4 py-6 text-slate-400">
                    Loading...
                  </td>
                </tr>
              ) : state.error ? (
                <tr>
                  <td colSpan={8} className="px-4 py-6 text-signal-red">
                    {state.error}
                  </td>
                </tr>
              ) : state.rows.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-4 py-6 text-slate-400">
                    No customers found.
                  </td>
                </tr>
              ) : (
                state.rows.map((r) => (
                  <tr key={r.id} className="border-t border-slate-100">
                    <td className="px-4 py-3 font-semibold text-slate-800">
                      {r.name || "—"}
                    </td>
                    <td className="px-4 py-3">{r.customer_code || "—"}</td>
                    <td className="px-4 py-3">{r.phone || "—"}</td>
                    <td className="px-4 py-3">
                      <span
                        className={`rounded-full border px-2 py-0.5 text-[11px] font-medium ${statusTone(r.status)}`}
                      >
                        {r.status || "—"}
                      </span>
                    </td>
                    <td className="px-4 py-3">{cdDate(r.archived_at)}</td>
                    <td className="px-4 py-3 max-w-[220px] truncate">
                      {r.archive_reason || "—"}
                    </td>
                    <td className="px-4 py-3">{r.archived_by_name || "—"}</td>
                    <td className="px-4 py-3 text-right">
                      <button
                        type="button"
                        onClick={() => setDetail(r)}
                        className="text-xs font-medium text-blue-700 hover:underline"
                      >
                        View Details
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
        <div className="flex items-center justify-between border-t border-slate-100 px-4 py-3 text-xs text-slate-500">
          <span>
            {state.total} result{state.total === 1 ? "" : "s"} · page {page + 1}{" "}
            / {pages}
          </span>
          <div className="flex gap-1">
            <button
              type="button"
              disabled={page === 0}
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              className="rounded-md border border-slate-200 px-3 py-1.5 disabled:opacity-40"
            >
              Prev
            </button>
            <button
              type="button"
              disabled={page + 1 >= pages}
              onClick={() => setPage((p) => p + 1)}
              className="rounded-md border border-slate-200 px-3 py-1.5 disabled:opacity-40"
            >
              Next
            </button>
          </div>
        </div>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-4 text-sm shadow-sm">
        <div className="font-semibold text-slate-800">Retention policy</div>
        <p className="mt-1 text-xs text-slate-500">
          How long archived accounts are kept before permanent removal can be
          considered. Empty = keep forever. Permanent removal is never automatic
          and needs its own permission.
        </p>
        {retention.loaded &&
          (isSuper ? (
            <div className="mt-2 flex flex-wrap items-center gap-2">
              <input
                value={retentionDraft}
                onChange={(e) => setRetentionDraft(e.target.value)}
                placeholder="days (empty = forever)"
                className="w-48 rounded-md border border-slate-200 px-3 py-1.5 text-sm"
              />
              <button
                type="button"
                onClick={saveRetention}
                className="rounded-md bg-slate-900 px-3 py-1.5 text-xs font-medium text-white"
              >
                Save
              </button>
              {retentionMsg && (
                <span className="text-xs text-slate-500">{retentionMsg}</span>
              )}
            </div>
          ) : (
            <div className="mt-2 text-xs text-slate-600">
              Current:{" "}
              {retention.days == null
                ? "keep forever"
                : `${retention.days} days`}
            </div>
          ))}
      </div>

      {detail && (
        <CustomerRecoveryDetail
          row={detail}
          user={user}
          onClose={() => setDetail(null)}
          onChanged={() => {
            setDetail(null);
            setReloadKey((k) => k + 1);
          }}
        />
      )}
    </div>
  );
}

function CustomerRecoveryDetail({ row, user, onClose, onChanged }) {
  const [counts, setCounts] = useState(null);
  const [modal, setModal] = useState(null); // "restore" | "phone"
  const [audit, setAudit] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const count = async (table) => {
        const { count: n, error } = await supabase
          .from(table)
          .select("id", { count: "exact", head: true })
          .eq("customer_id", row.id);
        return error ? "—" : n;
      };
      const [tk, cn, wallet, addr] = await Promise.all([
        count("packages"),
        count("cn_orders"),
        count("wallet_transactions"),
        count("customer_addresses"),
      ]);
      const { data } = await supabase
        .from("customer_recovery_audit")
        .select("action, actor_name, reason, created_at")
        .eq("customer_id", row.id)
        .order("created_at", { ascending: false })
        .limit(10);
      if (!alive) return;
      setCounts({ tk, cn, wallet, addr });
      setAudit(data || []);
    })();
    return () => {
      alive = false;
    };
  }, [row.id]);

  const isArchived = row.status === "archived";
  const isPurged = row.status === "purged";
  const isSuperUser = user?.role === SUPER_ADMIN;
  const canRestore = isArchived && hasPermission(user, "customer.restore");
  const canPhone =
    !isArchived && !isPurged && hasPermission(user, "customer.phone_change");

  const Field = ({ label, children }) => (
    <div>
      <div className="text-[11px] uppercase text-slate-400">{label}</div>
      <div className="text-sm text-slate-800">{children || "—"}</div>
    </div>
  );

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink-900/40 px-4"
      onClick={onClose}
    >
      {modal === "restore" && (
        <CustomerRestoreModal
          row={row}
          onClose={() => setModal(null)}
          onDone={onChanged}
        />
      )}
      {modal === "phone" && (
        <CustomerPhoneChangeModal
          row={row}
          isSuper={isSuperUser}
          onClose={() => setModal(null)}
          onDone={onChanged}
        />
      )}
      <div
        onClick={(e) => e.stopPropagation()}
        className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-md bg-white shadow-lg"
      >
        <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
          <h3 className="font-display text-lg font-bold">{row.name || "—"}</h3>
          <button type="button" onClick={onClose} className="text-slate-400">
            ✕
          </button>
        </div>
        <div className="space-y-4 px-5 py-4">
          <div className="grid grid-cols-2 gap-3">
            <Field label="Customer ID">{row.customer_code}</Field>
            <Field label="Status">{row.status}</Field>
            <Field label="Phone">{row.phone}</Field>
            <Field label="Email">{row.email}</Field>
            <Field label="Archived on">{cdDate(row.archived_at)}</Field>
            <Field label="Archived by">{row.archived_by_name}</Field>
            <Field label="Reason">{row.archive_reason}</Field>
            <Field label="Status before archive">
              {row.status_before_archive}
            </Field>
          </div>
          <div>
            <div className="mb-1 text-[11px] uppercase text-slate-400">
              Preserved records
            </div>
            <div className="grid grid-cols-4 gap-2 text-center text-xs">
              {[
                ["TK / Packages", counts?.tk],
                ["CN Orders", counts?.cn],
                ["Wallet tx", counts?.wallet],
                ["Addresses", counts?.addr],
              ].map(([label, v]) => (
                <div
                  key={label}
                  className="rounded-md border border-slate-200 px-2 py-2"
                >
                  <div className="text-base font-semibold text-slate-800">
                    {counts ? v : "…"}
                  </div>
                  <div className="text-slate-500">{label}</div>
                </div>
              ))}
            </div>
          </div>
          {audit.length > 0 && (
            <div>
              <div className="mb-1 text-[11px] uppercase text-slate-400">
                Audit trail
              </div>
              <ul className="space-y-1 text-xs text-slate-600">
                {audit.map((a, i) => (
                  <li key={i}>
                    {cdDate(a.created_at)} · <b>{a.action}</b>
                    {a.actor_name ? ` · ${a.actor_name}` : ""}
                    {a.reason ? ` · ${a.reason}` : ""}
                  </li>
                ))}
              </ul>
            </div>
          )}
          <div>
            <div className="flex flex-wrap gap-2">
              {canRestore && (
                <button
                  type="button"
                  onClick={() => setModal("restore")}
                  className="rounded-md bg-slate-900 px-3 py-1.5 text-xs font-medium text-white"
                >
                  Restore Account
                </button>
              )}
              {canPhone && (
                <button
                  type="button"
                  onClick={() => setModal("phone")}
                  className="rounded-md border border-slate-300 px-3 py-1.5 text-xs font-medium text-slate-800"
                >
                  Change Phone Number
                </button>
              )}
            </div>
            <p className="mt-2 text-[11px] text-slate-400">
              {isArchived
                ? "Restore the account first; then use Reset Password on the Customers page if the customer forgot it. Phone changes need an active account."
                : `Password reset: use Reset Password on the Customers page. ${
                    isSuperUser
                      ? "As Super Admin you can change the phone number directly after verifying the customer."
                      : "Changing the phone number needs an OTP sent to the new number."
                  }`}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

// Identity-verification block shared by Restore and Change Phone. The admin
// attests the check; the attestation is stored in the audit trail.
function CrVerifyFields({ v, setV }) {
  return (
    <div className="space-y-2 rounded-md border border-slate-200 p-3">
      <div className="text-xs font-semibold text-slate-700">
        Customer identity verification (required)
      </div>
      <select
        value={v.method}
        onChange={(e) => setV({ ...v, method: e.target.value })}
        className="w-full rounded-md border border-slate-200 px-3 py-2 text-sm"
      >
        <option value="">How was the customer verified?</option>
        {CR_VERIFY_METHODS.map(([k, label]) => (
          <option key={k} value={k}>
            {label}
          </option>
        ))}
      </select>
      <textarea
        value={v.note}
        onChange={(e) => setV({ ...v, note: e.target.value })}
        rows={2}
        maxLength={500}
        placeholder="What did you check? (e.g. matched ID card, last order, address)"
        className="w-full rounded-md border border-slate-200 px-3 py-2 text-sm"
      />
      <label className="flex items-start gap-2 text-xs text-slate-700">
        <input
          type="checkbox"
          checked={v.confirmed}
          onChange={(e) => setV({ ...v, confirmed: e.target.checked })}
          className="mt-0.5"
        />
        I confirm this person is the owner of the account.
      </label>
    </div>
  );
}

function CustomerRestoreModal({ row, onClose, onDone }) {
  const [v, setV] = useState({ method: "", note: "", confirmed: false });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState(null);
  const submit = async () => {
    setBusy(true);
    setError("");
    try {
      const res = await callCustomerRecovery({
        action: "restore",
        customer_code: row.customer_code,
        verification: v,
      });
      setResult(res);
      emitCBToast("ok", "Restored", `${row.customer_code} was restored.`);
    } catch (err) {
      setError(err.message || "Restore failed.");
    } finally {
      setBusy(false);
    }
  };
  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center bg-ink-900/40 px-4"
      onClick={(e) => {
        e.stopPropagation();
        if (!busy) result ? onDone() : onClose();
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-md space-y-3 rounded-md bg-white p-5 shadow-lg"
      >
        <h3 className="font-display text-lg font-bold">
          Restore {row.customer_code}
        </h3>
        {result ? (
          <>
            <p className="text-sm text-slate-700">
              Account restored. Orders, wallet and history are unchanged.
            </p>
            {result.needs_password_reset && (
              <p className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                The login account had to be re-created. Set a new password with
                Reset Password on the Customers page before the customer logs
                in.
              </p>
            )}
            <div className="text-right">
              <button
                type="button"
                onClick={onDone}
                className="rounded-md bg-slate-900 px-4 py-2 text-sm font-medium text-white"
              >
                Done
              </button>
            </div>
          </>
        ) : (
          <>
            <p className="text-sm text-slate-600">
              Restores {row.name || "this customer"} with the original ID and
              all records. Nothing is re-created or replayed.
            </p>
            <CrVerifyFields v={v} setV={setV} />
            {error && <p className="text-xs text-signal-red">{error}</p>}
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={onClose}
                disabled={busy}
                className="px-4 py-2 text-sm text-slate-700"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={submit}
                disabled={busy}
                className="rounded-md bg-slate-900 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
              >
                {busy ? "Restoring..." : "Restore"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function CustomerPhoneChangeModal({ row, onClose, onDone, isSuper = false }) {
  const [v, setV] = useState({ method: "", note: "", confirmed: false });
  const [nc, setNc] = useState("");
  const [newPhone, setNewPhone] = useState("");
  const [challenge, setChallenge] = useState(null);
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [done, setDone] = useState(false);
  const run = async (fn) => {
    setBusy(true);
    setError("");
    try {
      await fn();
    } catch (err) {
      setError(err.message || "Request failed.");
    } finally {
      setBusy(false);
    }
  };
  // Super Admin only: no SMS code; the admin attests both checks (audited).
  const direct = () =>
    run(async () => {
      await callCustomerRecovery({
        action: "phone_direct",
        customer_code: row.customer_code,
        new_phone: newPhone.trim(),
        verification: v,
        new_number_check: nc,
      });
      setDone(true);
      emitCBToast("ok", "Phone changed", `${row.customer_code} phone updated.`);
    });
  const request = () =>
    run(async () => {
      const res = await callCustomerRecovery({
        action: "phone_request",
        customer_code: row.customer_code,
        new_phone: newPhone.trim(),
        verification: v,
      });
      setChallenge(res);
    });
  const confirm = () =>
    run(async () => {
      await callCustomerRecovery({
        action: "phone_confirm",
        challenge_id: challenge.challenge_id,
        code: code.trim(),
      });
      setDone(true);
      emitCBToast("ok", "Phone changed", `${row.customer_code} phone updated.`);
    });
  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center bg-ink-900/40 px-4"
      onClick={(e) => {
        e.stopPropagation();
        if (!busy) done ? onDone() : onClose();
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-md space-y-3 rounded-md bg-white p-5 shadow-lg"
      >
        <h3 className="font-display text-lg font-bold">
          Change phone · {row.customer_code}
        </h3>
        {done ? (
          <>
            <p className="text-sm text-slate-700">
              Phone number updated. The customer now logs in with the new number
              and the same password.
            </p>
            <div className="text-right">
              <button
                type="button"
                onClick={onDone}
                className="rounded-md bg-slate-900 px-4 py-2 text-sm font-medium text-white"
              >
                Done
              </button>
            </div>
          </>
        ) : isSuper ? (
          <>
            <div className="text-xs text-slate-500">
              Current number: <b>{row.phone || "—"}</b>
            </div>
            <input
              value={newPhone}
              onChange={(e) => setNewPhone(e.target.value)}
              placeholder="New phone number"
              className="w-full rounded-md border border-slate-200 px-3 py-2 text-sm"
            />
            <CrVerifyFields v={v} setV={setV} />
            <div className="space-y-2 rounded-md border border-slate-200 p-3">
              <div className="text-xs font-semibold text-slate-700">
                New number check (required)
              </div>
              <select
                value={nc}
                onChange={(e) => setNc(e.target.value)}
                className="w-full rounded-md border border-slate-200 px-3 py-2 text-sm"
              >
                <option value="">How did you check the new number?</option>
                {CR_NEW_NUMBER_CHECKS.map(([k, label]) => (
                  <option key={k} value={k}>
                    {label}
                  </option>
                ))}
              </select>
            </div>
            <p className="text-[11px] text-slate-400">
              Super Admin change: no SMS code is sent. The customer logs in with
              the new number and the same password. Your name, both checks and
              the masked numbers are saved in the audit trail.
            </p>
            {error && <p className="text-xs text-signal-red">{error}</p>}
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={onClose}
                disabled={busy}
                className="px-4 py-2 text-sm text-slate-700"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={direct}
                disabled={busy || !newPhone.trim() || !nc}
                className="rounded-md bg-slate-900 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
              >
                {busy ? "Changing..." : "Change phone"}
              </button>
            </div>
          </>
        ) : !challenge ? (
          <>
            <div className="text-xs text-slate-500">
              Current number: <b>{row.phone || "—"}</b>
            </div>
            <input
              value={newPhone}
              onChange={(e) => setNewPhone(e.target.value)}
              placeholder="New phone number"
              className="w-full rounded-md border border-slate-200 px-3 py-2 text-sm"
            />
            <CrVerifyFields v={v} setV={setV} />
            <p className="text-[11px] text-slate-400">
              A 6-digit code is sent to the new number. Enter it on the next
              step to prove the customer controls that number.
            </p>
            {error && <p className="text-xs text-signal-red">{error}</p>}
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={onClose}
                disabled={busy}
                className="px-4 py-2 text-sm text-slate-700"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={request}
                disabled={busy || !newPhone.trim()}
                className="rounded-md bg-slate-900 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
              >
                {busy ? "Sending..." : "Send code"}
              </button>
            </div>
          </>
        ) : (
          <>
            <p className="text-sm text-slate-600">
              Code sent to <b>{challenge.sent_to}</b>. It expires in 10 minutes.
            </p>
            <input
              value={code}
              onChange={(e) =>
                setCode(e.target.value.replace(/\D/g, "").slice(0, 6))
              }
              inputMode="numeric"
              placeholder="6-digit code"
              className="w-full rounded-md border border-slate-200 px-3 py-2 text-sm tracking-widest"
            />
            {error && <p className="text-xs text-signal-red">{error}</p>}
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={onClose}
                disabled={busy}
                className="px-4 py-2 text-sm text-slate-700"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={confirm}
                disabled={busy || code.length !== 6}
                className="rounded-md bg-slate-900 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
              >
                {busy ? "Verifying..." : "Confirm change"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ============================================================
// pages/DeletedAccounts.jsx — Orders whose owner account was deleted.
// The DB trigger `customers_before_delete` keeps every TK / AIR Order,
// sets customer_id = null and customer = 'Deleted account'. Nothing else
// about the old customer (name, phone, code) is kept.
// ============================================================
const DELETED_ACCOUNT_LABEL = "Deleted account";

function DeletedAccountsPage() {
  const { user } = useAuth();
  const canViewAir = hasPermission(user, "air_order.view");
  const [tab, setTab] = useState("packages");
  const [state, setState] = useState({
    loading: true,
    packages: [],
    air: [],
    error: "",
  });

  useEffect(() => {
    let alive = true;
    (async () => {
      if (!supabase) {
        setState({ loading: false, packages: [], air: [], error: "" });
        return;
      }
      const load = (table) =>
        supabase
          .from(table)
          .select("*")
          .is("customer_id", null)
          .eq("customer", DELETED_ACCOUNT_LABEL)
          .order("created_at", { ascending: false })
          .limit(2000);
      const [p, a] = await Promise.all([
        load("packages"),
        canViewAir ? load("air_orders") : Promise.resolve({ data: [] }),
      ]);
      if (!alive) return;
      setState({
        loading: false,
        packages: p.data || [],
        air: (a.data || []).map(normalizeAirRow),
        error: p.error?.message || a.error?.message || "",
      });
    })();
    return () => {
      alive = false;
    };
  }, [canViewAir]);

  const { loading, packages, air, error } = state;

  const dateCol = {
    key: "updated",
    label: "Last Update",
    search: () => "",
    render: (r) => (
      <div>
        <div className="font-semibold text-slate-800">
          {cdDate(r.updated_at || r.created_at)}
        </div>
        <div className="text-[11px] text-slate-400">
          {cdAgo(r.updated_at || r.created_at)}
        </div>
      </div>
    ),
  };
  const pkgCols = [
    dateCol,
    {
      key: "tk",
      label: "Tracking Number",
      render: (r) => (
        <Link
          to={`/packages/${encodeURIComponent(r.tk)}`}
          className="font-semibold text-blue-700 hover:underline"
        >
          {r.tk}
        </Link>
      ),
    },
    {
      key: "container_no",
      label: "Container",
      render: (r) => r.container_no || "—",
    },
    {
      key: "route",
      label: "Route",
      search: (r) => `${r.origin_wh_code} ${r.dest_branch_code}`,
      render: (r) =>
        `${r.origin_wh_code || "—"} → ${r.dest_branch_code || "—"}`,
    },
    {
      key: "fee",
      label: "Shipping Fee",
      search: () => "",
      render: (r) => <ShippingFeeCell row={r} />,
    },
    {
      key: "status",
      label: "Status",
      search: (r) => pkgDisplayStatus(r),
      render: (r) => <StatusBadge label={pkgDisplayStatus(r) || "—"} />,
    },
  ];
  const airCols = [
    dateCol,
    {
      key: "order_id",
      label: "Shop Order ID",
      render: (r) => (
        <Link
          to={`/air-shipments/${encodeURIComponent(r.order_id)}`}
          className="font-semibold text-blue-700 hover:underline"
        >
          {r.order_id}
        </Link>
      ),
    },
    { key: "tk", label: "Tracking Number", render: (r) => r.tk || "—" },
    { key: "shop_name", label: "Shop", render: (r) => r.shop_name || "—" },
    {
      key: "product_name",
      label: "Product",
      render: (r) => r.product_name || "—",
    },
    {
      key: "status",
      label: "Status",
      search: (r) => r.status,
      render: (r) => <AirStatusBadge status={r.status} />,
    },
  ];
  const tabs = [
    ["packages", "Packages / TK (China)", packages.length],
    ...(canViewAir ? [["air", "AIR · Indonesia", air.length]] : []),
  ];

  return (
    <div className="mx-auto max-w-[1300px] space-y-5 p-5 md:p-7">
      <div>
        <h1 className="cb-page-title flex items-center gap-2 text-2xl font-bold text-slate-900">
          <Icons.UserX size={24} className="text-slate-500" /> Deleted Accounts
        </h1>
        <p className="mt-1 text-sm text-slate-500">
          Orders whose customer account was deleted. They are kept for history
          but have no owner.
        </p>
      </div>
      <div className="flex flex-wrap items-center gap-x-8 gap-y-4 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
        <CdStat label="Total Orders" value={packages.length + air.length} />
        <CdStat label="China (TK)" value={packages.length} />
        {canViewAir && (
          <CdStat
            label="Indo (AIR)"
            value={air.length}
            tone="text-violet-700"
          />
        )}
      </div>
      {error && (
        <p className="rounded-xl border border-red-200 bg-red-50 px-4 py-2 text-sm text-red-600">
          {error}
        </p>
      )}
      <div className="space-y-3">
        <div className="flex gap-1 border-b border-slate-200">
          {tabs.map(([k, label, n]) => (
            <button
              key={k}
              type="button"
              onClick={() => setTab(k)}
              className={`-mb-px inline-flex items-center gap-2 border-b-2 px-4 py-2.5 text-sm font-bold transition ${tab === k ? "border-blue-600 text-blue-700" : "border-transparent text-slate-500 hover:text-slate-800"}`}
            >
              {label}
              <span
                className={`rounded-full px-2 py-0.5 text-[11px] ${tab === k ? "bg-blue-50 text-blue-700" : "bg-slate-100 text-slate-500"}`}
              >
                {n}
              </span>
            </button>
          ))}
        </div>
        {tab === "packages" && (
          <CdTable
            cols={pkgCols}
            rows={packages}
            loading={loading}
            empty="No orders from deleted accounts."
          />
        )}
        {tab === "air" && canViewAir && (
          <CdTable
            cols={airCols}
            rows={air}
            loading={loading}
            empty="No AIR orders from deleted accounts."
          />
        )}
      </div>
    </div>
  );
}

function AdminApp() {
  return (
    <AuthProvider>
      <AdminPrefsProvider>
        <PackageTrackingProvider>
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route
              path="/register"
              element={<Navigate to="/login" replace />}
            />
            <Route
              element={
                <ProtectedRoute>
                  <Layout />
                </ProtectedRoute>
              }
            >
              <Route path="/" element={<Dashboard />} />
              <Route path="/orders/:id" element={<OrderDetail />} />
              <Route path="/cn-orders" element={<CnOrdersPage />} />
              <Route path="/cn-orders/:id" element={<CnOrderDetailPage />} />
              <Route path="/packages/:tk" element={<PackageDetail />} />
              <Route path="/shipment-lookup" element={<ShipmentLookup />} />
              <Route path="/scan-center" element={<ScanCenterPage />} />
              <Route
                path="/process-tracking"
                element={<ProcessTrackingPage />}
              />
              <Route path="/exceptions" element={<ExceptionCenterPage />} />
              <Route path="/wh-arrived" element={<WHArrivedPage />} />
              <Route path="/delivery" element={<DeliveryPage />} />
              <Route path="/sorting" element={<SortingPage />} />
              <Route path="/warehouses" element={<WarehouseManagementPage />} />
              <Route path="/kh-warehouse" element={<KhWarehousePage />} />
              <Route path="/roles" element={<RoleManagementPage />} />
              <Route
                path="/customer-features"
                element={<CustomerFeaturesPage />}
              />
              <Route path="/settings" element={<SettingsPage />} />
              <Route path="/reports" element={<ReportsHubPage />} />
              <Route path="/customers/:code" element={<CustomerDetailPage />} />
              <Route
                path="/deleted-accounts"
                element={<DeletedAccountsPage />}
              />
              <Route
                path="/customer-recovery"
                element={<CustomerRecoveryPage />}
              />
              <Route path="/wallet-top-up" element={<WalletTopUpPage />} />
              <Route path="/reports/:key" element={<ReportsPage />} />
              <Route
                path="/notifications"
                element={<NotificationCenterPage />}
              />
              <Route
                path="/permissions"
                element={<Navigate to="/roles" replace />}
              />
              {OTHER_ROUTES.filter(
                (item) =>
                  ![
                    "/process-tracking",
                    "/exceptions",
                    "/wh-arrived",
                    "/sorting",
                    "/warehouses",
                    "/kh-warehouse",
                    "/roles",
                    "/customer-features",
                    "/deleted-accounts", // custom page above
                    "/customer-recovery", // custom page above
                    "/settings",
                    "/wallet-top-up",
                    "/delivery",
                    "/shipments", // module removed — Container is the only grouping
                    "/air-shipments", // AIR / Indonesia is not part of this deployment
                    "/arrival", // hidden — Containers › Arrived Destination confirms arrival
                  ].includes(item.path),
              ).map((item) => {
                const config = MODULES[item.path];
                return (
                  <Route
                    key={item.path}
                    path={item.path}
                    element={
                      config ? (
                        <ListPage {...config} path={item.path} />
                      ) : (
                        <Placeholder title={item.label} />
                      )
                    }
                  />
                );
              })}
            </Route>
          </Routes>
        </PackageTrackingProvider>
      </AdminPrefsProvider>
    </AuthProvider>
  );
}

